    hit = 2,
    miss = 2,
    growth = 1,
    skill = 1,
    formation = 3,
    painter = "月见",
    cv1 = "暂无",
    desc = "馒头，是历史悠久的中国传统面食，用小麦粉发酵蒸熟而成。形状多为圆形，颜色雪白，口感软香，多作为主食活跃在人们的餐桌上。\n中国人吃馒头的历史至少可以追溯到战国时期。那时候石磨还没有被发明出来，人们仅能用杵臼等工具生产出少量的面粉，因此吃面食的很少，馒头的原型“蒸饼”在战国时多作为祭祀用途。到了汉朝，石磨已经被广泛应用，面食的蒸制做法也流行于中国各地，“馒头”一词第一次出现在文献当中，如《七修类稿》中记载：“馒头本名蛮头。”、《饼赋》有云“三春之初，阴阳交际，寒气既消，温不至热，于时享宴，则曼头宜设。”但汉朝馒头仍是一种高级、奢侈的食品。唐朝开始，馒头的形态变小，被美称为“玉柱”、“灌浆”，作为一种点心为人们熟知。不过那时，带馅的面食也被称为馒头，直到清朝，馒头的称谓才开始出现分野：北方称无馅者为馒头，有馅者为包子，南方则反之，称有馅者为馒头，无馅者为包子，这种习惯上的差异一直延续至今。\n到了现代，人们对食物的营养有更高追求。馒头中含有酵母，是一种可食用的、营养丰富的单细胞微生物，除了蛋白质、碳水化合物、脂类外，还富有多种维生素、矿物质和酶，是非常理想的主食。人们还会在馒头中加入蜂蜜、牛奶或者粗粮，进一步提升馒头的口感与食用价值。\n而为了让这种简单的传统面食更加具有吸引力，人们在它的外形上也动了许多脑筋。在案板上巧手稍动，就可以让馒头带上色彩，或变化成刺猬、兔子的形状。这种制作馒头的智慧，如今已经变成了一种文化符号印刻在所有中国人的基因之中。"
  },
  [2] = {
    order = 2,
    id = 99,
    desc = "白米饭",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 2,
    growth = 1,
    skill = 1,
    formation = 3,
    painter = "月见",
    cv1 = "赤尾ひかる",
    desc = "简单才是最强！simple is best！\n中国以稻米作为主食的历史极其悠久，已被考证的最早的藏有稻谷的遗迹，湖南道县玉蟾岩，已距今8200年历史，且属于人工栽培。\n稻米相比起小麦等其他的谷物，营养价值很高，米饭所包含的营养成分有碳水化合物、蛋白质、脂类、维他命B1、B2、钙、铁、镁、亚铅、食物纤维等，单靠白米饭就几乎能囊括人类日常生活所需的所有营养元素，且可以大量种植大量收获，肠胃容易吸收，是非常理想的主食。\n稻米的传播和收获量的提升是亚洲人口增大的原动力。\n稻米对中国的宗教和文化有非常大的影响，汉字中，关于食物的汉字除了“食字旁”以外，有很多是“米字旁”，如“粮”“籽”“糕”“糖”等，米饭被广泛作为食物的代表。\n在传统节假日或祭奠仪式中，也有大量由稻米制成的食物，如“年糕”，“粽子”，“汤圆”，“八宝饭”等。\n对中国和很多亚洲国家来说，米饭都有非常特殊地位，和各个国家的文化融合在一起，成为了不可分割的一部分。"
  },
  [3] = {
    order = 3,
    id = 102,
    desc = "扬州炒饭",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 2,
    growth = 2,
    skill = 4,
    formation = 4,
    painter = "谷梁顿Grain",
    cv1 = "続木友子",
    desc = "被联合国列入米食谱的著名中国炒饭。\n用料主要有鸡蛋，火腿，蔬菜，虾等。\n虽然名字叫做“扬州”炒饭，但主要分为两种版本，粤式和扬州式。\n扬州式的扬州炒饭据说，在谢讽的《食经》就有“越国食碎金饭”，即是扬州炒饭的前身。相传隋炀帝巡游扬州时将“碎金饭”传入扬州，也就成了有关扬州炒饭最早的记载。扬州炒饭据传是由一名清朝的扬州知府伊秉绶，因罢官而带回原籍福建汀州，在其所著的《留春草堂集》中详细的介绍了扬州炒饭的制作方法。\n而在国外相对有名的是粤式的扬州炒饭。\n粤式的扬州炒饭是清朝光绪年间的广州，一家叫“聚春园”的淮扬菜馆所创作，而后通过香港等地方的华人，带到了世界各地。\n至于扬州炒饭的起源到底是扬州，还是广州。\n此点目前学术界似乎并无定论。于是目前不同的城市，不同的餐馆和饭店，都有各自的“扬州炒饭”。"
  },
  [4] = {
    order = 4,
    id = 106,
    desc = "蛋包饭",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 2,
    skill = 2,
    formation = 3,
    painter = "忍忍包子",
    cv1 = "武田罗梨沙多胡",
    desc = "在日本诞生的西式米饭料理。\n用西式蛋饼包住米饭并且淋上西红柿酱等酱料食用。\n除米饭以外的材料是西式料理常用的食材，制作手法也大部分采用西式料理的手法。所以虽然诞生于日本，又以米饭作为主料，但蛋包饭往往被分类为西餐。\n因此如果按照原产国分类则是“日本料理”，按照技法分类则是“西餐”。\n蛋包饭的诞生距今有100年以上的历史，有不少餐厅至今还在主张自己才是蛋包饭的正统发祥地。其中比较有名的是东京银座的“炼瓦亭”和大阪心斋桥的“北极星”。\n蛋包饭还有不少的可塑性，在日本的中国餐馆，常会提供用蛋饼包住炒饭的“中华风蛋包饭”。在女仆咖啡厅，还有用西红柿酱在蛋饼上画图写字的“萌蛋包饭”。蛋包饭是无论是制作还是食用，都能给人带来快乐的料理。"
  },
  [5] = {
    order = 5,
    id = 107,
    desc = "方包",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 3,
    growth = 2,
    skill = 3,
    formation = 1,
    painter = "绘C",
    cv1 = "内田彩",
    desc = "方包通指切片或未切片的听型白面包。\n将糖、盐、牛奶、水和黄油掺入面粉，做成面团发酵，再将发酵好的面团放入长方形带盖或不带盖的听模，最后经过烤制做成。也可以依据喜好，在制作过程中加入烘焙果干、坚果、粗粮等，常见于欧美式的早餐。\n多数的吃法是将其切片，用烤面包机烤至发出香气，再涂抹上如炼乳、果酱、蜂蜜等佐料，也可将两片面包中加入蔬菜、肉类和煎蛋制成三明治。\n方包口感松软、香味十足，其中含有蛋白质、脂肪、碳水化合物、少量维生素以及钙、钾、镁、锌等矿物质，易于消化吸收，食用方便，深受世界各地人们的喜爱。"
  },
  [6] = {
    order = 6,
    id = 110,
    desc = "猫饭",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 3,
    growth = 2,
    skill = 2,
    formation = 3,
    painter = "杰克",
    cv1 = "暂无",
    desc = "猫饭是来自日本的一道简单饭食。在煮熟的米饭上撒上一些用鲣鱼干刨成的木鱼花，再淋入少许酱油就算完成了。\n 由于猫饭的用料价格低廉，所以在古时是十分受日本底层民众欢迎的料理。并且人们也乐于用这种廉价的鲣鱼来喂养家猫，因此这道料理就被称为猫饭。\n虽然做法如此简单，但根据地域不同，猫饭也诞生出了不同吃法。在东日本，猫饭的主流吃法是在鲣鱼屑上滴少许酱油调味。因为鲣鱼干本身有较重咸味，所以酱油的分量只要轻轻几滴足矣。而在西日本，要在米饭里加入味增汤。这种吃法很像泡饭，口味也较重，很符合关西人的吃法。在北海道，人们除了加味增汤，还会加入牛油，认为这样会使得猫饭更香。\n想将极简的料理做得美味，就需要在食材上下功夫。有条件的话，用现刨的木鱼花搭配隔夜的米饭，加上少许味霖，这样的猫饭口感会更好哦！"
  },
  [7] = {
    order = 7,
    id = 108,
    desc = "干炒牛河",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 2,
    phyDef = 4,
    hit = 2,
    miss = 2,
    growth = 3,
    skill = 4,
    formation = 4,
    painter = "蜥蜴仔",
    cv1 = "暂无",
    desc = "干炒牛河是流行于中国南方的特色小吃——牛肉炒河粉的简称。河粉就是米粉，将米浆蒸熟、切开而成的条状食物，因为诞生在广州的沙河镇而得名。河粉可炒、可配汤，吃法多样，而牛肉炒河粉则是其中最美味、最有亲和力的做法。\n温水浸泡河粉，韭黄切段，牛肉切小片，红椒切丝。炒锅将油烧热后，将牛肉片和韭黄、椒丝同炒，加入盐、酱油、味精、黄酒调味，炒熟后倒出。接着再将河粉翻炒片刻，与盐、酱油一起炒匀成熟后装盘，将先前做好的牛肉等浇在河粉上即可。\n所谓具有亲和力，第一是说干炒牛河的食材都寻常可得，例如牛肉、芽菜、韭黄等等。第二是说烹制手法简单，炒河粉时需要运用的颠勺、猛火快炒，都是非常基础的烹饪技能。最后是指干炒牛河在中国南方地区，无论是在百姓人家还是高档酒店，都非常受人们的欢迎。\n不过，尽管描述起来不复杂，但想要做好一份干炒牛河还是需要深厚的功力。下锅时，油多会腻，油少则容易焦。配置调料时，还要求每条河粉色、味均匀。牛肉的鲜嫩、河粉的筋道，这些要素都考验着餐厅用料的真诚、以及厨师对用油与火候的把控，所以在一部名为《满汉全席》的中国电影中，干炒牛河被喻为“厨房的克星”。\n有俗话说，“越是简单的菜肴，越是能见到真功夫”。就是因此，在饮食文化十分先进的中国广东， 干炒牛河有着非常崇高的地位。"
  },
  [8] = {
    order = 8,
    id = 109,
    desc = "帕尼尼",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 4,
    growth = 3,
    skill = 5,
    formation = 1,
    painter = "茶见",
    cv1 = "内田真礼",
    desc = "很有特点的意大利的三明治。\n用意式面包包夹奶酪、火腿、色拉、萨拉米香肠等材料制成。\n既可翻译为帕尼诺（panino单数形）也可以翻译为帕尼尼（panini复数形）\n帕尼尼的名称由美国第一个提出，可以追索到1956年，但其前身则是在16世纪的意大利食谱中出现。\n虽然帕尼尼不一定要经过烤箱加热，但是烤过的帕尼尼更加具有特点，也更有风味。帕尼尼的烘烤方式比较特殊，是使用带有纹理的金属，上下挤压并烘烤。这种技法被称为“热压”。\n意大利甚至有专门为烤帕尼尼而设计出的三明治烤架。\n在欧美国家，帕尼尼是非常流行的食物，经常出现在咖啡厅和快餐店中，因为食用便利，好吃又健康，非常受欢迎。为了制作帕尼尼用的热压技术和三明治烤架，现在也被广泛用在其他料理上。"
  },
  [9] = {
    order = 9,
    id = 112,
    desc = "千层面",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 4,
    growth = 3,
    skill = 2,
    formation = 5,
    painter = "忍忍包子",
    cv1 = "小原好美",
    desc = "意大利坎帕尼亚大区那不勒斯的著名料理。\n \n用西红柿酱、牛肉酱、白汁、芝士、面、牛奶、淡奶油、面粉等烤制而成。\n \n千层面是著名的意大利的料理，但有关这种面食起源目前仍众说纷纭。最古老的食谱可以追溯到13世纪，除了因为当时欧洲还不知道“西红柿”这种植物的存在而没有使用这种食材外，当时的食谱已经与现在千层面没有太大的差别了。\n \n一般千层面使用的食材与肉酱意大利面使用的食材非常类似，最具特点的是其层层叠叠的制作手法，如果将千层面的食材替换，就能做出口味截然不同的千层面，例如用较厚的饺子皮代替面皮，并且使用饺子的馅料的话，就可以做出“中式千层面”。\n \n传说，两西西里最后的国王弗朗切斯科二世，因为太喜欢千层面了，所以在小时候甚至被父王称作“千层面”。在全意大利，都是被长久喜爱的味道。"
  },
  [10] = {
    order = 10,
    id = 114,
    desc = "猪扒丼",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 3,
    skill = 5,
    formation = 3,
    painter = "贺崽",
    cv1 = "暂无",
    desc = "猪扒丼是近代开始流行起来的日式料理，因为食材常见、制作方便、成品美味等原因，受到世界范围人们的青睐。\n猪扒丼的历史不算悠久，明治维新后，炸猪排才传入日本。这种将肉排裹上蛋液面粉然后油炸的做法实际上脱胎于维也纳炸小牛排（Wiener Schnitzel），而如果追根溯源，维也纳炸肉排也并不是奥地利的创造，它来源于意大利的米兰炸肉排（Cotoletta Alla Milanese)。不过尽管时代变迁，这种对肉排的料理方法仍保持着传统。具体做法是：先用松肉锤均匀捶打猪排，让肉质变松软，撒上黑胡椒、料酒等调料进行腌制。再按照小麦粉、蛋液、面包糠的顺序，依次对肉排进行包裹。最后用 180 度的油温炸 5 分钟左右完成。\n一碗出色的猪扒丼，对肉排的要求很高外，对酱汁也有一定讲究。常见的做法是用高汤加入酱油、洋葱、猪排，大火持续煮开，最后均匀加入蛋液收汁，就可以作为浇头放在米饭上了。最后可以再撒上些海苔碎，能让整体的风味再上一个层次。\n关于猪扒丼还有不得不说的是，日文里“カツ丼（猪扒丼）”的“カツ”与“胜つ（胜利）”同音。因此，日本人民就自发形成了在考试或者比赛前一天吃猪扒丼的传统。\n猪扒丼就是这样能让人充满信心与力量的料理。"
  },
  [11] = {
    order = 11,
    id = 101,
    desc = "水饺",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 3,
    growth = 4,
    skill = 3,
    formation = 3,
    painter = "kaze",
    cv1 = "因幡うさもち",
    desc = "中国代表性的主食之一。\n制法主要是用事先做好的面皮包裹各种馅料制成。\n水饺的发明者据说是东汉末年的医师张仲景。当时饺子是药用，张仲景用面皮包上一些祛寒的药材用来治病（羊肉、胡椒等），避免病人耳朵上生冻疮。因此水饺当时被称作“饺耳”\n虽然现代大多数人都能区分水饺和馄饨的不同，但是因为做法和材料类似，历史上也有把“水饺”叫做“馄饨”的时期，所以两者的关系变得有些暧昧。不过馄饨有和水饺不同的起源说，因此也不能一概称作两者是姐妹关系。\n水饺在中国很多重要节日都是传统食物，包水饺也是中国人一项特殊天赋。每给家庭代代传承下来的独特包水饺的手法，是家庭的一种羁绊。\n水饺还传播到了各个国家，形成了各个国家特有的水饺。"
  },
