    painter = "RFF",
    cv1 = "岩山ちひろ",
    desc = "墨西哥代表性的主食。\n用小麦粉制成的薄饼，卷入各种食材做成的料理。\n墨西哥卷饼诞生于墨西哥北部，确切的诞生时间未知，一般认为在19-20世纪。\n一个广泛流传的民间故事是，一个名叫胡安·梅德斯的男人，他在墨西哥革命时期（1910年?-?1955年）在墨西哥城的贝拉维斯塔地区的一个街头摊贩上卖炸玉米饼，他使用驴作为自己和食物的运输工具，为了保持食物温暖，他用自制的大型墨西哥薄饼将食物卷入。而这种卷饼大卖，从而诞生了墨西哥卷饼。\n墨西哥卷饼不仅在墨西哥，也风靡了美国。由于墨西哥卷饼搭配各种食材的开放性很大，因此美国的各大餐厅也在用各种各样的创新制作方法，用不同形状，不同软硬程度的墨西哥薄饼来迎合不同食客的口味。"
  },
  [13] = {
    order = 13,
    id = 105,
    desc = "龙虾意面",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 2,
    phyDef = 3,
    hit = 2,
    miss = 3,
    growth = 4,
    skill = 5,
    formation = 5,
    painter = "Asrid",
    cv1 = "内田真礼",
    desc = "意大利代表性料理，意大利面的一种。\n在煮好的意大利面上，浇上用龙虾制成的酱汁，并以龙虾和蔬菜等为配料制成。\n“Pasta”即是意大利语中的“面食”的意思，意大利面的历史非常悠久，约在公元前4世纪，意大利半岛就出土了几乎和现在一样的制作意大利面的工具。\n单纯仅仅是意大利面的种类，在意大利就有650类以上。且几乎每年都会发表新的种类，而意大利面的各种酱汁，配料，也是多种多样，因此意大利面有无尽的组合可供搭配。\n而因为意大利半岛被地中海包围的原因，海鲜也自然是意大利面配料中很常见的一种。\n顺带一提，10月25日被定为世界意大利面日。是龙虾意面的生日哦。"
  },
  [14] = {
    order = 14,
    id = 111,
    desc = "馄饨",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 4,
    skill = 4,
    formation = 3,
    painter = "半透明黑桶",
    cv1 = "暂无",
    desc = "馄饨是源于中国北方的一种带馅面食，粤语中音同“云吞”，根据地域不同，也有抄手、扁肉、包面、清汤等叫法。\n在中国许多地方都有冬至时节吃馄饨的风俗，还流传着“冬至馄饨夏至面”的谚语。\n原本馄饨与饺子是一样的称呼，因为它们都是以面皮包住馅料做成，四周密封没有七窍，是不可听不可见不可闻的一片浑沌，古代中国人便通称它们为“浑沌”，依据中国的造字规则，后来改为“馄饨”。《燕京岁时记》记载：“夫馄饨之形有如鸡卵，颇似天地混沌之象，故于冬至日食之”，民间将吃馄饨引申为“打破混沌、开天辟地”。但到了后世，冬至日吃馄饨就不再解释其源义，而变成了祭祀先祖的风俗。\n经过千百年的演变，终于在唐朝时，因北方人多吃饺子，而馄饨则在南方大兴，这才正式区分了它们的称呼。在如今的武汉地区，还留存着将馄饨称为水饺的习惯。\n到了现代，馄饨更是吃法繁多、制作各异；有皮薄馅鲜的三鲜馄饨，有包捏讲究、蘸着料吃的过桥抄手，还有个大馅嫩的龙抄手。深受全国各地食客们的喜爱。"
  },
  [15] = {
    order = 15,
    id = 117,
    desc = "汤圆",
    open = 1,
    atkSpeed = 2,
    hp = 3,
    atk = 2,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 4,
    skill = 4,
    formation = 5,
    painter = "6音",
    cv1 = "暂无",
    desc = "汤圆、具有代表性的中华小吃之一，是由糯米粉做成的、包有馅料的球形食品。\n虽然很容易搞混，但——汤圆不是元宵、汤圆不是元宵、汤圆不是元宵！每年元宵节的时候，世间便会弥漫着着如此强大的怨念……\n具体来讲：\n汤圆是先做出饼皮、包裹馅料“包”出来的；而元宵是把馅料放在生糯米粉中“滚”出来的。\n汤圆表皮的糯米粉成团，所以煮后汤水清亮凉；而元宵表皮糯米粉松散，所以煮后汤水会成为面汤。\n汤圆馅料柔弱、馅料变化丰富；而元宵馅料吃起来口感偏硬、口味上也基本具现于甜。\n汤圆可以冷冻、速冻汤圆很流行；而元宵冻住会炸开，所以元宵必须是现做现卖的。\n虽说过去有着南吃汤圆北吃元宵这样的说法，但随着技术进步，无论哪里都能同时吃到元宵和汤圆。\n总而言之，只要记住“包汤圆、滚元宵”这六字真言再结合常识进行推论，一定能很快的分辨出是元宵还是汤圆，从而避免危机的吧？"
  },
  [16] = {
    order = 16,
    id = 119,
    desc = "粽子",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "巫贼",
    cv1 = "暂无",
    desc = "粽子是来自中国的传统节庆食品，有着悠久的历史。\n早在春秋战国时期，就有用黍来祭祀祖先和神灵的现象。到了汉晋时期，人们用植物的叶子将黍包裹成三角锥形来祭祀，称之为“角黍”，这就是粽子的原型。关于这种形状的来历，一般认为是传承了周代先民使用牛角祭祀的风俗，角黍的形状是对牛角的模仿。\n到了秦汉时期，在黄河流域出现了用粽叶包裹黍制成的角黍，与现代的粽子已经十分相近。南北朝时期，开始出现端午吃粽子纪念屈原的传说。参见南朝梁宗懔《荆楚岁时记》载：“夏至节日食粽，周处谓之角黍。人并以新竹为筒，楝叶插五彩系臂，谓为长命缕。”及南朝梁吴均《续齐谐记》载：“屈原以五月五日投汨罗水，而楚人哀之，至此日，以竹简贮米，投水以祭之。”农历五月初五包粽子祭祀屈原的传说从此逐渐流传开来，并影响至今。\n唐宋时期，都市餐饮文化高度发展，开始出现了用糯米制成的粽子。因为材料的改变，所以除了“角黍”外，粽子在那时也被称为“角饭”，并且逐渐脱离节庆的时节限制，变为一种日常食品，形式也多样起来。宋朝的《岁时杂记》有：“端午粽子名品甚多，形制不一，有角粽、锥粽、菱粽、筒粽、秤锤粽。”除了形状外，宋朝的人们也开始在粽子里加入各种馅料，比如栗子、姜、胡桃等。\n明清时期，粽子的用料已经普遍采用糯米，人们更加注重粽子内馅的变化。据清代食书《调鼎集》述，那时的粽子已经有莲子粽、薄荷香粽、豆沙粽、松仁粽、火腿粽等数十种之多。\n迄今为止，吃粽子的风俗在中国已经流传了近 1800 年，并且向外流传到了东亚以及东南亚各国。带有粽叶香气的糯米香甜嫩滑，与所有的馅料都搭配得十分出色，征服了东方诸多民族的味蕾。"
  },
  [17] = {
    order = 17,
    id = 103,
    desc = "热香饼",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 3,
    formation = 4,
    painter = "阿芸",
    cv1 = "岩井映美里",
    desc = "热香饼是一种欧美常见的料理，经常被作为早餐食用。\n主要制作方法是将小麦粉鸡蛋发粉砂糖鸡蛋牛奶等混合成面糊，然后在平底锅上两面烘烤而成。\n被称做“pancake”的时候一般都指比较薄的热香饼，而“hotcake”则指的是较厚的热香饼。\n“pancake”这个名字的由来是因为只要使用平底锅（frying pan）很轻松就能做出来。\n享用时，一般会浇上蜂蜜，蜜汁等甜酱。\n因为只要有粉，水，金属或石制平面就能做热香饼，所以热香饼的历史极为悠久，最早可以追溯到古埃及。\n真正的被命名产生“pancake”这个英语单词是在15世纪的英国。\n虽然从古至今热香饼的材料一直随着生产水平发生着变化，但是做法却一样的简单，这也让她作为基础料理的一种传播到欧洲各国，并且派生出了很多不同料理（华夫饼，班戟等）。\n即使是如此基础的料理，但只要浇上蜂蜜，就会让人觉得非常美味满足。这也是为什么热香饼可以在数千年中占领欧洲国家早餐餐桌的理由。"
  },
  [18] = {
    order = 18,
    id = 113,
    desc = "那不勒斯披萨",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "贺崽",
    cv1 = "暂无",
    desc = "披萨是一种由特殊的饼底、奶酪、酱汁和馅料烤制而成，具有意大利风味的食品。据统计，意大利总共有 20000 多家比萨店，其中那不勒斯地区就有 1200 家。那里的披萨大多有着相同的外形：饼底纤薄，中间的馅料柔软粘稠，饼边则是焦香酥脆，上层盖满了西红柿酱以及马苏里拉芝士——这就是意大利披萨中最为经典的款式，那不勒斯披萨。\n作那不勒斯披萨材料的面团，必须使用高筋面粉，加少量盐与酵母搅拌而成。制作饼底时，只能用手推压，不能使用机器或擀面杖帮助，并且饼底厚度要控制在 3 毫米以下，最后在边缘用手捏出厚度，这样才是最为正统的做法。\n那不勒斯披萨的配料只有两种，分别为玛格丽特（Margherita）和玛丽亚娜（Marinara）。前者包括圣玛扎诺西红柿、初榨橄榄油、水牛奶制作的马苏里拉芝士、磨碎的硬干酪和罗勒；后者则更简单一些，只需要圣玛扎诺西红柿、初榨橄榄油、牛至叶以及大蒜即可。\n那不勒斯披萨作为如今意大利的国民披萨，几乎可以说是披萨的代名词。它还是欧洲的传统保护标志产品，做法和配方都有严格标准，它甚至有属于自己的行业公会：那不勒斯披萨标准协会（Associazione Verace Pizza Napoletana）。如果有日能前往意大利，一定要在那披萨的故乡点上一份那不勒斯披萨，经过悠久历史认证的经典绝对不会让你失望。"
  },
  [19] = {
    order = 19,
    id = 116,
    desc = "石锅拌饭",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "小手",
    cv1 = "暂无",
    desc = "“最具代表性的韩国料理是什么”，这个问题也许尚存争议，但绝对不会有任何一个人接触过韩式料理却从未品尝过石锅拌饭。这道拥有数百年历史的米饭料理可以说正蕴含着韩国料理最最本质的味道……当然了，它本身的做法并不复杂——应当说，是“做法非常简单”才对，烹饪者只需要一些米饭、一碗辣酱以及一些他所喜爱的食材如豆芽、鸡蛋、牛肉等等，将它们置于石锅当中适当加热，再用勺子均匀搅拌便可以快乐地享用美味了。\n说来、与这种料理相关的传说真的是多到数不胜数，其内容却又往往大相径庭，例如一种说法认为“拌饭”原本是宫中的御膳，它是一种含五谷、有“五色”的重要养生料理；而与之相对的另一种说法则认为“拌饭”起源自贫苦的韩国媳妇们——在古代，媳妇们在家中的地位很低，是无法与公公婆婆一同进餐的——她们利用剩菜再加热加工的过程逐渐演变成了现如今的拌饭……不论真相到底如何，可以确定的一点是：“拌饭”是如此地深入人心，而它也正带着它独特的魅力、与韩国的饮食业一同成长着，在经历了首尔奥运会与迈克尔·杰克逊韩国公演等重要历史事件之后，为韩国料理打开了风靡世界各地的重要门户。"
  },
  [20] = {
    order = 20,
    id = 126,
    desc = "牛肉面",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "他宝甜食",
    cv1 = "暂无",
    desc = "牛肉面，全称是川味红烧牛肉面，听到这个名字很容易让人误以为它是一道川菜、想要去四川当地“寻源”，但实际上“川味红烧牛肉面”是一道不折不扣的台湾本地食物，在其他地区也被称作是“台式牛肉面”。\n有趣的是，在过去的台湾，人们既不会想去吃作为农耕伙伴的牛，也几乎不食用小麦面粉制成的面条。据说最早的“川味红烧牛肉面”是从四川等地迁居至台湾的人们用牛肉罐头、辣豆瓣酱以及红烧汤头制作出来的，这种做法虽然随性、随意，但充满家乡的味道，同时让很少食用牛肉与面条的人们体会到了二者的美味。当然了，时至今日，牛肉面里所使用的牛肉已不再是廉价的工业加工品，从口感劲道、价格亲民的黄牛肉到进口的上等澳洲牛肉，各式各样的新鲜牛肉及搭配的配菜让牛肉面也百变起来，在台北，几乎三五步就能看到一家牛肉面馆，而且每一家都有着密不外传的独家配方。\n但无论是随意丢出几十、几百元就能吃到的牛肉面，还是需要一掷千金才能吃到的牛肉面，不变的都是豆瓣香味、辛辣味以及大块大块的鲜美牛肉对味蕾的冲击。选一家好餐馆，点一碗上好牛肉面，一个人尽情享受“把头埋入面碗里”的大快朵颐过程，再尝一尝店家附赠的美味小菜，绝对是享受“料理”最简单、最直接的方法。"
  },
  [21] = {
    order = 21,
    id = 120,
    desc = "日式炒面",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "一朵焼麦",
    cv1 = "暂无",
    desc = "日式炒面，又被称作是酱油炒面，它是一道别具日式风味的炒面类料理。日式炒面所使用到的面条并不是在日本较为常见的荞麦面，而是与中式炒面原料相同的中华面。而日式炒面的灵魂就在于它的酱汁了，同其他许多料理一样，不同的店铺各自拥有着秘不外宣、独一无二的酱汁配方，如果一般人想要在家中制作日式炒面的话不妨直接购买袋装日式炒面并使用其中附赠的日式炒面酱汁。\n在原材料方面，除了必不可少的面和酱汁以外，日式炒面的食材选择是较为自由的，通常来说人们会使用到包菜、胡萝卜以及猪肉，还有适量的芝麻以及海苔用于提升口感，如果时间紧迫的话使用培根也未尝不可。它的制作方法同样很简单。首先先处理猪肉，将猪肉切片，撒上盐、味精、白胡椒粉抓匀稍稍腌制，也可以直接使用煎好的培根。接下来是切分包菜与胡萝卜，再烧水煮面。等到锅中的面吸足水分并定型后将其捞出、控干水分，再另一起一锅下油煎炒炒面、酱汁与食材。待到食材成熟、充分入味后便可出锅，装盘后再撒上芝麻与海苔，这道制作随性但却酱香浓郁的美味炒面便大功告成了。"
  },
  [22] = {
    order = 22,
    id = 122,
    desc = "跨年荞麦面",
    open = 1,
    atkSpeed = 2,
