    painter = "M",
    cv1 = "暂无",
    desc = "在一年的终点，也就是除夕这一天，为了祈求来年多福而食用的荞麦面就是跨年荞麦面了。至于为什么要在除夕吃荞麦面，不同地区和不同传说中说法不一。比较广为人知的说法是——因为荞麦面又细又长，所以人们为了祈求健康长寿之类的福气而食用荞麦面。也有一种说法是——因为荞麦面比其他的面更好切，象征着斩断厄运和灾祸，所以人们才会食用它。此外，也有传说认为年已经过去后再吃荞麦面反而会招致厄运，或是留下跨年荞麦面就会失去财运云云。荞麦面是日本的传统食品，跨年荞麦面也是在日本的历史中诞生的吃法。最晚进入十九世纪，在除夕吃荞麦面的习俗迅速普及开来，追溯到江户时代中期，那时便已经出现作为跨年荞麦面原型的一些风俗了。关于跨年荞麦面的吃法并没有详细的规定，想怎么吃就怎么吃随心所欲地享受即可。在一年结束之时，一边嘬着荞麦面，一边回忆今年的经历或是做来年的展望，这样渡过除夕也是别有一番风味的。"
  },
  [23] = {
    order = 23,
    id = 127,
    desc = "散寿司",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Asrid",
    cv1 = "暂无",
    desc = "散寿司是一种非常特别的寿司，与人们通常印象中被捏成小小一团、搭配生鱼片等配菜的握寿司、卷寿司不同，散寿司是将大量寿司饭铺在盒状餐具内，然后拌入或平铺上多种配菜的料理。它有些类似于中国特色快餐中的“盖饭”。在制作的时候，首先将寿司米煮熟，然后加入寿司醋、盐等搅拌不断、放入容器中铺平，接着放入视季节、价格所选取的时令食材，如鱼生、虾、蘑菇、海苔、黄瓜、蘑菇等，最后淋上山葵与酱油调味，散寿司即告完成。虽然它的名气远不如同族的其他种寿司，但由于制作过程较为简单、用料丰盛，因此深受家庭餐桌的爱戴。在一些特别的日子如祭祀、庆典、生日会等场合很容易见到散寿司的身影。"
  },
  [24] = {
    order = 24,
    id = 115,
    desc = "过桥米线",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Rain Lan",
    cv1 = "暂无",
    desc = "过桥米线是中国传统的米线料理中最为人们所熟知的一种。它的主料是米线，即稻米经过多道工序处理后所制成的条线状主食，配料有猪里脊肉、鸡胸脯肉、乌鱼肉、猪腰片、鱿鱼片，辅以豌豆、韭菜、葱丝、姜丝、玉兰片、豆腐等。过桥米线的制作方法较为复杂，它讲求用禽肉油封住烫面，汤汁滚烫但不冒出热气，从而保持住食材的美味与米线的滑爽。值得一提的是，过桥米线之所以得名“过桥”也正在于此——相传，过桥米线的做法源自一位贤惠的妻子，她为了人远在湖心岛上苦读的秀才丈迟到上温热可口的饭菜，发明了用热油封住汤面的处理方法。久而久之，这种烹饪方法便被普及推广开来，过桥、登上湖心岛的送饭过程也成为了这种米线的名字，被人们用以纪念那位温柔而又聪慧的贤妻。"
  },
  [25] = {
    order = 25,
    id = 128,
    desc = "管装牛肉",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "wu家小子",
    cv1 = "暂无",
    desc = "管装牛肉是20世纪60年代的航天食品之一，将牛肉泥封入铝制牙膏壳内，以便让宇航员在失重的情况下吸食。\n不过，管装牛肉等早期航天食品都只是为了在为期较短的宇宙旅行中维持宇航员的营养均衡而制作的，所以仅仅考虑到了营养，重量，体积等因素，由此一来，味道方面就有些不尽如人意，宇航员也会在种种环境因素下食欲大减，对身心健康造成影响。\n在之后的航天历史发展当中，为了让宇航员能获得更加舒适的饮食生活，科学家们在航天食品的制作当中也是煞费了苦心，时至今日，宇航员在航天过程中已经可以享受到与日常生活中同等甚至更高质量的饮食。\n也因此，航天食品的进化史也侧面反映出人类航天事业的发展过程。"
  },
  [26] = {
    order = 26,
    id = 129,
    desc = "竹筒饭",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 1,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "竹筒饭可以说是一种民族气息相当浓郁的料理，不同的民族有着不同的做法，每种做法都有其独特之处。少数民族的先人们上山狩猎，为求轻装出行，而不随身携带炊具，饿了时，便将山上的竹子砍断，取其一节作为锅，将带着的米放入其中，加入适量水后用叶子封住口，用火烧熟。以此烧制的米饭既保留着其原本的甘甜，又带有着竹子的清香，十分美味可口。这种做法后来延续下来，人们也开始尝试在烧制米饭时将蔬菜和肉加入其中，这样的竹筒饭在保留原有口味的前提下营养更加均衡，原先的「烧」也逐渐衍生出「焖」和「蒸」等做法，这无疑是我国少数民族智慧的结晶。时至今日，竹筒饭依旧作为个别少数民族日常生活中的常见主食，延续着它的历史。"
  },
  [27] = {
    order = 27,
    id = 123,
    desc = "杂煮",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "M",
    cv1 = "暂无",
    desc = "用高汤调味的汤汁里，加入以年糕为中心以及其他食材的汤料理就是杂煮了，但其样式因日本各地区而异。光是有名的西日本和东日本的区别，就有圆年糕、方年糕、味增做法、酱油做法等，差异涉及到了很多点。光看放在年糕里的食材，各县的样式都不一样，复杂到难以记录在一起。和做法一样，关于杂煮的历史也有各种各样的说法。一种有力的说法是从武家社会的礼仪料理中派生出来的，根据这种说法，从室町时代开始，作为杂煮前身的烹杂煮就作为吉利的东西被食用。即使采用了其他的说法，大体上也与礼仪和吉兆相通。正因为每个地方的做法都有很大的不同，所以杂煮更能表现出当地的特色。面对一碗杂煮的时候，一边思考它是哪里的做法一边吃，也很有意思吧。"
  },
  [28] = {
    order = 28,
    id = 130,
    desc = "妖炽",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良",
    cv1 = "赵爽",
    desc = "妖炽是猫咪星海妖家族大小姐，天之骄子这个词用在妖炽身上再贴切不过，妖炽自小展露出她过人的天赋，拥有绝对的破甲能力。\n妖炽因为出色的能力与显赫的家世，无论在哪里都是全场焦点，父母对她万般宠爱，喜欢跟着母亲云游四海，对任何事物都抱有好奇心。\n随着R实验的爆发，整个星系都被病毒笼罩，因为和母亲在怪味星冒险途中受到大量的污染，驯服妖兽的能力似乎被压制住。而深海组织掌握着海底60%的资源，只有拥有驯服妖兽能力的孩子才有资格管理深海；深海领袖历来都是在猫咪星三大家族里挑选。，父亲为了妖炽，和海胆宇宙经纪公司合力开发提纯剂。\n提纯剂似乎起到了很大程度的作用，妖炽拥有了自己的妖兽猫鲨，因为父亲违背了深海规则，海妖家族在深海的强大地位岌岌可危，受到其他两大家族的合力对抗，为了妖炽安全，父母将她送往皇家学院。\n沉重的代价使妖炽快速的成长，因为海妖家族的危险位置与优等生的身份，妖炽成了很多人眼中嫉妒的对象。甚至有些人会陷害捉弄她，妖炽从来都不是小心隐忍的人，她总是会狠狠的教育回去。\n从学院回到深海，妖炽以强大的实力证明了自己，成为深海领袖的候选人，因为需要解决家族危机，她与月汐的联系又热切起来了......似乎一切事情都在好转。\n在那些晚上无法睡着的夜里，其实妖炽也会偶尔的对压力倍增的未来感到迷茫。可是每当这时候，那些她闪耀的过去，父母的笑容都会随着那些迷茫一起在她的脑海中浮现。于是她又恢复了活力：有着最优秀的实力，最深爱的家人，有什么困难会是妖炽无法战胜的呢？"
  },
  [29] = {
    order = 29,
    id = 124,
    desc = "炸鱼薯条",
    open = 1,
    atkSpeed = 2,
    hp = 4,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "白身鱼(炸鱼)配上炸薯条(薯片)是英国的传统快餐。\n英国的传统吃法是撒上醋和盐。浇上的醋是苦醋和芫荽醋。配菜一般是被称为玛西比的捣碎的绿豆。\n鱼和薯片虽然在路边摊也有提供，但也可以在餐厅吃到。在餐厅里，客人可以用放在桌上的调味料等，根据自己的喜好调味食用。\n炸鱼薯条有着悠久的历史，特别是工业革命以后，作为英国的国民料理而根深蒂固。尤其是作为劳动者的饮食主体普及开来。\n英国国内有很多炸鱼薯条的专卖店，国外也有很多吃炸鱼薯条的地方。\n除了英国的传统吃法之外，各地也有各种各样的吃法。例如，可以搭配肉酱、咖喱酱、番茄酱、塔尔塔酱、当季肉酱等等来食用。"
  },
  [30] = {
    order = 30,
    id = 131,
    desc = "西班牙海鲜饭",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Ahchii",
    cv1 = "暂无",
    desc = "在西方世界，有传说中的三大名菜，除了法式蜗牛和意面之外，第三位成员就是西班牙海鲜饭（Paella，音译为巴埃加）。西班牙有一座鱼米之都——瓦伦西亚，盛产艮米。人们用当地的特产做为原料，以无数虾子、螃蟹、黑蚬、蛤、牡蛎、鱿鱼来点缀黄澄澄的饭粒，整体上桌后热气腾腾，令人垂涎。\n据说最早的Paella并不是以海鲜为食材。关于Paella的起源，据说在西班牙东海岸的一个叫Valencia的小海港，的货工们习惯在篝火上架起一口大锅，把米和食材丢进去一起煮，然后用木勺子直接从锅中取食。Valencia是出名的货港，但附近缺少渔场，所以海鲜售价并不便宜。旧时即使到了庆典时刻，最好的配料也不过是兔子和野鸭，偶尔才会有些许鸡肉。那么平时的主要食材是什么呢？你一定想不到，是当地最便宜的肉类——蜗牛。所以，也许最早该叫它西班牙蜗牛饭——噢，真可怕。至于Paella的名字，其实是当地语言“大锅”的意思，或许和中华大陆的“香锅”有一定的异曲同工之妙吧？\n不过，关于Paella，还有另一种传说——15世纪，哥伦布航海时曾遭到一次飓风袭击，逃生到一个小岛上。当地渔民用海鲜和米饭做了锅大杂烩，救了饥寒交迫的哥伦布一命。后来哥伦布回到西班牙后，跟国王说起这件事，国王就命令宫廷御厨到小岛学做海鲜饭，以后王宫里就用海鲜饭招待最尊贵的客人。就这样，海鲜饭从渔民的餐桌搬到了国王的宴席上，从此，海鲜饭也成了西班牙的“国饭”。"
  },
  [31] = {
    order = 31,
    id = 132,
    desc = "咖喱饭",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 5,
    hit = 1,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "“咖喱”一词来源于泰米尔语，是“许多的香料加在一起煮”的意思。在印度民间传说中，咖哩是由佛祖释迦牟尼所创的。在泰米尔语中，“Kali”是“酱”的意思。早期印度被蒙古人所建立的莫卧儿帝国梦龙所统治过，其间从波斯（现今的伊朗）带来的饮食习惯，从而影响印度人的烹调风格直到现今。\n在早期的印度，人们发现羊肉膻味太浓，仅仅使用一种香料无法将其消除。为了烹调出更美味的羊肉，人们以多种干香料粉末组合而成的浓汁来烹调，没想到效果出奇地好。这便是坦米尔“卡利”（Kulry）咖喱的来源。\n咖喱的种类很多，以国家来分，其源地就有印度、斯里兰卡、泰国、新加坡、马来西亚等；以颜色来分，有棕、红、青、黄、白之别，根据配料细节上的不同来区分种类口味的咖喱大约有十多种之多，这些迥异不同的香料的汇集在一起，就能够构成各种咖喱的各种令人意想不到的浓郁香味。\n人们常用不同的主食配着咖喱食用，像面包，馍片，炸虾片等都是咖喱的好搭档。不过，要说最常配着咖喱食用的当然还是香喷喷的米饭——被浓郁酱汁包裹的咖喱饭，给味蕾带来了饱满奇特的幸福感，一定会让食客感到充实的满足。"
  },
  [32] = {
    order = 32,
    id = 134,
    desc = "安西娅",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 1,
    phyDef = 4,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "朝露",
    cv1 = "大久保瑠美",
    desc = "安西娅的母亲在怀孕时，仍然为了平民们、在尼布尔讨伐魔物，于是不得不感染了异化病，长出异样的耳朵与尾巴。没想到，可悲的事情就此发生了，凯旋的母亲非但没有收到人们的欢迎，反而被认为是不详之物驱逐出了村子。\n为了让孩子健康成长，母亲没有绝望气馁，而是选择成为拾荒者，独自抚养两个孩子——安西娅与安妮丝长大，最后，在她们六岁时病逝。\n对当时仍然年幼的姐妹俩来说，这意味着失去了唯一的保护伞，不得不直接面对人们对异人的恐慌与歧视。但是，姐姐安西娅完全遗传了母亲的坚强，与母亲同样的，她决定以温柔与善良来面对荒原与这里的人们，绝不改变。\n\n年纪轻轻就开始以拾荒者身份在墨涅塔西亚生活的异人少女，性格温和，吃苦耐劳，受到很多人的喜爱。但是，荒原上仍然有一部分人对异人怀有歧视，因此安西娅能接到的委托比起普通人要少很多，目标也往往很苛刻，这让安西娅非常辛苦——即便付出比普通人多出数倍的努力，也仅能让生活维持温饱。\n因为偶然的事件与薇琪一起加入了舒儿的拾荒队，虽然不用再为遮风避雨的场所发愁，然而作为拾荒者的辛苦程度却比从前要变本加厉，这在荒原上的生活是变好了还是变糟了……只能交给安西娅自己来评断。"
  },
  [33] = {
    order = 33,
    id = 135,
    desc = "饭团",
