    painter = "漫道",
    cv1 = "暂无",
    desc = "饭团，番剧中的常客，便当盒里的明星，日系快餐的王者。它主要食材是米饭，主要配料是酸梅，鱼片等。制作者可根据自己的喜好添加配料，亦可根据个人喜好，制作成多种样式的饭团。虽然传统上对于饭团的印象，就是在一团蓬松的白米饭中，内馅或许是烤鲑鱼，并且由一位慈爱的母亲以海苔将整个饭团满满地包覆起来，放进便当盒，放进书包，给孩子背上送Ta去上学。而便利商店则彻底地改变了这幅景象。\n自从便利商店于1970年代出现后，饭团就成为便利商店最重要的商品之一，至今这种方便美味的料理仍然保有这个地位。由于开发出将米饭以及海苔分离的包装方式，可以使海苔保持酥脆，并且可以让消费者在享用饭团之际不至于弄脏手，这让便利商店所销售的饭团深受喜爱。而饭团内馅料的选择也非常多元化，其中还有不少来自外国的口味，让这种日本料理又多了点洋味。\n饭团风潮的另外一个原因，是因为人们不仅追求口感，还越来越多地重视健康，对方便的点心感开始质疑。大部分速食食品，如汉堡炸鸡，经过了油炸处理，热量公认地超标。反之，饭团的主要成分是大米与海苔。即便他们的馅料可能包括肉或沙拉酱，但是饭团的大小适中，所以不会因此而发胖。\n不过，饭团最迷人的地方莫过于手工制作的感觉。速食连锁店所提供一般价位的食物，不论你选择哪一家，在外观上或口感上实在没有什么差别。但是如果你所享用的饭团是专为你准备的，或由你自己包覆上那一层海苔的话，你一定会感受到一份独享的温馨。"
  },
  [34] = {
    order = 34,
    id = 133,
    desc = "羊肉泡馍",
    open = 1,
    atkSpeed = 2,
    hp = 6,
    atk = 1,
    phyDef = 6,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "六水",
    cv1 = "暂无",
    desc = "羊肉泡馍，亦称羊肉泡，古称“羊羹”，关中汉族风味美馔。它烹制精细，料重味醇，肉烂汤浓，肥而不腻，营养丰富，香气四溢，诱人食欲，食后回味无穷。\n自古以来，羊肉泡馍，即羊羹，便是颇有帝王之气的料理。且不说它源自秦皇的故乡——陕西，单单是民间关于它的传说，就极为不凡。最有名的莫过于是宋太祖赵匡胤与“汤泡馍”的故事：五代末年的赵匡胤流浪街头，饥肠辘辘，因小贩施舍的一碗“汤泡馍”而得以果腹。后来赵匡胤做了皇帝，想起了曾经落魄时吃的那碗“汤泡馍”，便让御厨去做。但御厨反复做了多次，却始终不得其味。于是，便带随从来到当年吃“汤泡馍”得长安街，让卖肉的店主给他做一碗“羊肉泡馍”。店主见皇上驾到，非常惊喜也非常惶恐，认认真真的为他烹饪了这道绝佳的美味。赵匡胤用后赞叹不已，重赏了店主，从此“羊肉泡馍”名声大噪。\n当然，在史书上，这道料理的记载又出现了变化，但这股帝王之气却从未消去。如《礼记》以及先秦诸子，都曾提及羊肉羹。最初多用于祭祀及宫廷御筵。西周时曾将羊肉羹列为国王、诸侯的礼馔。《战国策》记载中山国君，由于一杯羊羹而激怒了司马子期，怒而走楚，说楚王伐中山，招致亡国的命运。据《宋书》记载：南北朝时，毛修之因向宋武帝献出羊羹，味美，武帝竟封俘虏修之为太官史，后又高升为尚书光禄大夫。到了隋朝，出现了“细供没忽羊羹”(谢讽《食经》)。虽然各种史料的说法均有不同，但足以证明，这道料理从古至今，都是披着黄袍流传下来的。虽然现在已经成为了民间随处可见的料理，但它的传奇故事却一直被人们铭记着。所以，正在享用这道料理的你，有没有位极九五的自豪感呢？"
  },
  [35] = {
    order = 35,
    id = 136,
    desc = "奶油玉米棒",
    open = 1,
    atkSpeed = 2,
    hp = 6,
    atk = 1,
    phyDef = 6,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "“白蓬蓬~金灿灿~奶甜香~鲜嫩弹~”奶油玉米棒作为一道家喻户晓的家常菜，材料简单，制作简单，味道美味且有营养。主要材料的玉米中的维生素含量非常高，是稻米、小麦的5-10倍，在所有主食中，玉米的营养价值和保健作用是最高的。玉米中含有的核黄素等高营养物质，对人体是十分有益的。据《本草纲目》记载：玉米种出西土，甘平无毒，能调中开胃。玉米的花粉、胚芽中还含有大量的维生素E和玉米黄酮，经常食用玉米制品可延缓人体衰老，增强人的体力和耐力。而奶油作为辅料，主要作用有二，一是调味，在玉米本身有的甜味上增加现代加工过的奶香也使口感更佳，二是能补充维生素A，以及玉米没有的脂肪与蛋白质，两者相加营养丰富味道甜香，可谓是绝配~"
  },
  [36] = {
    order = 36,
    id = 137,
    desc = "盲公饼",
    open = 1,
    atkSpeed = 2,
    hp = 6,
    atk = 1,
    phyDef = 6,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "盲公饼是广东省佛山市的一种特色传统名点，属于粤菜系；由于它是由一盲人创制于清代嘉庆年间，因而得名盲公饼。距今已有一百六十年之久。\n而盲公饼最受欢迎的部分呢，则要属其制作，盲公饼与一般饼食不同，有其独特之处，市场上出售的饼食，大都以面粉配制，而盲公饼则全用糯米配以食糖、花生、芝麻、猪肉、生油等上乘原料巧制而成。饼内所夹的猪肉，其制法更为美妙精巧，用幼细白糖腌藏数月才取出配制，吃起来甘美酥脆，美味可口，享誉中外。\n据传，百多十年来，盲公饼的制法古朴，以瓦盆盛料焙制，坐着生产，效率极低。直至1955年公私合营后，才改用案板制，站着生产，由于操作方法改善，生产效率大大提高。在其出名以后，购买者日众，并多以此为送礼佳品。初制时，饼形大于铜元，没有猪肉心，到1875年后，为了精益求精，才加猪肉心配制。产品规格有大小二种，大的每筒六个，小的每筒十个。出口或送礼另有装纸盒和铁罐。多销往东莞、石龙一带，省内及港澳来佛山的旅客，多购盲公饼回去馈送亲友，很受欢迎~"
  },
  [37] = {
    order = 37,
    id = 138,
    desc = "带骨汉堡罐头",
    open = 1,
    atkSpeed = 2,
    hp = 6,
    atk = 1,
    phyDef = 6,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "暂无",
    desc = "带骨汉堡罐头是一种源自美国南部的独特美食，属于美式快餐文化的一部分。这种罐头的创意来源于传统的汉堡，但加入了带骨的肉类，使其风味更加丰富和独特。带骨汉堡罐头最早由一位名叫约翰·史密斯的厨师在20世纪50年代发明，因其便捷和美味迅速在美国流行开来。\n带骨汉堡罐头的制作过程颇为讲究，与普通汉堡不同，它选用带骨的猪排或鸡腿肉作为主要原料，配以特制的烧烤酱、洋葱、辣椒和各种香料，经过慢火炖煮，使肉质酥软，骨头中的髓质也融入汤汁中，增添了独特的风味。罐头内的汉堡肉饼则是由精选的牛肉和猪肉混合制成，经过特殊的腌制和煎烤工艺，保持了肉质的鲜嫩多汁。\n带骨汉堡罐头的独特之处在于其食用方式。打开罐头后，消费者可以直接将带骨肉和汉堡肉饼取出，搭配罐内的浓郁酱汁和蔬菜，夹入面包中食用。这种吃法不仅保留了传统汉堡的便捷性，还增添了啃咬骨头的乐趣，深受年轻人和户外活动爱好者的喜爱。"
  },
  [38] = {
    order = 38,
    id = 202,
    desc = "宫保鸡丁",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 1,
    miss = 3,
    growth = 2,
    skill = 4,
    formation = 2,
    painter = "TN千夏",
    cv1 = "萩原 みやこ",
    desc = "也称“宫爆鸡丁”。\n著名的中华料理，在川菜，鲁菜，贵州菜都有收录，但主要被认为是川菜。\n以切丁鸡肉为主料，佐以花生米、黄瓜、辣椒等辅料烹制而成。\n虽然给人一种历史悠久的感觉，但其实是在晚清时确立的菜式。\n传说是清朝时期四川总督丁宝桢所创。\n出自达官显要，却广为流传于民间，无论是高级餐馆还是民间小店中都能品尝到。\n在中国以外的地区也很受欢迎，甚至改良出了适合外国口味的各种版本。"
  },
  [39] = {
    order = 39,
    id = 206,
    desc = "勃艮第红酒炖牛肉",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 1,
    phyDef = 1,
    hit = 1,
    miss = 3,
    growth = 2,
    skill = 2,
    formation = 4,
    painter = "TN千夏",
    cv1 = "小原好美",
    desc = "法国传统的乡土料理。\n将牛肉、橄榄油、大洋葱、大胡萝卜、马铃薯、红酒等放入锅中炖成。\n \n虽然红酒有高价的印象，但勃艮第红酒炖牛肉并非高级料理，而是一般的家庭料理。勃艮第红酒炖牛肉的故乡勃艮第是法国主要的红酒产地，因此不太高品质的红酒，价格非常低廉，导致有许多使用红酒的料理。\n勃艮第红酒炖牛肉本身也是把喝剩的红酒和多筋而无法食用的牛肉放到一起炖煮而诞生的料理。\n但由于其独特的风味，渐渐从一般的乡土料理发展为法国的代表菜之一。\n过去勃艮第红酒炖牛肉需要相当长的时间炖煮，但由于高压锅的发明，现在可以在短时间内做成非常美味的勃艮第红酒炖牛肉。"
  },
  [40] = {
    order = 40,
    id = 203,
    desc = "莎朗牛排",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 2,
    phyDef = 1,
    hit = 1,
    miss = 4,
    growth = 3,
    skill = 3,
    formation = 2,
    painter = "小吃",
    cv1 = "赤尾ひかる",
    desc = "常见的一种西式牛排。\n使用牛后背部的肉切成的牛排煎成。\n \n莎朗牛排的“莎朗”是指的牛的部分“Sirloin”，对于“Sirloin”英国和美国的认定不同，在美国指牛后腰脊柱两侧的肉，肉质细嫩，价格高。其中顶部（top sirloin）的肉质最好，价格最高，一般会标明。在英国、香港等地指牛胸脊肉部分，肉质细嫩度次于菲力牛排，售价也较低于菲力牛排，上端部分的西冷牛排较为鲜嫩，售价亦稍高。\n虽然判定位置有微妙的不同，但都是指靠近牛后背的比较细嫩的部位。\n莎朗牛排最合适的口感，被认为是在铁板上烤至七分熟。\n虽然莎朗牛排并不是牛价格最高的部位。但是人气极高，老少都能享用，如果在牛排馆犹豫选什么牛排，莎朗牛排永远是个不错的选择。"
  },
  [41] = {
    order = 41,
    id = 204,
    desc = "帕尔玛火腿",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 1,
    miss = 5,
    growth = 3,
    skill = 4,
    formation = 2,
    painter = "Rain Lan",
    cv1 = "続木友子",
    desc = "意大利产的世界三大火腿之一。\n用作帕尔马火腿原料的猪只必需有血统证书，且重量达到要求。帕尔马火腿火腿唯一的添加物是海盐，并需要经过不少于12个月的专门处理。\n \n帕尔马火腿是非常古老的料理，从罗马时期就开始生产，最早的文字记录是公元前100年，并在希腊和罗马之间被交易，距今已有2000年以上的历史。\n帕尔马火腿虽然相对于其他熟食容易保存，但制作帕尔玛火腿对于温度和湿度都有一定的要求，因此在古时产量有限，流通量并不是很大。\n不过由于现代冷藏技术的进步，得以让帕尔马火腿能全年生产。从而让这种美味的火腿远离原产地，被输送到世界各地。\n虽说如此，帕尔马火腿漫长的制造时间，也还是导致其产量有限，一般来说帕尔马火腿的熟成不少于12个月，而理想状态是20-24个月。因此，也只有四分之一的帕尔玛火腿被出口到国外售卖。\n现代的帕尔玛火腿受欧盟法定产区保护和规范（DOP），通过保证生产地区的方式来规范火腿的品质，并且“帕尔马火腿”的名称使用受到严格限制。"
  },
  [42] = {
    order = 42,
    id = 208,
    desc = "回锅肉",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 3,
    skill = 3,
    formation = 3,
    painter = "阿宇",
    cv1 = "暂无",
    desc = "回锅肉是一道以猪肉味主料的传统川菜，其名中的“回锅”是指把已经做熟的猪肉重新放入锅中翻炒，通过如此处理，猪肉中肥油被最大限度的煸出，猪肉变得劲道爽口、肥而不腻，再配上青椒、蒜苗、辣椒、豆瓣等调料与配菜带来的浓厚辛辣味，如此制成的回锅肉会给人的味蕾带来极大的冲击，让人直呼过瘾。\n有关于回锅肉的历史，同其他许多民间菜肴一样已难以考证。在一些民间杂谈当中说回锅肉起源于清朝，由一位四川的翰林所发明，然而更多的记录表示回锅肉的宋明时期已极其普及，它的源头可能是一道被称作油爆猪肉的民间名菜。无论真相到底如何，对于食客们而言最重要的一点是，回锅肉身上所体现的是与宫中那些精雕细琢的贵族菜相对的，通过民间代代相传、代代改良的民间智慧闪光，这也是回锅肉的魅力远摄四方的根本原因。"
  },
  [43] = {
    order = 43,
    id = 201,
    desc = "麻婆豆腐",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 4,
    skill = 5,
    formation = 3,
    painter = "林茶以",
    cv1 = "古城こじょ",
    desc = "中华料理，川菜的代表菜。\n主要食材有豆腐、牛肉碎或猪肉碎、辣椒、和花椒等。\n和宫保鸡丁一样，看起来很有历史，但其实是清朝诞生的菜式。\n在清同治初年（1874年以后），由成都市北郊万福桥一家名为“陈兴盛饭铺”的小饭店老板娘陈刘氏所创。因为陈刘氏脸上有麻点，人称陈麻婆，她发明的烧豆腐就被称为“陈麻婆豆腐”。\n麻婆豆腐在传到国外后，有非常多的改变，其中改变最大的，是不使用花椒，“麻”虽然作为麻婆豆腐的一大特点，但是因为太过刺激的味道，导致很多人无法接受。\n但从另一个方面来思考，即使去掉“麻”的成分，麻婆豆腐的魅力也足够扬名海外。成为大多数中餐馆的必备菜式。"
  },
  [44] = {
    order = 44,
    id = 205,
    desc = "东坡肉",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 4,
    skill = 3,
    formation = 3,
    painter = "忍忍包子",
    cv1 = "杉浦しおり",
    desc = "传说由宋朝著名诗人苏轼所创的名菜。\n将半肥半瘦的猪肉切成块状，炖制而成。\n相传元丰二年十二月（1080年），苏东坡被贬于黄州时，仿制前人的做法改良，将烧猪肉加酒做成红烧肉小火慢煨，创造出了东坡肉。\n苏轼还在期间专门创造了一首《食猪肉诗》：\n \n黄州好猪肉，价钱如粪土，富者不肯吃，贫者不解煮。\n慢着火，少着水，火候足时它自美。\n每日早来打一碗，饱得自家君莫管。\n \n虽然东坡肉的诞生地不在浙江，但是东坡肉传统上被认为是浙菜，其原因是因为其真正被发扬光大的是在杭州。\n \n宋哲宗元佑四年（1089年）一月三日，苏东坡任杭州知事，发动民众疏浚西湖。大功告成，为犒劳民工，吩咐家人将百姓馈赠的猪肉，烹制成佳肴，分送给民工，民工们吃后无不称奇，人们为传颂东坡的为人，将此独特风味的块肉命以东坡肉。\n \n现今，远近闻名的东坡肉在各大菜馆都能品尝到，是苏轼除了在诗词之外，留给后世的一大财产。"
  },
  [45] = {
    order = 45,
    id = 210,
    desc = "鱼香肉丝",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 2,
    phyDef = 1,
    hit = 1,
    miss = 5,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "蛋挞Pokiri",
    cv1 = "暂无",
    desc = "鱼香肉丝是一道非常著名的中华料理，其名字中的“鱼香”一词指的是这道料理虽然没有使用到任何的鱼类材料，但是在厨师完成烹饪之后整道菜都散发出一股浓郁的鱼肉鲜香。对此，一种最富有说服力的解释是：鱼香肉丝当中鱼香源自原料中的四川泡辣椒，因为后者最原始的制作方法正是将新鲜的辣椒与鲫鱼一起放入坛中长时间泡制发酵——就此看来，鱼香肉丝的精髓全在于四川泡辣椒的独特美味之上，但事实恰恰相反、缺少了其他技法与调料也是万万不行的。鱼香肉丝的第二个特点是葱姜蒜味特别浓厚，厨师在准备制作时必须要先将四川泡辣椒与葱姜蒜切得非常细碎，因为只有这样做才能令它们的鲜味完全释放、从而避免其中的一种辛辣味盖过另一种辛辣味。\n具体制作方面，除了必须的要有肉丝以外，在配菜方面鱼香肉丝的要求并不是非常严格，通常的选择有冬笋、木耳、青椒等等，没有的话也可以自由使用其他相近的食材代替，或者干脆弃之不用。在按照先荤后素的顺序将以上食材逐一下入锅翻炒、临出锅前加入糖、盐、醋、酱油等调料调味之后，色泽鲜红、口感滑嫩，味道清鲜微辣、略带酸甜的鱼香肉丝便大功告成了，无论是直接食用还是搭配其他菜肴，鱼香肉丝的美味都令人印象深刻。非常值得一提的是，虽然鱼香肉丝已经在某种意义上成为了人们心中的川菜代表，但有传闻说它的诞生期是二十世纪的三四十年代，是名副其实的最“年轻”的川菜哦。"
  },
  [46] = {
    order = 46,
    id = 211,
    desc = "鞑靼牛肉",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 4,
    skill = 5,
    formation = 4,
    painter = "NIN",
    cv1 = "内田彩",
    desc = "狂野的美味，却是地道的欧洲的料理。\n \n将切碎的生牛肉或者马肉，搭配调料和蛋黄做成。\n \n鞑靼牛肉又称野人牛肉，关于其诞生有两种说法:\n鞑靼牛肉中的“鞑靼”两字，指的是游牧民族的“鞑靼人”，其中一种观点认为鞑靼牛肉的诞生与鞑靼人食用马肉的方式有关。\n鞑靼人在远征时，往往一人会带数匹马，这些马不仅仅只是用来骑乘，还会被当作军用食物，但因为骑乘用的马比起家养的马来肉质更硬，所以会用刀切碎，再利用骑马时的震动将肉捣烂，添加调味料来食用。\n鞑靼人的这种马肉的食用法，传入欧洲后，欧洲人用牛肉代替马肉，并进行改良，诞生出了鞑靼牛肉。\n \n另一种说法是鞑靼牛肉在诞生之初，配有塔塔酱，并且因为在欧洲食用生肉是一种野蛮的行为，因此冠以“鞑靼”的名字。\n \n由于可能造成的细菌和寄生虫（如弓形虫和牛带绦虫）污染，鞑靼牛肉的制作需要附和极高的卫生标准，并且不适合孕妇，免疫力较弱人士和慢性病患者食用。"
  },
  [47] = {
    order = 47,
    id = 212,
    desc = "叫花鸡",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 2,
    phyDef = 1,
    hit = 3,
    miss = 4,
    growth = 4,
    skill = 5,
    formation = 3,
    painter = "八才提督",
    cv1 = "钉宫理恵",
    desc = "由最底层民众创造的著名江苏菜。\n叫花鸡最原始的做法是将清空内腔的整鸡，不放血不拔毛，直接用泥浆包裹，并埋入土中用火煨制而成。\n\n叫花鸡又名“富贵鸡”，一般认为是诞生于明末清初的江苏省常熟市。传说当时有名叫花子，偶然的机遇下获得了一只鸡，但是身边没有任何调理道具，无奈之下只好徒手简单处理了一下鸡，用泥土将带毛的鸡整个包裹，并在泥土上方生火。一段时间后，叫花子将鸡挖出，毛随着泥土一起剥落，里面的鸡肉柔软而鲜美。\n原始的叫花鸡的做法存在卫生问题，因此现代餐厅里提供的叫花鸡使用的是经过改良的制作方法，一般是将处理过的整鸡用荷叶包裹，再用保鲜膜和粘土在外面再包裹一层，并用焗炉烤熟。因为荷叶的芳香渗入鸡肉，让叫花鸡更有了风味。\n\n虽然是由底层人民所创，但美味的料理一定会被发掘出来，叫花鸡现在也已经成为知名菜式并被国内外贵宾所享用，是一种从下往上逆袭的美味料理。"
  },
  [48] = {
    order = 48,
    id = 214,
    desc = "叉烧",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 4,
    skill = 3,
    formation = 4,
    painter = "ovos",
    cv1 = "暂无",
    desc = "叉烧是中国广东省的名菜，属于粤菜。多选用猪颈肉，用红曲米或者红腐乳，加料酒和蜜糖腌制后，烤制完成。\n详细来说，叉烧一般分为两类：瘦叉烧和肥叉烧。顾名思义，瘦叉烧使用全瘦肉制作，吃起来略微干柴。肥叉烧则是最常见的叉烧，除了猪颈肉，用梅头肉和五花肉都可以制作，特点是更加软嫩多汁，瘦肉之间的油脂会随着咀嚼不断析出，让脂香在口腔回绕，因此得到了绝大多数人的青睐。\n关于制作，叉烧的腌制要求在 12 小时以上。红曲米或者红腐乳的作用主要是上色，家庭也可以用叉烧酱代替，里面的红曲会让叉烧的色泽更加诱人。料酒用来增香，蜂蜜则是负责叉烧的主要口味——甜味，比起白糖，蜂蜜的味道要更为柔和。除了上述的三种主料，腌制时通常也会加入其它基本腌料例如五香、蒜蓉、姜葱、陈皮等。\n叉烧的烤法有明火与暗火之分。明火类似北京烤鸭的挂炉，采用果木，明火烤制。暗火则是用高温炉密封烤制，类似北京烤鸭的焖炉。一般来说，明火叉烧要求烤到外皮焦香而内部酥脆，更加考验厨师的手艺。\n在广东，叉烧往往伴随着人们每天的生活。叉烧肠粉、叉烧饭、叉烧包，用叉烧制得的料理数不胜数。广东更有一句名言：“生旧叉烧好过生你”，经常见于母亲训导孩子。意思是说生一条叉烧好歹能吃，然而生你这个孩子只会给我添麻烦。可见叉烧在人们心中有着相当崇高的地位。"
  },
  [49] = {
    order = 49,
    id = 215,
    desc = "酸菜鱼",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 3,
    skill = 5,
    formation = 3,
    painter = "inxst?",
    cv1 = "暂无",
    desc = "酸菜鱼来自中国重庆地区，是从 20 世纪 90 年代开始流行的著名江湖菜之一。\n所谓江湖菜，是与正宗菜相对的概念，指从百姓人家、小酒馆、大排档等地发迹的料理。虽然在食材与形式上与正宗菜有一定差距，但也具有鲜明的特色与风味。同时江湖菜的价格便宜，适合大众消费，使得它们的流行速度快于寻常。\n在酸菜鱼身上，江湖菜的“土、粗、杂”特点表现得非常明显。第一，“土”是指食材朴素实惠，酸菜鱼一般选用在中国最为常见的水产——草鱼，其他的成分譬如酸菜、红椒、蒜，也都是及为寻常的食材。第二，“粗”是说在烹调方式上粗犷豪放。在制作酸菜鱼时，人们往往用大把的花椒、胡椒、油来提升滋味，再与酸菜搭配，使得整道菜的味道非常刺激、开胃。第三，“杂”是指烹饪技巧不拘常法，灵活多变。制作酸菜鱼，需要先用料酒、盐等将鱼片进行腌制，再和酸菜、花椒、干辣椒、大蒜、八角等一起爆炒，最后将鱼片放入事先熬好的鱼汤中，仔细调味，浇热油提香。\n与许多江湖菜一样，酸菜鱼没有严格的用料规定与烹饪标准，流行之后，在中国各地厨师的手中，酸菜鱼都有着不一样的表现。但作为将鱼与酸菜结合的首创，突出的酸辣鲜口味在经受广泛的传播后非但没有被冲淡，反而愈发精进，这也是让酸菜鱼在几十年间风靡不衰的原因。"
  },
  [50] = {
    order = 50,
    id = 207,
    desc = "佛跳墙",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 4,
    miss = 4,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "八云玖",
    cv1 = "日高里菜",
    desc = "佛跳墙又名福寿全、满坛香，是清朝道光年间，福建省福州的一家菜馆“聚香园”的老板郑春发研制出的一种菜品。\n将海参、鲍鱼、鱼翅、干贝、鳖裙、鹿筋等几十种原材料，配以冬菇、冬笋等多种佐料，一起放入绍兴酒坛，以荷叶封口煨炖数日，取“吉祥如意、福寿双全”之意，名“福寿全”。后来在他用此菜款待客人时，品尝此菜的食客对福寿全令人震惊的美味心折不已，写下了“坛起荤香飘四邻，佛闻弃禅跳墙来。”的诗句，所以自此之后，福寿全便被大家称为“佛跳墙”。\n这道菜既有几十种原料共同的荤香，又保持着各自的特色，香味浓郁、嫩软鲜美、荤而不腻，但在煨制过程中几乎没有香味冒出，反而在煨成开坛之时，只需要略略掀开荷叶，便有令人迷醉的酒香扑鼻而来。酒香与各种食材的荤香混合，香飘四座，口感烂而不腐，让人回味无穷。\n佛跳墙不仅口感丰富，还具有很高的食疗价值，多次作为国宴主菜用来款待国内外贵宾，在世界各地都掀起了佛跳墙热。日本前首相田中角荣在中国尝过佛跳墙之后，还将其带回日本，现在日本东京的许多著名食府中均有佛跳墙。"
  },
  [51] = {
    order = 51,
    id = 209,
    desc = "糖醋里脊",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "TN千夏",
    cv1 = "暂无",
    desc = "糖醋里脊是一道来自中国的经典名菜，它的主料是猪里脊肉，在进行烹饪的时候需要先将切好里脊肉条放入由蛋清、料酒和盐调制的料汁中腌制一段时间，然后再让里脊肉均匀裹满淀粉、入油锅炸熟。之后另起一锅，加入油、糖、醋、料酒、葱姜——也可以加些许西红柿酱——勾兑成糖醋汁，再将它与放凉的炸里脊肉一起入锅翻炒。待到金黄里脊条与料汁充分结合，即可出锅盛盘。\n新鲜出锅的糖醋里脊外皮酥脆，肉香四溢又不失嚼劲，酸甜的料汁粘稠却十分爽口，毫无油腻之感，这种特别的口感令它在以咸口所支配的荤香诸菜中显得尤为独树一帜。这种“特殊”也使得糖醋里脊与众多的民间传说结缘，例如有传说称糖醋里脊始于秦朝，最早是秦始皇的母亲为始皇帝所做，还有一说糖醋里脊源于宫廷大厨为慈禧太后所做的创新……综合中国的饮食历史与文化考察，可以推定的是糖醋里脊最早应始于南宋，这是因为炒以及在料理过程中大量使用糖的烹饪方法均始于唐宋之间。\n无论事实到底如何，我们可以确信一点的是，糖醋里脊这看似简单的做法中其实包含着无数来着劳动人民的智慧，而人们对它的喜爱也随着时代的发展历久弥新。无外乎这小小一道菜能融入浙菜、鲁菜、川菜、粤菜等各大菜系，让全国各地的人们都热衷去烹饪它。"
  },
  [52] = {
    order = 52,
    id = 213,
    desc = "北京烤鸭",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 3,
    painter = "影法师",
    cv1 = "钉宫理恵",
    desc = "世界闻名的中国代表料理之一。\n将北京填鸭涂上糖水，并整只烘烤而成，大多时将其切片并用面饼包裹，和黄瓜，葱等一起食用。\n\n北京烤鸭的历史发展悠久，并发展出了“挂炉烤鸭”与“焖炉烤鸭”两大流派。\n北京烤鸭的前身被认为是出现在南北朝时期的“炙鸭”。\n“焖炉烤鸭”当初仅在宫廷中被食用，但于明朝嘉靖年间，开始针对一般民众贩卖，北京烤鸭也开始了更多方向的发展。\n清末年间，鸭子的料理方法也出现了多样性的发展，1864年，来自河北的师傅改良了烤鸭的烤制方法，采用挂炉方式烤制，使北京烤鸭发扬光大。\n\n正宗北京烤鸭使用的鸭种是世界著名的优良肉用鸭标准品种——北京鸭，原产于北京西郊玉泉山一带，现已遍布世界各地。\n\n北京烤鸭无论是在中国的高级餐厅，还是世界各地的中华街，都被当作广告牌料理看待，是远近驰名的中国国宝级的料理。"
  },
  [53] = {
    order = 53,
    id = 218,
    desc = "洛天依",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "stoner08",
    cv1 = "暂无",
    desc = "来自异世界的歌姬，有着纤细、温柔的心灵，能敏锐地感受到他人的感情，是一位努力用歌声传递感动与幸福的少女。\n来自中国的她深谙中华美食文化，对美味的料理没有抵抗力，食量也非常惊人。在一次偶然中，品尝到了薇琪摆放在异世界的、只有真正热爱料理的人才能看到的料理，随之被召唤到了料理次元。\n虽然起初有些震惊，不过洛天依很快便接受了现实。对她来说，如此充斥着美食的世界，不仅能满足胃口，还能带来崭新的冒险——作为创作灵感的来源，再好不过了。\n\n代表作：《千年食谱颂》、《普通 Disco》、《追光使者》、《权御天下》等。"
  },
