    painter = "sola7764",
    cv1 = "暂无",
    desc = "蒲烧鳗鱼是一种相当经典的日式料理，它的具体做法是将鲜鳗鱼破开并去骨，之后涂上以酱油为主制成的甜辣汁上火烤制。根据日本作家三田村鸢鱼提出的说法，蒲烧鳗鱼是在江户幕府刚刚成立的时候，在民间流行起来的食物，当时为了给参与兴建江户城的大量工人提供充足的食物，有人捕捉沼泽里的鳗鱼、将它们切成大块状串上竹签再刷上烧烤酱进行烧烤。由于整个鳗鱼并不切开，加上酱烧烤之后的型态和香蒲草的穗很相似，所以这种烧烤方式便被称为是“蒲烧”了。\n\n由于鳗鱼的油脂较多，能够帮助人快速补充能量，因而它被视为是能强身健体的食物，但它也因此被当做是只有贫苦的穷人才会食用的粗俗食物。现如今这种偏见已经彻底消失了，各种鳗鱼料理正丰富着人们的餐桌，更有专门烹饪鳗鱼的料理店出现。值得一提的是，虽然蒲烧鳗鱼好吃好做，但不同的厨师有着不同的处理鱼肉、烧烤鱼肉的办法，更有着独一无二的酱料秘方，这就令蒲烧鳗鱼的美味变得多彩而又神秘，总令人们捉摸不透却又难以自拔地流连忘返。"
  },
  [55] = {
    order = 55,
    id = 220,
    desc = "寿喜烧",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "一朵焼麦",
    cv1 = "暂无",
    desc = "寿喜烧，著名的日本锅物料理，是现今人们享受日本顶级牛肉的代表性烹调方法之一，让人大快朵颐又怎么吃都吃不够的美味料理。相传寿喜烧起源自锄烧，即古代农人们在农耕之余利用手头的农具烧烤食物与蔬菜的料理方法，但从日本的食用牛肉料理的历史来看寿喜烧应当是发源于近代的，其形式吸取了许多牛锅的烹饪方法。\n寿喜烧分为关东风与关西风两种。关东风的做法是先将牛肉加热至断生，然后迅速将香菇、葱、春菊等食材排入锅中，再倒入鲣鱼和昆布做成的“出汁”与调味料进行焖煮，这样做成的寿喜烧口味清淡鲜美，最大限度地保持了食材原本的美味。而关西风格的寿喜烧则不会事先放入汤汁，它是先利用牛油在铁锅上煎烤牛肉，待到肉半熟后放入寿喜烧酱汁，再排放入容易出水的蔬菜进行煎煮，这样做成的寿喜烧味道浓厚、口感层次分明。\n当然，无论是哪种风格的寿喜烧，在食用时都要先蘸上生蛋液，这样做不仅可以为刚出锅的食材降温，还可以让食材变得更加滑嫩可口。一定要熟记秘籍“搅拌·九又二分之一下”！\n……还有就是，寿喜烧并不是火锅哦？"
  },
  [56] = {
    order = 56,
    id = 226,
    desc = "晓",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "出身于东洋的武人，浪迹天涯的大剑豪。与娇小的身形不符，个性异常顽固认真，不达目的决不放弃。常凭修炼到极致的秘传剑术于危难中拯救萍水相逢之人，但却从不过问缘由、不追究对错、不与任何人发生纠葛。仿若暗夜里的月光，无言映照着人心善恶，是人们心中“拯救者”的化身。\n真实身份是前代春日山城守护之女、现任守护的妹妹，为了寻找杀害自己母亲与兄长的仇人踏上了复仇之旅，在不断磨砺刀锋的同时也在不断磨砺着自己的心之刃。\n不知因何缘故被带到这个异界。晓将此视作是一种试炼，并不断拯救被神秘领域——“死之视界”所吞噬的食灵，然而就在此时，宿命的春日山城与“那个人”的影子出现在她面前……"
  },
  [57] = {
    order = 57,
    id = 222,
    desc = "烤牛肉",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "烤牛肉是英国的传统料理之一。\n将牛肉块放在烤炉里蒸熟，切成薄片，再浇上肉汁汁食用。\n其特点是先烤表面，再用低温慢慢加热，这样吃起来不会失去红肉的柔嫩。\n它的起源能从被称为圣代烤面包的英国贵族的风俗中看到。曾经，贵族们为了慰劳佣人们一周的劳动，会在周日烤一整头牛给他们吃。\n这一习俗在不断改变的过程中一直延续到现代，至今英国还保留着周日吃烤牛肉的习惯。\n无论热或冷都能吃起来很美味的秘密在于，首先要烤好肉的表面，把肉的鲜味锁在里面。这种在红肉中经过时间浓缩而成的美味，作为美食，即使在远离英国的日本，也受到了很多人的喜爱。"
  },
  [58] = {
    order = 58,
    id = 223,
    desc = "烤串",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Asrid",
    cv1 = "暂无",
    desc = "——烤串，说到这个词大家的第一反应会是什么呢？也许有人会想到烤韭菜、烤面筋，也许有人会想到烤鸡翅、烤鸡胗……口味偏好影响着人们的记忆与选择，但从知名度与重要程度来讲，恐怕还是要把奠定了烤串基础的羊肉串排在首位吧？这种在中国颇为流行的食物始于在大都市中闯出一片天的新疆人们，他们选取上好的羊腿肉，切成大小合适的块状，然后放入由盐、香料粉等调制成的腌料中进行腌制。在进行烧烤的时候就将肉块用木钎或铁钎穿成一串，之后放在铺满木炭的长条形铁炉上来回翻烤。这是一种十分高明的做法，从烤炉下方升起的木炭香气和从上方飘下的孜然、辣椒粉香混杂在一起，让羊肉在熟成过程中散发的肉香变得更加诱人，路过的行人无不被这股原始的香气所吸引。\n当然了，没有谁会在大排档里只点羊肉串。就像火锅、炉式烤肉和麻辣烫一样，烤串与其说是一道料理，不如说是多种有同样做法的料理所构成的集合。它们一同激发着我们体内的古老记忆——一种可以追述到上古时代、人类的祖先刚刚学会享用火烤食物时大脑所获得的满足感。当人类寻找到食材被高温所加热之时，其中的蛋白质（尤其是脂肪）与碳水化合物便会发生一系列被称作是“美拉德反应”的复杂变化，这时食物内会产生大量的棕褐色大分子物质以及数百种具有不同气味的中间体分子，形成令我们感到愉悦的“色泽”和“香气”。一些科学家们相信正是对这种满足感的追求促使古人类更多地烹饪，然后令它们在生存竞争中获得更大的优势。而这种变化随遗传不断延续，最终成为对烹饪食物——特别其中最古老、最质朴的烧烤食物——对你我的致命吸引。\n换句话讲，喜爱烧烤是人类的一种“本能”。所以不要试图回避它的魅力，感激去买上几串烤串、在炎热的夏夜大快朵颐一番吧。"
  },
  [59] = {
    order = 59,
    id = 216,
    desc = "河豚刺身",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "M",
    cv1 = "暂无",
    desc = "河豚刺身──简单来说就是河豚做的刺身，把它的名字拆开来理解的话，就是把生河豚肉切成的薄片。和其他鱼的刺身相比，河豚的刺身肉片非常薄，这是因为河豚的肉比其他鱼的肉更为紧致，如果不切得很薄的话，嚼起来就会十分辛苦。正因如此，河豚刺身才会如此美味。\n除开刺身，河豚的历史非常悠久，在大约1万年前的日本绳文时代就发现了很多食用河豚的痕迹。 之后河豚也一直与日本的饮食息息相关，但由于在战国时代，河豚毒素导致许多士兵死亡，之后一直到明治时代中期为止，在日本的很多地区河豚都受到了管制。 但是即便如此，江户时代的菜谱上也登载了河豚的料理，而这种文化也一直流传到了现代。\n河豚自身并没有多少鱼类特有的腥味，清淡的鲜味很容易传达到舌头上，特别是生食刺身的美味会直接传达到味觉上。 和少量的橙醋和红叶萝卜泥一起吃的话，便能充分享受生食鱼肉的美味。"
  },
  [60] = {
    order = 60,
    id = 227,
    desc = "狼牙土豆",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 2,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "狼牙土豆——也即是狼牙土豆。是四川乐山的一种地方风味小吃，由天蚕土豆改进而来。四川各地的街边常常能看到贩卖狼牙土豆的小摊，已经可以说是人尽皆知，家喻户晓级别的小吃了。\n将土豆洗好削皮，用刀切成齿状，外形酷似狼牙，因此得名狼牙土豆（狼牙土豆）。与其原型天蚕土豆不同，狼牙土豆是与各式各样的蔬菜和佐料一起放入锅内翻炒而成，辣椒的辛香配合蔬菜特有的朴素清香，足以让人食指大动，比起仅有土豆和佐料的天蚕土豆，狼牙土豆显然更适合作为家常菜，乃是集成本低廉，做法简单，健康美味为一体的优秀菜肴。\n四川各地制作狼牙土豆的做法不尽相同，但却都是饱经岁月雕琢的独特做法，无论味道如何，只要看到土豆那锯齿状的外表以及或多或少的其他蔬菜，便说明那就是狼牙土豆。"
  },
  [61] = {
    order = 61,
    id = 228,
    desc = "绯夜",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良&Boom",
    cv1 = "柳知萧",
    desc = "来自缤纷星的新人武士，坚信努力可以得到一切，十分崇拜某位与天气变化相关的传说侠客。\n最开始见到刀剑，是在被恶人追逐的时候。在那时，携带暴雨的大侠如同天神降临。她牢牢的记住了那个身影，并暗自祈祷自己能拥有与那同样的，保护他人的力量。\n学习一项技能并不简单。绯夜最开始连木刀都拿的很费劲。但是经过长期的练习，木刀已经可以使用的很熟练了。\n在日常繁重的计划之余，绯夜也会做些调整自己状态的事情。比如去稍微远一点的地方修行，或者是坐在水果们附近煮一煮茶水。顺带一提，想和绯夜一样挥动沉重的长刀来准确的把水果切成可透光的薄片，这可是需要很惊人的训练量的。\n绯夜不止一次设想过，要如何呼唤风雨，以此来吓退那些作恶的人。但在结识了落樱之后，她突然意识到温柔和纯真也是难得可贵的能力。或许不必唤来风雨，她照样可以有和那位大侠一样的力量。\n“唉，最开始是真的很想找到大侠本人来学习刀法的。可是他的踪迹真的不好捉摸。就算是听说哪里出现了极端天气。赶过去的时候他也已经离开了。这也算一种遗憾吧。”\n尽管本人似乎还没有察觉。但在时间的流逝里，当初追逐传说的少女，如今已经成为了星系里新的传说。努力或许不能改变所有事，但它能改变多数事情。聚沙成塔，积少成多。今天的绯夜就是这个道理的最佳证明。"
  },
  [62] = {
    order = 62,
    id = 230,
    desc = "三叉姬",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良&酸奶",
    cv1 = "蘭雨馨",
    desc = "被叉子，鱼叉和叉戟钉死在一线天的龙族少女。虽以龙的身份死而复生，但那残酷的回忆却化作融入骨血的仇恨，形成了两颗不可磨灭的魔珠，满怀恨意的龙族少女发誓，所受屈辱，必将原数奉还！\n三叉姬还不是三叉姬的时候，曾居住在清澈的沉渊湖中。因为有她的存在，任何凶狠的怪兽都不敢冒犯这片领土。湖水鱼虾活泼，水草富足。居民们在她的守护下安居乐业，人们感谢天神庇护，却不知湖水下有这样一条龙。\n凶狠的怪物不敢靠近沉渊，却抵不住心生贪婪的人类。流窜的叛军点燃了村民的房子，砍伐茂盛的林地。他们拎着抢来的粮食和银币，想取沉渊的水来痛饮时，水中的龙悄然现身，撕裂他们的咽喉，扯断他们的臂膀，义无反顾的守护着被伤害的村民。\n传闻，吃掉龙的肉就能得到永生，沐浴被烈日灼烧过百日的龙血，人将战无不胜。\n心怀鬼胎的人们将龙奉为保护村庄的英雄，请她吃季节最好的葡萄和牛肉，饮用冰镇之后的麦酒。随后在夜里用叉戟刺穿她的胸膛，将奄奄一息的龙族少女钉死在悬崖峭壁任由烈日烧灼，满目贪婪的人们坚信传说，食烈日龙血之人，将永生不死，战无不胜。游于深水的龙族少女，被烈日烧滚了满身凉血，濒死之际，曾滚烫热情的心如深海般冰凉，走向魔化。\n普通人没有资格啃食龙的骨骸，龙被烹饪成精致的菜肴端上了尊贵之人的餐桌。他们用叉子分食了龙的身体，可等待他们的并不是永生，而是致命的毒素——龙族温柔的热血是永生的良药，因仇恨而魔化的龙，骨血却是最致命的毒，无知而贪婪的人类吃下了剧毒的龙血，痛不欲生的死去，而他们的后代，再也不会有一条为守护他们而义无反顾的龙。只有名为三叉姬的龙族少女，带着对人类溶于骨血的厌憎，于龙骨之下，死而复生。\n然而，经受背叛的龙族少女，似乎依然忘记不了，将弱小之人护佑于身后的本能。"
  },
  [63] = {
    order = 63,
    id = 231,
    desc = "白肉血肠",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "白肉血肠，也就是酸菜白肉炖血肠，也可以说是传说中的东北杀猪菜。\n　据《满洲祭神祭天典礼.仪注篇》记载，满族长期以来信仰萨满教，祭祀过程中，以猪为牺牲。每逢宫廷举行祭祀时“司俎太监等舁(即抬)一猪入门，置炕沿下，首向西。司俎满注入洲一人，屈一膝跪，按其首，司俎满洲执猪耳，司祝灌酒于猪耳内……猪去息后，去其皮，按节解开，煮于大锅内，……皇帝、皇后亲诣行礼……，神肉前叩头毕，撤下祭肉，不令出户，盛于盘内，于长桌前，按次陈列。皇帝、皇后受胙，或率王公大臣等食肉。”这种肉叫“福肉”即“白肉”。所谓血肠，即“司俎满洲一人进于高桌前，屈一膝脆，灌血于肠，亦煮锅内”，这就是血肠，通称“白肉血肠”。清代沈阳和吉林地区开设的白肉馆，都兼营血肠。慢慢的，这道料理也演变成为了辽宁和吉林省满族特有的传统名菜。\n制作这道料理时，通常就是把所有的材料塞进大铁锅一炖就完成了，这种方法也堪称东北人做菜的精髓，乱七八糟一股脑，问题是，还很美味。不过，比起其他的东北炖菜，白肉血肠的味道层次明显要丰富很多，这也是托了那几样食材的福。不仅仅是血肠，这里的酸菜也和南方的酸菜不同——南方酸菜的原料一般是芥菜，北方则一般用大白菜，这两者最后适合烹饪的料理也大有不同，我们熟知的酸菜鱼就是这样。啊，当然，料理次元的食灵们无论是用哪种酸菜，都是干净又卫生的，可不是拿脚踩出来的哟。"
  },
  [64] = {
    order = 64,
    id = 232,
    desc = "异界·薇琪",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 3,
    painter = "朝露",
    cv1 = "ファイルーズあい",
    desc = "在小岛国海蓝的内部冲突中失去双亲，危急时被某个拾荒者小队所救，将她带到了墨涅塔西亚。受到了拾荒者照顾的她从此便励志成为一名能够帮助他人的拾荒者。从小带着的锅子便是以前恩人留下的礼物。\n因为当时薇琪的年龄过小，无法加入拾荒者的队伍，短暂地相处便于恩人分别。之后在机缘巧合中遇见了安西娅，与她一起加入了舒儿的拾荒队。\n\n纯真的少女，对任何事情都保持着乐观态度。\n特长只有料理，因为是笨蛋，非常容易被骗。让人放心不下。\n所有的魔物在眼里都是食材，对料理的偏执程度甚至有鬼畜的感觉。\n梦想是称为恩人、也是偶像——荒原美食团队长赫琳那样伟大的拾荒者。"
  },
  [65] = {
    order = 65,
    id = 234,
    desc = "煤梅",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良",
    cv1 = "小眠",
    desc = "“煤梅当然也是煤球啦！”——当你质疑煤球会有人形时，煤梅会一边大声纠正，一边气呼呼地吐着小舌头。煤梅自小就和其他煤球长得不一样，至于原因？没有人知道。小时候的煤梅对不同的长相耿耿于怀，但自从迷上了烹饪，就释怀了——虽然经常炸厨房就是了……/n煤梅喜欢甜甜的东西。第一次尝到棒棒糖的美味记忆一直缠绕在煤梅脑中，幼小的煤梅想，如果自己能像棒棒糖一样，就不用担心外表的问题了，于是成为一只甜甜的棒棒糖变成了她的梦想——某种意义上也算是和自己达成和解了吧～/n煤梅在机械方面有着非凡的天赋，长大后她成为了煤老板商店的一位售后服务工程师（主打飞船和武器维修方向），平时一般都是远程服务，倒也不是煤梅不喜欢出门，只不过她实在是好奇心过重，容易乱跑，为了保证降低成为走失煤口的频率，所以煤老板会尽量少让她出门！/n改变煤梅命运的，是那唯一一次的上门维修服务—一个来自宇宙海盗某舰队的委托。梅煤来到那艘海盗飞船的当天，正好遇上了内部叛变。叛变成功的海盗将看起来一脸傻气的煤梅绑起来，意图勒索煤老板。不过呢……煤梅可是行走的兵器库和工具箱，普通的手段怎么能困得住她！煤梅三下五除二解除了枷锁，并不断掏出各种重型武器将一众海盗全部打趴在地，之后又经过了这样那样的危机，煤梅居然阴差阳错地成为了这只海盗小队的舰长！只是煤梅自己对此毫无知觉，她依然以飞船工程师自居。/n煤梅身上有一个至今无人能解的谜团……煤梅总能从全身上下掏出各种大型的武器——至于那些大型武器与道具究竟是煤梅从哪里掏出来的？没有人知道。不过就算去问煤梅，她也只会呆呆地看着你，一副完全听不懂你在问什么模样——所以这件事逐渐成为了海盗团七大不可思议事件之首的存在。/n发觉自己可以自由探索宇宙的煤梅很兴奋，好奇心泛滥的她告别了煤老板，寻找可以让自己变成棒棒糖的办法。今日的煤梅也在果冻星系中飘呀飘，沉迷于各种稀奇古怪的事件之中。"
  },
  [66] = {
    order = 66,
    id = 235,
    desc = "魔王",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "魔王，来历不明的少女，拥有极为强悍的战斗力。\n据说她曾经是一统天下的将军、乃至于暴君一样的存在。\n来到料理次元后，她半分没有忘记她曾经的理想。\n一屋不扫，何以扫天下？\n嗯，就让我那位首席幕僚帮我占领新的城池吧？\n至于我……不吃掉面前的蛋糕，哪有力气走远方？\n望着远方吃着黑森林蛋糕的魔王，随意地这么想着。"
  },
  [67] = {
    order = 67,
    id = 236,
    desc = "曹操鸡",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "曹操鸡也称逍遥鸡，始创于东汉末年，该菜品为安徽省合肥市的一道地方传统名菜，属于徽菜系。曹操鸡选料严格，要求鸡身肌肉丰满、脂肪厚足、胸肉裆油较厚；制作工艺考究，用老汤浸煮；成菜后，形体丰满、造型美观、色泽金黄、香气浓郁；吃起来骨酥肉烂、味道鲜美、余香满口，而且营养丰富、有食疗健体之功。\n关于曹操鸡，还有一个很经典的历史故事，早在东汉时期的庐州地处吴国和魏国交界处，为兵家必争之地。汉献帝建安十三年曹操统一北方后，从都城许昌率领八十三万大军南下征伐孙吴。因过度疲劳，在庐州时，曹操的头痛病再度发作，卧床不起。行军膳房厨师遵照医嘱，选用当地仔鸡配以中药、白酒，烹制成食疗“药膳鸡”。曹操品尝后，感觉味道不错，就一连吃了不少，不知不觉地感到头痛病轻多了。为了尽快将病治好，曹操令厨师们每顿都做这种鸡给他吃。他接连吃了数天，身体渐渐康复，数日后便下床了。从此以后，不论部队开到哪里，只要有条件，曹操都要吃这种“药膳鸡”。后来，这种既有营养价值，又可防病、治病的菜肴渐渐传开，人们为这道药膳菜命名为“曹操鸡”。"
  },
  [68] = {
    order = 68,
    id = 229,
    desc = "松鼠鱼",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "松鼠鱼，这道小有名气的中华料理，卖相独特，色泽鲜艳，酸甜可口，又有一个惹人好奇而不失可爱的名字。它是一道苏系名菜，通常以黄鱼，鲤鱼和鳜鱼等鱼类作为原料，因装盘后形似松鼠而得名。\n说起松鼠鱼的历史，可追溯到乾隆年间——据说早在乾隆皇帝下江南的时候，万岁爷便品尝过苏州一带的“松鼠鲤鱼”，后来又发展成“松鼠桂鱼”。据清代《调鼎集》记载:“取季鱼，肚皮去骨，拖蛋黄，炸黄，作松鼠式。油、酱油烧。”可见当时，“松鼠鱼”身上的衣裳还是蛋黄糊，但是在现代，厨师们更习惯于用拍干淀粉。\n至于具体做法，包括前期极其考验刀功的剔骨刺，切花刀，以及一些必需的清理工作。以适量佐料，提前将鱼腌制，拍粉。油炸后，另烹糖醋芡汁，浇在鱼上后出菜。\n相比于古时候，如今的松鼠鱼造型更为逼真，口味也更有层次感，其味酸甜可口，仿佛淘气的精灵在口中雀跃，便也更加对得起这个有趣的名号——这都是以前的“松鼠鱼”难以比拟的。\n由此可见，中华料理始终在源源不断的发展，更新，传承——大概这就是中国菜不可忽略的一大魅力吧。"
  },
  [69] = {
    order = 69,
    id = 233,
    desc = "麻辣兔头",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "说起麻辣兔头，最有名的莫过于川地的老妈兔头。它起源于四川省成都市双流县\n  正宗成都“双流老妈兔头”，起源于二十年前一位慈祥的妈妈，她在双流县城开了一间麻辣烫小吃店。这位妈妈的儿子从小爱吃兔头，那时候成都吃兔头的店很少，妈妈心疼儿子，便在麻辣烫的锅里煮给儿子吃。倾注着母爱的兔头不仅让儿子解馋了，更是让他吃的上了瘾。于是，儿子天天在店里吃兔头的模样，仿佛一块招牌，吸引了登门的客人。慢慢的，这兔头一传十、十传百，麻辣鲜香的兔头吸引的人越来越多。聪明的儿子建议妈妈将小店扩大，专卖兔头。因为大家都亲切而尊敬的称她老妈，店名干脆就叫——“双流老妈兔头”。 二十年岁月沧桑，“双流老妈兔头”早已成为成都食客追捧的知名美味，多年来老妈一直寻找品相整齐、肉质细嫩的兔头，味道纯正、回味醇香的麻辣调料，做出味道纯正的老妈兔头。\n　现在，麻辣兔头已经成了一道川蜀名吃，活跃于各大麻辣烫小店等餐馆。虽然还有人觉得“兔兔这么可爱，怎么可以吃兔兔”，不过，真的把这道料理摆在你面前的话，你能保证自己能顶住它的诱惑吗？"
  },
  [70] = {
    order = 70,
    id = 237,
    desc = "活蛙派",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "暂无",
    desc = "活蛙派，又名“活蛙飞鸟派”，乍听之下只觉得恶心残忍，这种“黑暗料理”怎么能搬上餐桌，又怎么能下咽呢？但与名字溢满的血腥味不同，这其实是一道“恶作剧”与“庆祝”的料理，在中世纪常用于圣诞假期的第十二夜等节庆之中。\n  一般在活蛙派出现的场合，同时也需要制作“会流血的公鹿糕”和“会爆炸的船与城堡”。而活蛙派则放置在“会流血的公鹿糕”两侧。\n  在盛鹿的大浅盘两端各放一个用粗面煳做成的派，一个派里放些活青蛙，另外一个里头放些活的鸟儿。这些派在制做时得填入米糠，然后用番红花或蛋黄染黄。烤熟之后，在派底挖洞，藉此漏出米糠，填入蛙或鸟，然后用相同的粗面煳将洞封住。\n  等到来宾尝完盛满波尔多红酒的“会流血的公鹿糕”，引爆了面糊做成的船与城堡，众人得以休息，开始品尝美味的派之时。谁能料想众人首先将其中一个派的顶端掀开，结果跳出青蛙，这肯定会让女士们急跳脚加惊声尖叫；接着打开另外一个派，飞出来一群鸟，鸟的天性会趋光，由此照明的蜡烛会被拍灭。于是乎就这样飞鸟在上、跳蛙在下，现场大伙儿必然闹哄哄地笑成一片。\n  这道料理被记载于1660年罗伯·梅的著作《厨师的修为》中。"
  },
  [71] = {
    order = 71,
    id = 238,
    desc = "红烧狮子头",
    open = 1,
    atkSpeed = 5,
    hp = 3,
    atk = 5,
    phyDef = 3,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "暂无",
    desc = "红烧狮子头，一道承载着团圆吉祥寓意的中华经典名菜。其名虽霸，实则温润——取“狮首”之雄浑造型，喻“团圆”之美满内涵。这道菜精选肥瘦相间的猪五花，手工剁制成蓉，其间掺入荸荠或嫩藕粒以增爽脆，团成硕大饱满的肉丸后，先经油炸定形锁住鲜香，再以文火慢炖，让浓油赤酱的醇厚滋味丝丝渗透。成菜色泽红润油亮，肉质酥烂软糯，入口即化，鲜香与清甜在口中交织，肥而不腻，堪称淮扬菜系中“粗料细作”的典范。无论是家庭团聚还是佳节宴席，这一颗圆融饱满的狮子头，都是对美满团圆最温暖、最厚重的味觉诠释。一道承载着团圆吉祥寓意的中华经典名菜。其名虽霸，实则温润——取“狮首”之雄浑造型，喻“团圆”之美满内涵。这道菜精选肥瘦相间的猪五花，手工剁制成蓉，其间掺入荸荠或嫩藕粒以增爽脆，团成硕大饱满的肉丸后，先经油炸定形锁住鲜香，再以文火慢炖，让浓油赤酱的醇厚滋味丝丝渗透。成菜色泽红润油亮，肉质酥烂软糯，入口即化，鲜香与清甜在口中交织，肥而不腻，堪称淮扬菜系中“粗料细作”的典范。无论是家庭团聚还是佳节宴席，这一颗圆融饱满的狮子头，都是对美满团圆最温暖、最厚重的味觉诠释。"
  },
  [72] = {
    order = 72,
    id = 303,
    desc = "香菇盒",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 2,
    hit = 2,
    miss = 3,
    growth = 2,
    skill = 3,
    formation = 1,
    painter = "TN千夏",
    cv1 = "筱原侑",
    desc = "中国安徽名菜“香菇盒”。\n将煮好的香菇扣夹肉馅，清蒸，再勾薄芡，浇在蒸好的香菇盒上而成。\n香菇被认为是低热量、高蛋白、高纤维食物，蛋白质方面含有多量优质氨基酸等，其他维生素类也颇多，尤其富含维生素D。此外，香菇尚含有多糖类物质香菇多糖（Lentinan），其中一种β-1,6-葡聚糖注射入人体则有抗癌作用。\n因此香菇盒不但好吃，而且有很大的营养价值。适合任何年龄段的人享用。"
  },
  [73] = {
    order = 73,
    id = 309,
    desc = "土豆泥",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 2,
    skill = 2,
    formation = 1,
    painter = "6音",
    cv1 = "小仓唯",
    desc = "料理白痴的救世主——土豆泥！\n土豆泥的做法异常简单，人人都能上手，即使不会做饭也可以做出好吃的土豆泥，因为只需将整颗土豆煮熟，再去皮压成泥，加入各种符合口味的佐料就可以了。但如果想要做得卖相漂亮、口感诱人，也得费一番功夫。\n土豆泥在西餐中广受欢迎。欧美各国厨师发明了芝士焗土豆泥、火腿土豆泥、鸡汁奶香土豆泥等料理，将土豆泥赋予了全新的味道，不但更加香滑软糯，加入的多种配料也兼顾了口感和营养。\n土豆泥的主料——土豆，不仅产量高，营养也非常丰富，甚至有专家研究，人类每天只吃土豆泥和全脂牛奶，就能满足所有的营养需求。历史上，早在公元前8000年到5000年，秘鲁南部的印第安人就开始食用土豆了，在十六世纪中期，土豆被西班牙殖民者从南美洲带回欧洲，但在当时，土豆在欧洲是被当做花朵观赏植物的，直到十八世纪前后，欧洲人口急剧增加，主要粮食作物无法满足需求，英法德政府才开始大力推广土豆这种耐寒产量高营养丰富的食物。德国七年战争时期，德国人就是靠吃土豆坚持到了最后的胜利。为了纪念当时大力推广土豆的德国腓特烈二世大帝，直到现在，人们在他墓前供奉的还是土豆。"
  },
  [74] = {
    order = 74,
    id = 310,
    desc = "苏格兰蛋",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 2,
    miss = 3,
    growth = 2,
    skill = 4,
    formation = 2,
    painter = "翼酱",
    cv1 = "暂无",
    desc = "传说由英国著名食品商店兼百货公司 Fortnum & Mason 在18世纪发明的食物。当初的做法，是将新鲜香肠肉绞碎后，中间包上一枚水煮蛋，最后在外表裹上一层面粉经过油炸即成。\n\n现在的做法，与传统几乎没有差别，但是选材更为讲究。鸡蛋选用一周内的新鲜蛋，煮制五分半，迅速捞出放入冰水，能够获得品相极佳的糖心蛋。接着，肉馅中放入芝士碎、盐、黑胡椒和干香草拌匀，包住鸡蛋后揉成球状。最后按照面粉、蛋液、面包糠的顺序裹好，在六成热的油锅中中小火炸五分钟即可。\n\n也有人觉得鸡蛋裹上肉馅后，体积过大难以下口。所以如今也有使用鹌鹑蛋代替鸡蛋，制成小型苏格兰蛋的做法。"
  },
  [75] = {
    order = 75,
    id = 302,
    desc = "西芹百合",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 3,
    skill = 4,
    formation = 4,
    painter = "Asrid",
    cv1 = "内田彩",
    desc = "家常菜中华料理西芹百合。\n顾名思义就是把西芹和百合放一起炒。\n西芹百合除了食感外，被广为人知的还有其药用效果，无论是西芹还是百合，都是现代中医的重要药材，西芹百合有促进食欲、降低血压、健脑、解毒消肿、促进血液循环等功效。\n药膳菜单中，也常会载入西芹百合。\n而和美丽的菜名一样，百合有美容的功效，因此西芹百合在女性中拥有很高的人气。\n要注意的是并不是所有的百合都可以食用，因此在挑选食材时要分清百合是观赏用还是食用。"
  },
  [76] = {
    order = 76,
    id = 306,
    desc = "九珍法式蔬菜冻",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 3,
    miss = 3,
    growth = 3,
    skill = 3,
    formation = 3,
    painter = "teeth",
    cv1 = "暂无",
    desc = "所谓的“法式冻”一般指的是在法式料理中被称为“Terrine”的前菜料理，它通常是用多种动物的肉或内脏绞成肉糜、连同香草或其他调味料一起压入被称为“Terrine”的容器中烹饪而成。法式蔬菜冻就是“Terrine”的纯素版本，经过厨师的改良变为一道单独的料理。它的原料一般有黄瓜、秋葵、卷心菜、胡萝卜、西葫芦、玉米笋、西芹、花椰菜、竹笋等，制作的时候厨师需要先将这些蔬菜清洗、切块、焯熟，然后分层压入长方形容器中，之后再注入用多种调料与香料调制的汤汁与吉利丁水，密封，冷藏数小时甚至数天待到其从内到外的缝隙完全胶化便可以食用了。\n成品的法式蔬菜冻外观惊艳、口味清新，时令蔬菜的颜色层叠排布，被凝胶化吉利丁所保留，在口感上冰凉的冻皮下是新鲜的蔬菜，清淡的咸香中透出食材的原味，而搭配特制的料汁食用又是另一番风味，着实是一道看看似简单但又让人回味无穷的美味料理。"
  },
  [77] = {
    order = 77,
    id = 307,
    desc = "烧麦",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 3,
    skill = 2,
    formation = 3,
    painter = "LF",
    cv1 = "日高里菜",
    desc = "烧麦，又称烧卖、捎卖、烧梅等，是一种以烫面为皮，裹上各种馅料上笼蒸熟的小吃。起源于内蒙古地区，最早的史料记载是十四世纪高句丽的汉语教科书《朴事通》，书中写有在元大都（北京），有商家出售“素酸馅稍麦”的记载。早年的烧麦多在茶馆出售，食客喝着浓浓的的砖茶、叶茶，捎带着买些小吃糕点一起吃，所以在那时烧麦被称为“捎卖”，就是捎带着卖的意思。\n \n到了明清时代，逐渐出现“烧麦”的名称，品种也从过去“以面为皮，以肉为馅，当顶做花蕊”的单一肉馅，变成多种多样口味馅料的烧麦。清代无名氏编撰的菜谱《调鼎集》中，便收集有“豆沙烧麦”、“油糖烧麦”等。到了现代，烧麦的品种更为丰富，馅料更有鸭油、鲜虾、猪肝、蟹肉、牛肉、蛋肉等等，各具地方特色。\n \n在日本，烧麦也在中华料理小吃中占有地位，也许是因为有中华街的关系，位于神奈川县的横滨，烧麦已经成为家庭日常购买食物品种的首位，横滨站也配有昭和小说家狮子文六所创作的、成为了烧麦广告牌娘的小说人物“烧麦娘”。"
  },
  [78] = {
    order = 78,
    id = 312,
    desc = "瑞士鸡翅",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 3,
    growth = 3,
    skill = 2,
    formation = 4,
    painter = "ex-hentai",
    cv1 = "金子彩花",
    desc = "瑞士鸡翅虽然名字中有“瑞士”，但来源其实和那个中欧国家并没有什么关系，是土生土长的中华料理。\n这道料理可以看做是用甜卤烧出的鸡翅，浇鸡翅的甜卤便是这道菜的精髓——瑞士汁。瑞士汁的发源地是香港，在上世纪六十年代，有两位擅长做“豉油西餐”也就是中式配料、西式做法的厨师徐氏兄弟，创作了一道名为“豉油鸡翅”的菜，有西洋人吃过后觉得异常甜香可口，不停称赞此菜“Sweet！”，但当时店内跑堂的英语不好，就去问别人这句英语什么意思，在信息传递的过程中出现了差错，把Sweet说成了瑞士的发音Swiss，自此，这道菜的名字就变成了瑞士鸡翅，豉油浇汁也被称作“瑞士汁”流传至今。\n直到现代，在香港的茶餐厅里还少不了这道瑞士鸡翅，成为了深受大众喜爱的平民料理。"
  },
  [79] = {
    order = 79,
    id = 301,
    desc = "天妇罗",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 3,
    growth = 4,
    skill = 3,
    formation = 3,
    painter = "stoner08",
    cv1 = "杜和佑纱",
    desc = "天妇罗与寿司，刺身齐名为日本料理三大种类，是日本的代表性料理之一。\n主要做法是将海鲜，蔬菜等食材沾上鸡蛋与小麦粉混合的汁液，油炸后制作而成。\n本来是在江户时期的屋台等地方随处可以吃到的大众食品，但同时也有天妇罗专门店那样的高贵的一面。\n日本奈良时代-平安时代，已经有用米粉包裹食材的料理出现，但“天妇罗”这个名称在文献上首次登场是在1669年（宽文9年）由京都医师奥村久正所写的《食道记》中。\n天妇罗这种料理可以搭配非常多的食材，例如秋天时，有一种叫做“红叶天妇罗”的料理，枫叶会经过用盐腌制一整年，并且加上甜面粉调味，常见于大阪箕面市。\n麻辣烫里常见的被称作甜不辣的东西，其实就是在日本被称作萨摩扬げ（萨摩炸）的东西，萨摩扬げ在日本的某些地方(如九州岛岛)，也被称为天妇罗（天ぷら）。而甜不辣这个发音，其实正是日文天妇罗（天ぷら，tenpura）的发音。可能的原因是把萨摩扬げ称作天妇罗的日本九州岛岛人，传播了这种料理到了台湾，而台湾又把它译名为甜不辣传回了大陆。因此即使发音是一样，但是天妇罗和甜不辣指的并不是同一种料理。"
  },
  [80] = {
    order = 80,
    id = 305,
    desc = "瑞典鲱鱼罐头",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 3,
    hit = 3,
    miss = 2,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "mvv",
    cv1 = "杉浦しおり",
    desc = "瑞典产的被称为“世界第一臭”的鲱鱼罐头。\n将鲱鱼放入盐水中自然发酵，并封入罐头中完成。\n瑞典鲱鱼罐头原名“Surstromming”，“sur”意为“酸味的”，“stromming”意为“波罗的海鲱鱼”。\n在罐头封装技术诞生之前，瑞典人就已经有将鲱鱼放入盐水中保存的习惯。\n在中世纪，瑞典虽然盛产鲱鱼，但是因为地理环境原因缺乏材火和日照，因此用以腌制和保存食物的盐是贵重品。也因此出现了将鲱鱼放入盐水的保存方法。\n虽然放入盐水中，可以防止鲱鱼的腐败，但是却没有办法阻止鲱鱼的发酵，因此也产生了大量由发酵导致的臭气。\n产生这种恶臭的物质主要包含，丙酸、硫化氢、丁酸、醋酸等，部分物质浓度过高时会对人体产生实质损害，因此千万不要在密闭空间内同时打开数个罐头。\n国际上大多航空公司都把瑞典鲱鱼罐头列为禁止空运的食品，原因是其有爆炸的危险，2014年5月1日，胡迪克斯瓦尔一间仓库起火，使仓库内数千个正在发酵的鲱鱼罐头发生爆炸并飞出仓库。\n瑞典鲱鱼罐头的上市日是八月的第3个星期四，适宜的食用期间为9月，在现代可以通过网络预约，并通过海运获得。注意如果船只通过热带地区时间过长，有可能导致罐头内的鲱鱼发酵得完全液状化不留原型。\n瑞典鲱鱼罐头是适合有勇气的吃货们挑战的难得珍品，吸引着各国吃货络绎不绝地挑战。"
  },
  [81] = {
    order = 81,
    id = 311,
    desc = "章鱼丸子",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 2,
    hit = 3,
    miss = 3,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "水熊",
    cv1 = "暂无",
    desc = "章鱼小丸子，它有另一个更广为流传名的名字，即章鱼烧。这种料理的主要材料是章鱼、章鱼烧粉、海苔，根据地方口味与店家流派配以蛋黄酱、千岛酱或芥末酱等酱汁。一口咬下去，面球焦香、章鱼弹牙，浓稠的烧酱和香脆的海苔片在唇齿间碰撞，美味到让人停不下来。\n章鱼烧如此美味，制作起来却不困难，一份餐车、一份材料、一份耐心与手艺就能迎来络绎不绝的客人，这令章鱼烧迅速推广到了东南亚各地，成为“街头一霸”。不过本身的历史却并不久远，它的历史可追述到二十世纪三十年代，它的前身是一种以牛肉为原料的丸子状料理，因为长的很像是当时的收音机按钮，因此得名“Radio烧”。而后的某日，店主在热爱明石烧的顾客的启发之下想到了用章鱼须来代替馅料，于是章鱼烧就这样“随便”的诞生了。话虽如此，章鱼烧的美味离不开无数店家的改良与智慧，在品尝章鱼烧的时候请不要忘记心怀感激，并请求店家加上双份的蛋黄酱哦？"
  },
  [82] = {
    order = 82,
    id = 304,
    desc = "玉子烧",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 2,
    hit = 4,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 3,
    painter = "薯子",
    cv1 = "花泽香菜",
    desc = "玉子烧是日本家庭料理的一种，经常作为配菜出现在便当中。\n原料非常单纯，主要食材仅仅只有鸡蛋，最特殊的地方是其烹饪手法和所用的独特厨具。\n将打好的鸡蛋放在矩形的平底锅中一边煎一边加入酱汁调理，然后卷成筒状是玉子烧的常规做法\n一般认为玉子烧的诞生是在江户末期的京都，宽永20年（1643）出版的《料理物语》中，有一个称作“玉子软绵绵”的料理，被视为是玉子烧的原型。\n日本人在江户时代之前都不怎么食用鸡蛋。过去在日本，鸡的饲养目的主要是作为“斗鸡”来使用，而非食用。尤其在1300-1400的日本因为受到佛教的强烈影响，而禁止食用动物的肉和卵。\n在战国末期，葡萄牙等西方国家的商人来到日本，将使用了鸡蛋的甜品，例如卡斯提拉传播到了日本，使日本人认知到了鸡蛋的美味。但当时的鸡蛋产量稀少，价格太高的鸡蛋使一般百姓不太容易获得。因此意外的玉子烧过去是高级料理。\n而在现代，因为鸡蛋变得便宜，所以玉子烧成为了日本家庭料理的宠儿。\n现代的玉子烧中往往会加入更多的甜味，主要是作为家庭料理的地位确立，让其更加符合小孩子的口味。"
  },
  [83] = {
    order = 83,
    id = 308,
    desc = "小笼包",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "黑萌",
    cv1 = "水瀬いのり",
    desc = "诞生于中国江南地区的著名点心，以“体小、馅大、汁多、味鲜、皮薄、形美”着称。\n正宗小笼包的馅必须选用猪腿肉，细细切成臊子，然后加入适量盐、糖、白酒、姜末与葱末制成。汤的质量取决于皮冻，用去掉皮下脂肪的猪皮，捶打去腥后加入鸡汤或牛骨汤煮烂、冷却而成。关于面皮的讲究则更为复杂，要求要薄、韧，呈半透明状态；上方的褶子除了熟透外还要捏得美观，这是小笼包外形的关键。\n关于小笼包的起源，最早可上溯自北宋。靖康之难后，宋室南渡，并将饮食习惯也一起带到南方，小笼包因此成为江浙一带的代表食物。清朝之后，在今常州、无锡一带出现了与现代形式更为接近的小笼包。\n如今，小笼包流行于全国各地，逐渐形成了上海南翔、无锡、绍兴喉口、台湾等多个流派，并且在海外也十分受欢迎，是各家海外中餐馆必备的主力食品。"
  },
  [84] = {
    order = 84,
    id = 313,
    desc = "茶碗蒸",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 3,
    phyDef = 4,
    hit = 2,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "左也",
    cv1 = "柚木尚子",
    desc = "茶碗蒸，一种传统日式的料理，从食材与做法上来看即是一种“日式蒸蛋”。它的做法可以说非常简单——将香菇、鲜虾、蟹柳、蛤蜊、干贝、鱼肉、菠菜等食材稍作处理后拼入茶碗，再注入入用纱布滤掉小气泡与絮状物的蛋液，以及盐、日式高汤等调料，随后将用扎出小孔的保鲜膜封好茶杯、置入蒸锅当中，先大火快蒸2-3分钟，再转小火蒸制15分钟左右，待到出锅之时，鲜美诱人的茶碗蒸即算是大功告成。\n这道料理虽然看似平淡，但口感浓厚、内藏乾坤；小小一碗蒸蛋虽不能令人大快朵颐，但它蕴含着日式料理的精髓与日本人含而不露的处世哲学，作为会出现在怀石料理当中的美食，若搭配着茶饮一起食用，则可以令人充分地享受到茶饮的美味而不必因空腹饮茶而遭受腹痛之苦。"
  },
  [85] = {
    order = 85,
    id = 314,
    desc = "罗汉斋",
    open = 1,
    atkSpeed = 3,
