    painter = "山药酱",
    cv1 = "暂无",
    desc = "罗汉斋，亦名“罗汉菜”，其名有“十八罗汉聚集一堂”之意，类似四喜丸子的“四喜”，指这道菜包容着众多美好事物与祝福。这里的“十八”其实是个虚指，罗汉斋并没有固定的主料限制，只要是应季的新鲜时蔬，例如香菇、草蘑、木耳、叶菜等都能被绘于一锅、加工成罗汉斋，颇有佛教中“随缘而安”的味道。\n不过，提到罗汉斋时不得不提及中国的素斋文化：按照人们一般的理解，素即无肉，无肉是因不好杀生，素斋即寺庙中僧人们所食用的饮食——其实恰恰相反，素斋的起源并不是寺庙，而是宫廷，这是由于中国历史上有众多信奉佛教、遁入佛家的皇帝、官员，在此机缘牵引之下佛教与宫廷的交会甚多，汇聚了多种珍贵时蔬的素斋正诞生于这些“贵客”被接待的过程当中，因而素斋所体现的并不都是佛教思想，它还包含了中国传统饮食文化中荤素搭配、以素代荤的贵族式饮食均衡理念。时至今日，以罗汉斋为代表的种种素斋已普及进民间，成为了人们眼中素食料理的巅峰之作。"
  },
  [86] = {
    order = 86,
    id = 315,
    desc = "黑布丁",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 3,
    phyDef = 2,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 4,
    formation = 4,
    painter = "西行寺科学子",
    cv1 = "暂无",
    desc = "黑布丁来自欧洲，但与人们传统印象中的甜品布丁不同，是一种由肠衣包裹风干猪血制作而成的料理，味道偏咸。在十七世纪的英伦菜谱《打开南尔姆·迪戈比爵士的私室》中有关于它做法的描述：“取三品脱奶油，与四分的肉豆蔻、三四瓣大个的肉豆蔻干皮、一根肉桂枝同煮，然后取一些美好的香料，捶打他们，并将其汁液挤进和杏仁一起捣好的奶油里。再取两三勺鸡血，两三勺面包屑，六七根骨头的骨髓，糖和盐，和一点蔷薇水，把所有东西混合起来，填充布丁。你还可以放入八个或十个鸡蛋，和两个打好的蛋白，或者放进一些麝香或龙涎香。\n 现在的黑布丁配方要简单许多，猪血之外加上一些脂肪、洋葱碎和谷物就可以了，但欧洲各地的做法都有所不同。英国人通常会加入燕麦片，法国人喜欢用奶油和牛奶，而在西班牙，人们会使用杏仁、甜椒和欧芹。用这些配料加工后的黑布丁，不仅没有血腥味，质地还更加细腻，口感软糯，是许多餐厅的理想配菜。\n关于黑布丁，还有一些历史悠久的传说，其中最著名的是 16 世纪英格兰国王亨利八世的故事。据说但凡是这位国王举办的宴会，餐桌上必有黑布丁出现，有历史学家形容亨利八世对黑布丁的喜好是“无尽的爱”。而更早在 15 世纪的玫瑰战争，还有黑布丁被用作投掷武器、攻击敌人的传说。直到现在，每年 9 月，英国的约克郡还会举行扔黑布丁的比赛，要求参赛者在 20 米开外的地方，将带有提手的黑布丁扔到高塔的塔尖，挂到塔尖数量最多的人获胜。\n作为一款价格低廉的食品，黑布丁仅含有不到 5% 的脂肪，但其他营养素（例如铁）的含量却十分丰富，加上不逊于甜品布丁的软滑口感，让黑布丁受到了很多食客的青睐。"
  },
  [87] = {
    order = 87,
    id = 316,
    desc = "四喜丸子",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "咩煲",
    cv1 = "暂无",
    desc = "四喜丸子是经典的中国传统名菜，一如所见的是四个丰盛的大型肉丸，分别寓意着人生的福、禄、寿、喜，谓之四喜。因而常用于喜宴、寿宴等宴席中做压轴菜，以取其四喜临门之意。\n虽说是不同的东西，但四喜丸子与另一道名菜狮子头比较相似，在做法上也有异曲同工之妙。不过、若想把美味浓缩于在这个四个丸子之中而不是以量取胜，制作者就得在制作四喜丸子时下更多的功夫——\n比方说若想保证四喜丸子的“色”好看，用于提味的葱花就不能直接混放在肉馅之中——那样做的话，葱花会在丸子下锅过油时因高温变黑变糊，影响丸子的外观。\n比方说若想保证四喜丸子的口感劲道、不柴不腻而鲜美多汁，那么在调配肉馅的时候就不要图快、利用搅拌器等道具搅拌，而要在清洁之后直接用双手去抓，使肉料与香油、油等均匀混合，进入所谓“上劲”的状态，而后再混入调味的料酒、酱油等。\n总而言之，四喜丸子在制作时需要制作者下更多心思，把控更多的细节。\n但与之相对的，一道色香味俱全的四喜丸子所蕴含的心意也比一般的菜色更多，给人们带来的快乐与幸福感也更多呢。"
  },
  [88] = {
    order = 88,
    id = 321,
    desc = "辣炒年糕",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 1,
    phyDef = 2,
    hit = 3,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "AKR",
    cv1 = "暂无",
    desc = "辣炒年糕在韩国是一种非常常见的小吃，以其甜辣的口味及鲜红的色泽而深受年轻人的欢迎。比较特别的是，虽然名叫辣炒年糕，但做法中的核心是其实水煮，让年糕饱吸酱料，从而诞生浓郁的口味。\n \n制作辣炒年糕，首先要准备好辣椒酱以及白糖，其他亦可以用火腿肠或洋葱等蔬菜做辅料。先将年糕与热水一起入锅煮开，加入辣椒酱以及白糖，再放少许耗油、盐、鸡精、酱油来调味。待收汁到一半时，放辅料与年糕一起翻炒，让调味料与食材进行充分的接触。最后调小火进行进一步收汁，酱汁收干后就可以起锅了。\n \n出锅后的辣炒年糕，不但色泽亮丽，软糯的年糕与香脆的蔬菜搭配还形成了层次丰富的口感。有白糖和辣椒酱的调味，也使得年糕甜而不腻、并带有让人沉醉的刺激感。\n \n现如今，辣炒年糕在韩国各地已随处可见，在中国、日本等东亚国家的街头也非常流行。辣炒年糕的丰富口感以及极高的营养价值已经使得它毫不逊色于世界各地的著名美食，更令它成为名满天下的“红色系”韩式料理。"
  },
  [89] = {
    order = 89,
    id = 320,
    desc = "拔丝地瓜",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 2,
    hit = 3,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "一朵焼麦",
    cv1 = "暂无",
    desc = "拔丝地瓜，这道菜的名字可能会让一些人感到困惑。它名字中的拔丝不是指藕或山药等食物的粘液拉成的丝，也不是指植物的粗纤维，而是指食糖在高温融化成糖浆后遇冷所凝结成的糖丝。拔丝地瓜的做法非常简单，新鲜的地瓜洗净、切块，然后将其下入热油之中，烹炸至金黄色，随后另起一锅加清水、白糖，用慢火熬制，直至糖浆浓稠变色后，倒入炸好的地瓜、使地瓜均匀地裹上“糖衣”。\n烹制好的拔丝地瓜色泽金黄，芳香浓郁，甜甜的口感深受孩子们喜爱，厨艺高强的厨师甚至会用糖丝塑形、书画，令人更加的爱不释手。拔丝地瓜虽然是一道著名的甜口鲁菜，但相较于它那些出入皇宫的“兄弟姐妹”，它显得更加的亲民，如果手头没有营养价值丰富的地瓜，用红薯、土豆甚至是苹果这类的寻常可见的食材代替完全没有任何问题，在中国，很多母亲都会在闲暇时光为孩子们烹制这到简单又好吃的甜点。\n不过甜食虽好，食用可要注意量与度，特别是拔丝系的食材往往都是含糖量较高的果实、根茎类蔬菜，另外，在食用的时候要记得先把地瓜放到清水中“沾一下”，这样做会让糖丝进一步成型、提升口感，也避免了糖浆粘牙的困扰。"
  },
  [90] = {
    order = 90,
    id = 326,
    desc = "御",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 3,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "春日山城前代守护之妻，侍奉毘沙门天的苦修之人。拥有着年长女性所特有的温柔与稳重，性格恬淡安然，临危不乱，但在危机发生时会表现出超乎常人的果决强硬，能够以一己之力左右大局。她的这份能力与心性自然与常年的苦修有关，透过经年累月的虔诚修法，她参透了自己与因缘者们的宿命——成为“██者”，那正是其职责所在。\n这个曾经在丈夫受围而亡时独自对抗万千妖族的女性正是流浪剑豪晓的生母，原本她应当在某个事故中与当代守护一起被杀死，但现如今却完好无损的出现于春日山城……\n应当被杀死的御，究竟是逃过了一劫，还是幽灵？她又为何会出现在这个世界里？众多的秘密，被隐藏在忽然现身于异界的春日山城之中。作为事件的核心，知晓一切的御正连接着众人的命运。"
  },
  [91] = {
    order = 91,
    id = 322,
    desc = "小龙虾",
    open = 1,
    atkSpeed = 3,
    hp = 3,
    atk = 2,
    phyDef = 3,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "月见",
    cv1 = "暂无",
    desc = "小龙虾，又称口味虾，是一道源自中国湖南的著名小吃。它最为经典的做法是麻辣小龙虾，在其制作伊始，应取小龙虾一盆，去虾线并洗净，接着在锅中放油，待油温三成热时下葱姜蒜煸香，再倒入小龙虾与干红椒、花椒、八角、酱油等调味料一起翻炒。小龙虾的身体卷曲、外壳变红是其肉质成熟的证明，此时淋入一定量的清水，在锅上加盖，中火焖8~10分钟收汁后即可出锅。\n这种学名克氏原螯虾的平民食材以肉质丰满、蛋白质含量高而闻名，食用起来口感也极佳，经过这样一番翻炒，小龙虾的虾肉浸满辣椒的香气，又保留着虾肉的鲜香，让人欲罢不能。即使是不太能吃辣的人也可以选择酱香及蒜蓉来享受这一美味。所以小龙虾一经推广便迅速地占领大江南北，成为人们夏夜消遣的首选之一。\n当然，也有学者称“小龙虾之所以能稳坐社交食物头把交椅，主要是因为吃小龙虾时人们必须用上双手。这就杜绝手机等外界因素带来的干扰，令人专注于面对面交流、实打实的加深感情”。无论真相到底如何，不可否认的一点是，小龙虾确实十分美味，也没有人能够轻易拒绝小龙虾所带来的味觉诱惑。"
  },
  [92] = {
    order = 92,
    id = 323,
    desc = "炸串",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 3,
    hit = 3,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "KW",
    cv1 = "暂无",
    desc = "炸串是一种将海鲜和山货等食材切成一口大小，插在竹签上，撒上面包粉之类的东西作为外皮，最后油炸而成的料理。作为关西的名菜声名远扬，受到全国各地人民的广泛喜爱。虽然炸串（串扬げ）很容易被与炸肉串（串カツ）搞混，但实际上原本也没有明确的区分标准。不过，有一种辨别方法是：食材以肉类为主的便是炸肉串，用鱼贝类、蔬菜、各种各样的食材制成的则叫炸串。在刚炸好的金黄色的炸串上滴上酱汁，一口嚼上松脆的面衣。面衣包裹下的食材多汁的美味便在嘴里瞬间扩散开来，让吃的人赞不绝口。另外还有一种纯粹的吃法，只蘸上一点点酱汁，以便更充分享受食材本身的美味。一次就能享受多种食材的美味，这也是炸串的一种魅力所在。"
  },
  [93] = {
    order = 93,
    id = 325,
    desc = "蛋饼",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 2,
    phyDef = 2,
    hit = 3,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "调羹",
    cv1 = "暂无",
    desc = "蛋饼，通常来说指的是台式蛋饼，这道料理料理乍一看颇有中式煎饼或美式卷饼（Burrito）的韵味，但却有着与二者截然不同的特色口感——它的独特之处在于，作为蛋饼主要食材的蛋液既不是被“摊”在面饼上的，也不是被炒熟后卷进面饼里的，而是被直接浇入刚刚定型的面糊，与面饼完美融合在一起的。这就要求面糊要调制的较稀、面饼则必须摊得够薄。\n如此做出来的蛋饼，厚厚的蛋液与柔韧的面饼平分秋色，使得它外侧焦脆、中央温润，爽滑弹牙的口感配上火腿、起司、培根或肉松的香味，再辅以番茄酱等酱料的浓厚味道，着实是对味觉的全方位冲击，让人欲罢不能。无外乎有人说蛋饼之于台湾就如同热干面之于武汉或担担面之于四川，这种简洁但却直击人们欲望的料理着实是味觉享受的最佳代名词。"
  },
  [94] = {
    order = 94,
    id = 327,
    desc = "琉璃",
    open = 1,
    atkSpeed = 3,
    hp = 3,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "未定",
    cv1 = "茅野爱衣",
    desc = "琉璃出生一个音乐氛围浓厚的家庭，父母均毕业于音乐院校，但两人擅长的乐器却与各自的性格一般不搭调，自小，她就在架子鼓和小提琴无法融合的音乐中长大。 琉璃自小就展现出绝佳的音乐天赋，无论是摇滚、流行、古典等不同种类的音乐，她都可以驾驭，也顺理成章地就读某座音乐院校。 一切的改变源于Ai“觉醒”的那天，琉璃所在的学院同样遭到了破坏，自己也不幸被埋入废墟中。在等待救援的漫长时间中，少女经历了深刻的绝望。 不过少女并没有因此崩溃，在获得拯救后，琉璃暗下决心。她想要成为能够为他人带去光明的人，用自己的音乐驱散绝望。"
  },
  [95] = {
    order = 95,
    id = 328,
    desc = "鲲",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 3,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "玛雅G",
    cv1 = "伊藤加奈惠",
    desc = "摸鱼一时爽，一直摸鱼一直爽。只要在死线前能够完成就是perfect，不能在死线前完成的话就萌混过关！\n摸鱼——是一种可以保持身体放松和精神紧张的优良习惯。可以在紧要关头激发灵感和创作力，既能高效完成任务又能在预计的时间中享受休息的快乐，可以给人带来极大的心理满足！\n入我摸鱼神教啦！"
  },
  [96] = {
    order = 96,
    id = 324,
    desc = "炸鸡块",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 3,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "干炸是在各种食材上撒上淀粉或面粉之后用油炸油炸出来的料理。一般来说，很多人会联想到炸鸡块。\n油炸食品的起源可以追溯到江户时代，当时不是用鸡肉，而是炸鱼之类的料理。现在的炸鸡是在这几十年里诞生的，历史还很短。\n咬上一口炸得酥脆、香喷喷的鸡肉，里面多汁、肉汁溢出来的嫩鸡肉的美味溢满口腔。\n一般家庭的菜式和饮食店也经常使用炸豆腐，不论在大人还是小孩中，炸鸡块都很受欢迎。\n另外，几个人围着盘子的时候，不要不小心洒上柠檬汁。要说为什么的话，因为有可能会引发加柠檬派和不加柠檬派的争论。"
  },
  [97] = {
