    painter = "千良",
    cv1 = "貔貅肛",
    desc = "缤纷星缤纷家族的大小姐，落樱是生命之神达拉嘣塔守护的仙女，拥有可爱到犯规的脸，一激动大大的眼睛就会闪亮闪亮的；小落樱怀着一颗珍爱生命的善良之心，有时候会因为自身的暴击能力感到困惑。\n因为落樱待人亲切，无论面对什么情况，她总是会笑容满面，像个温柔的大姐姐，能敏锐的感觉到一切生物的情感，有着安定人心的能力，经常会帮小伙伴开导情绪；在缤纷星有着极高的人气。\nR实验的爆发后，整个星系陷入一片灰暗中，生命之神塔塔也因为保护她和星球被病毒污染个彻底，看着塔塔与混乱的星球，落樱满心的内疚，明明她的使命才是保护缤纷星。\n缤纷家族为了保护落樱，准备将她送往更加安全的地带，落樱为此与家族产生分歧，尽管她已经很努力的帮忙净化星球，但是个人能力总是有限，她意识到缤纷组能给她提供一个拯救更多人的机会。\n缤纷组的可靠情报显示[XR]提纯剂似乎可以对病毒起到一定的抵制作用，一切线索指向皇家学院，落樱决定只身前往学院。在学院结识妖炽，并在后来成为交心好友。\n落樱带着提纯剂回到缤纷星，病毒情况终于得到初步控制…\n怀着对这个星球的关心而离开，之后又再度回来的少女终于走在了实现她“保护这个星系”这个理想的路上。虽然仍然不知道前路会走向何方，这份灰暗何时能够终结。但是至少她如今已经有了很大的成长，也有了可以共同努力的伙伴。随着时间的流逝，想来生命复苏的未来终会到来"
  },
  [98] = {
    order = 98,
    id = 331,
    desc = "水晶虾饺",
    open = 1,
    atkSpeed = 3,
    hp = 3,
    atk = 1,
    phyDef = 3,
    hit = 2,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "水晶虾饺是粤式茶楼的传统名点，它最早出现在广州郊外靠近河涌集市的茶居。那些地方盛产鱼虾，茶居师傅再配上猪肉、竹笋，制成肉馅。当时虾饺的外皮选用粘(大)米粉，皮质较厚，但由于鲜虾味美，很快流传开来。城内的茶居将虾饺引进，经过改良，慢慢成为广州茶楼的名点，历久不衰。\n在粤式的茶楼中，虾饺的质量可是判断这家店厉不厉害的重要标准。真正优秀的虾饺讲究皮白如雪，薄如纸，半透明，半月形，蜘蛛肚，内馅隐约可见，吃起来爽滑清鲜，美味诱人。每当掀开笼屉，几只白里透红的虾饺仿佛少女精致的肌肤一样，弹滑可爱，惹人怜惜。\n现在的茶楼上，虾饺的馅料已经做了不同的创新。有的会加入鸡肉粒，也有的会放蟹籽。无论如何，这道经典料理几乎都是广式早茶必点的一道明星茶点，配上沏好的热茶，慢慢的品去，一上午便悄然过去——这可是奢侈无比的安逸呀。"
  },
  [99] = {
    order = 99,
    id = 332,
    desc = "落樱lost",
    open = 1,
    atkSpeed = 3,
