    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良",
    cv1 = "貔貅肛",
    desc = "缤纷星缤纷家族的大小姐，落樱是生命之神达拉嘣塔守护的仙女，拥有可爱到犯规的脸，一激动大大的眼睛就会闪亮闪亮的；小落樱怀着一颗珍爱生命的善良之心，有时候会因为自身的暴击能力感到困惑。\n因为落樱待人亲切，无论面对什么情况，她总是会笑容满面，像个温柔的大姐姐，能敏锐的感觉到一切生物的情感，有着安定人心的能力，经常会帮小伙伴开导情绪；在缤纷星有着极高的人气。\nR实验的爆发后，整个星系陷入一片灰暗中，生命之神塔塔也因为保护她和星球被病毒污染个彻底，看着塔塔与混乱的星球，落樱满心的内疚，明明她的使命才是保护缤纷星。\n缤纷家族为了保护落樱，准备将她送往更加安全的地带，落樱为此与家族产生分歧，尽管她已经很努力的帮忙净化星球，但是个人能力总是有限，她意识到缤纷组能给她提供一个拯救更多人的机会。\n缤纷组的可靠情报显示[XR]提纯剂似乎可以对病毒起到一定的抵制作用，一切线索指向皇家学院，落樱决定只身前往学院。在学院结识妖炽，并在后来成为交心好友。\n落樱带着提纯剂回到缤纷星，病毒情况终于得到初步控制…\n怀着对这个星球的关心而离开，之后又再度回来的少女终于走在了实现她“保护这个星系”这个理想的路上。虽然仍然不知道前路会走向何方，这份灰暗何时能够终结。但是至少她如今已经有了很大的成长，也有了可以共同努力的伙伴。随着时间的流逝，想来生命复苏的未来终会到来"
  },
  [100] = {
    order = 100,
    id = 333,
    desc = "林美",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 1,
    phyDef = 3,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "林美，来自远方的神秘少女，有绿蛇和老龟为伴。她的笑容是如此纯真、温柔，与她交谈，总能忘却烦忧。但，主厨也发现她与外表不同的一面。主厨不是第一次见到林美的小腿和裙摆一同摇摆着，她笑着请求——如果她不是坐在高高的城墙上，拿着竹棍的话。“主厨大人，我给你打下栗子？你给我做栗子糕吃吧？”见到主厨惊讶的表情，她的笑容和更加灿烂，栗子随着竹棍的敲打噼里啪啦落下。“……我以前就是这样的哦？我可是是圣愿寺的孩子王呢！”那一定是过去的、不用被责任束缚的、无忧无虑的岁月，能看到这样的林美，谁说这不是一件好事呢？"
  },
  [101] = {
    order = 101,
    id = 334,
    desc = "法式鹅肝",
    open = 1,
    atkSpeed = 3,
    hp = 2,
    atk = 4,
    phyDef = 3,
    hit = 3,
    miss = 5,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "忍忍包子",
    cv1 = "暂无",
    desc = "鹅肝是法国的传统名菜，法语称为“FoieGras”，是用鸭科动物鹅的肝脏为主材制作而成，其中，“Gras”有顶级的意思，鹅肝在法国菜中的地位可见一般。这道名菜将法国菜的浪漫推到了极至。鹅肝一般重达600到900克，不过有些来自Toulouse和Strasbourg地区的鹅，肝据说有2公斤重！用来作鹅肝的鹅并不多，而且体型要够大才能制造出足够重的鹅肝。除了重量外，鹅肝的颜色也很重要，受伤或有损坏的鹅肝是不被采用的，只有纯鹅或鸭肝才能被当作是“Foie Gras”出售。料理鹅肝是一种从被过份喂饲的鹅取出来的肝。欧洲人将鹅肝与鱼子酱、松露并列为“世界三大珍馐”。法式鹅肝的主要材料有鹅肝、黑菌、松茸菌、红蒜、奶油、黄油、盐、糖、胡椒等，采用烤的烹饪工艺，味道鲜香。"
  },
  [102] = {
    order = 102,
    id = 329,
    desc = "可乐饼",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 2,
    phyDef = 2,
    hit = 3,
    miss = 6,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "日本街道上最流行几大明星小吃，除了章鱼丸子之外，就数可乐饼最受欢迎了。不过虽然同样是女孩子们喜欢捧在手心里边走边吃的食物，可乐饼却有一个很不同的地方——它并不是日本的传统食物。\n可乐饼虽然有这个听起来甜甜的名字，但它的配方里却一滴可乐都没有。据说，它是从法兰西传入日本，在日本兴旺发达起来。 它的名字取自法语中的“croquette”，日语为コロッケ（korokke)，所以最终才会被音译成“可乐饼”。\n它原本的做法，是在奶油和面粉制成的酱中，加入碎菜和肉（用马铃薯泥亦可），冷却后捏成圆柱形，再抹上小麦粉、蛋汁以及面包粉，然后用油炸后出锅。但是日本的家庭却把这种小食经过改良，变成更加简约的口味，改用马铃薯泥，加入炒好的洋葱和肉末，然后捏成圆柱状煎炸。所以可乐饼真正的名字，应该是“日式炸丸子”或是“日式炸肉饼”才对，不过可乐饼听起来又精简又有食欲，当然更容易被大家接受啦。"
  },
  [103] = {
    order = 103,
    id = 335,
    desc = "康沃尔馅饼",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 2,
    phyDef = 2,
    hit = 3,
    miss = 6,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "纳豆Nash",
    cv1 = "暂无",
    desc = "康沃尔馅饼是一道来自英格兰西南部康沃尔郡的传统菜肴。它是一种咸点心，里面填有肉、蔬菜和调味料，然后烤成金黄色。点心本身由面粉、水和黄油制成，滚成薄而椭圆的形状。康沃尔馅饼的起源可以追溯到13世纪，当时它首次在康沃尔郡的一份文件中被提及。当时，馅饼类的食物主要被工人阶层消费，因为它是一种方便和便携的食物，可以轻松带到工作地并用手吃。\n传统的康沃尔馅饼馅料包括切碎的牛肉、土豆、洋葱和萝卜，但现在也有许多变化。一些常见的变化包括添加其他蔬菜，如胡萝卜、豌豆和带皮萝卜，或使用其他类型的肉，如羊肉或猪肉。\n现今，康沃尔馅饼已经成为康沃尔郡的受欢迎的和珍视的菜肴，现在在世界各地都有人喜欢。2011年，它获得了欧盟保护地理标志认证，这意味着只有在康沃尔郡使用传统方法制作的馅饼才能被称为“康沃尔馅饼”。"
  },
  [104] = {
    order = 104,
    id = 336,
    desc = "板蓝根泡面",
    open = 1,
    atkSpeed = 2,
    hp = 5,
    atk = 2,
    phyDef = 2,
    hit = 3,
    miss = 6,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "暂无",
    desc = "板蓝根泡面是一种源自中国古代饮食文化的快速食品。它是一种即食面，由面条、调料包和脱水蔬菜组成，只需用鸡蛋液冲泡几分钟即可食用。面条经过压制和干燥处理，呈现出金黄色的色泽和粗糙的口感。板蓝根泡面的起源可以追溯到20世纪末，当时它首次在先秦时期的一份食品报告中被提及。当时，这种方便食品主要被用于弥补疾病，因为它是一种快速、苦涩的食品，那么很适合当做宠物粮食。\n传统的板蓝根泡面调料包包括蚝油、花露水和脱水生鱼片（如葱花、折耳根等），但现在也有许多变化。一些常见的变化包括添加其他口味的调料，如香油味、脂肪味或可乐味，或在面条中加入其他配料，如新鲜蔬菜等。\n如今，板蓝根泡面已经成为各国现代饮食文化中不可或缺的一部分，不仅在国内广受欢迎，在阿德利企鹅族群中常常脱销。2023年，它获得了木卫二地理标志产品认证，这意味着只有符合特定标准和传统工艺制作的泡面才能被称为“正宗板蓝根泡面”。"
  },
  [105] = {
    order = 105,
    id = 403,
    desc = "九层糕",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 2,
    formation = 4,
    painter = "TN千夏",
    cv1 = "暂无",
    desc = "拥有独特纹理的中国南方糕点。\n又名九重糕，千层糕，中元糕等。\n由米，白糖等原料蒸制而成。\n相传九层糕起源于宋末年间，至今约600多年的历史\n九层糕这种料理带有一定的宗教色彩，在南方常被用在喜庆或祭祀节日时食用。尤其在除夕，清明，中元，重阳中国传日祭祖四大节中，经常能看到九层糕的身影。\n九层糕根据工法和用料的不同，颜色和层数也会不一样。因此九层糕不一定有九层。\n随着华人移居到海外，九层糕也被传到一些东南亚国家，发展出如“印度尼西亚九层糕”之类的版本。"
  },
  [106] = {
    order = 106,
    id = 405,
    desc = "冰糖葫芦",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 1,
    formation = 1,
    painter = "谷梁顿Grain",
    cv1 = "铃木亜理沙",
    desc = "中国京津地区的传统小吃。\n最常见的冰糖葫芦是用涂上麦芽糖的山楂串成。但有时也会使用其他水果。虽然叫做“冰糖葫芦”但是并没有使用冰糖。\n冰糖葫芦的起源有几种说法，较常见的说法是起源于南宋绍熙年间。\n冰糖葫芦的“冰”是指其在冬天贩卖时，冰凉而有硬度的口感。因为冰糖葫芦外层糖衣会融化和过去小贩露天贩卖的方式，过去冰糖葫芦并不适合在夏天贩卖，但是现在因为冷藏技术的进步，冰糖葫芦变得一年四季都很常见了。\n冰糖葫芦陪伴了许多中国小孩的成长，即使现在也深受小孩子的喜爱。叫卖冰糖葫芦的吆喝声，也早已成为了京津地区的民俗风情 ，即使在流行快速变化的现代，作为历史悠久的小吃，冰糖葫芦还能维持高人气并且每年产量都有增长，其魅力可见一斑。"
  },
  [107] = {
    order = 107,
    id = 412,
    desc = "爆米花",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 4,
    miss = 1,
    growth = 2,
    skill = 2,
    formation = 5,
    painter = "kkkkkkey",
    cv1 = "内田彩",
    desc = "爆米花是一种历史悠久的膨化食品，也是现代各种数不清的膨化零食小吃的祖先。\n据历史考察，古代印第安人5000年前便开始食用爆玉米花了。哥伦布发现新大陆后，回到欧洲也向人们描绘了新大陆上，印第安儿童用爆玉米花串成项链在街上兜售的情景。印第安人教会了前往新大陆的欧洲移民如何栽种玉米、如何烘烤玉米，自此，爆米花渐渐风靡欧洲。\n中国宋朝也有食用爆米花的风俗，但与印第安人不同，宋人采用的是稻谷。在诗人范成大的《石湖集》中，记录着上元节时吴中各地的“孛娄”风俗：“上元，爆糯谷于釜中，名孛娄，亦曰米花。每人自爆，以卜一年之休咎”。“孛娄”就是宋时爆米花的名字，模拟爆谷时的响声。在新春来临之际，宋朝人用爆米花来占卜一年的吉凶，姑娘们也用爆米花来占卜自己的终身大事，将这个小吃赋予了更加丰富的文化内涵。\n进入现代之后，爆米花一般就通指爆玉米花了。现代的爆米花有上百种口味，因其松脆的口感与丰富的种类而深受大众喜爱，不管是看电影、聚会、饮酒还是休闲，大家都喜欢来上一袋爆米花佐食。"
  },
  [108] = {
    order = 108,
    id = 414,
    desc = "砵仔糕",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 2,
    formation = 2,
    painter = "电风扇",
    cv1 = "岛袋美由利",
    desc = "香港的街头传统小吃，不少香港人怀念的味道。\n \n传统的钵仔糕以黄糖、粘米粉等造成后，放在一个瓦制的小砵内蒸熟。\n \n钵仔糕起源地广东台山，诞生时间不详，传统的钵仔糕口味比较少。在8、90年代的香港大量流行。\n \n因在香港的流行，钵仔糕也得到了发展，钵仔糕的可塑性很强，无论是“糕”还是“料”都可以进行DIY，做成各种不同颜色和风味，其中不乏年轻人喜欢的水果、巧合力等口味。同时，钵仔糕也可以放入不同形状的砵，定型出不同形状的外形。\n现在钵仔糕款式的多样性，已经是钵仔糕最大的卖点之一。\n \n虽然没有8、90年代那么具有代表性，但是钵仔糕毫无疑问的是香港小吃的代表之一，各种新款的钵仔糕正在散发着全新的活力。"
  },
  [109] = {
    order = 109,
