    skill = 3,
    formation = 1,
    painter = "stoner08",
    cv1 = "青柳るう",
    desc = "被带上皇冠的蛋糕。\n帝王蛋糕主要是在拉丁语系国家中，“主显节”期间食用的蛋糕。\n在不同国家使用的材料和外观会有微妙的不同。\n一般做法是将预先做好的杏仁膏螺旋状叠成两层，再将派的面皮包裹烘烤而成。\n帝王蛋糕带有的宗教色彩，让她在天主教以外的国家知名度并不高。\n但由于“王的蛋糕”这包含特殊意义的名字，让不少人对她产生了好奇。\n传说吃到帝王蛋糕中藏有被称作fève的小陶偶，就能获得一整年的祝福哦。"
  },
  [110] = {
    order = 110,
    id = 404,
    desc = "焦糖布丁",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 5,
    painter = "ovos",
    cv1 = "みゅう",
    desc = "布丁的代表之一。\n布丁的历史悠久，五世纪前在英国诞生的布丁并不是甜品，而更加像是作为主食的蒸糕。直到19世纪，法国的糕点师将布丁改良成甜品，才变成了我们现在所喜爱的布丁。原来的大众食品也因此一下子变成上流社会所喜爱的下午茶甜点。\n黑糖布丁因为其非常具有特点的“黑糖层”，被大众所记忆。\n人们一旦说起布丁，脑海中浮现的第一印象，经常就是这种带有黑糖层的布丁。\n布丁种类繁多，并不是所有的布丁都适合浇上黑糖食用。使用较多的如鸡蛋布丁，牛奶布丁等居多。\n因为现代的食品加工技术的进步，本来只有在糕点店才能品尝到的布丁，现在一般超商都可以买到。\n也算是布丁从平民到贵族再回归平民的过程。"
  },
  [111] = {
    order = 111,
    id = 411,
    desc = "沙琪玛",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 3,
    painter = "西域",
    cv1 = "暂无",
    desc = "沙琪玛，也写作萨其马，是一种由面条油炸，混合蜂蜜、奶油而成的甜品。\n“沙琪玛”是由满语的“切”和“码”组成的音译词。在《燕京岁时记》有记载：“萨其马乃满洲饽饽，以冰糖、奶油和白面为之，形如糯米，用不灰木烘炉烤进，遂成方块，甜腻可食。”\n作为满族的传统甜品，原本沙琪玛是清代关外三陵祭祀的祭品之一，后来在各地八旗驻军的推动下，得以流行全国。\n经过不断改良，如今沙琪玛的做法变得非常亲民：鸡蛋加入面粉，制成面条下锅油炸。再由白糖、蜂蜜、奶油制成糖浆后与之混合。待干、切块即可。也可以加入坚果或果干，能够大幅降低甜腻，提升口感。\n沙琪玛能够流行开，关键在于味道甜美、价格实惠，在食物紧缺的年代，其丰富的热量也能让众多平民得到满足，是中式传统糕点中名副其实的翘楚。"
  },
  [112] = {
    order = 112,
    id = 413,
    desc = "华夫饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 4,
    miss = 1,
    growth = 3,
    skill = 5,
    formation = 1,
    painter = "6音",
    cv1 = "佐藤亚美菜",
    desc = "华夫饼，又叫格仔饼、压花蛋饼、窝夫，是一种用专门烤盘烤制的点心，起源于比利时。\n而作为一款甜品，华夫饼最让人印象深刻的莫过于它身上格子一样的图案了。这是因为华夫饼烤盘上下两面一凹一凸，一般呈方形或菱形，用来保证烤制时受热均匀。这种格子也被称为华夫格，如今作为一种经典图案，经常被用于各类纺织品中。\n现在比较常见的做法是，用面粉、黄油、鸡蛋、牛奶、砂糖、泡打粉调制成面糊，再在烤盘内壁抹上一层黄油，预热后将面糊倒入，小火慢烤至表面金黄完成。\n食用时，通常在华夫饼上浇上枫糖浆，或者酸奶、冰淇淋，也可以搭配自己喜欢的水果，甚至是炸鸡，所以是万能百搭的料理哦。"
  },
  [113] = {
    order = 113,
    id = 406,
    desc = "可丽饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 3,
    painter = "真名",
    cv1 = "铃木亜理沙",
    desc = "可丽饼是一种发源于法国布列塔尼省的料理。\n将小麦粉（或荞麦粉）、鸡蛋、牛乳、奶油等混合成浆，再用平底锅煎制两面而成。\n可丽饼是热香饼的近亲，在发源地法国，会把烧的较薄的热香饼称作可丽饼。\n可丽饼并不一定作为甜点，可丽饼除了包裹水果、奶油等馅料作为甜品食用，原本还有包裹各种坚果、蔬菜、火腿等食物作为主食来食用的形式。\n可丽饼通过法国的殖民地，印度尼西亚等地方传入亚洲，而我们常见的卷筒状的可丽饼，其实是1977年，日本原宿的一家可丽饼店所创，现在非常常见的在可丽饼中放入水果等类似甜品的形式，也是从日本诞生的。\n虽然这种纸卷的可丽饼一开始并没有受到注目，但后来因为杂志等媒体的报道而开始流行，成为了亚洲最流行的可丽饼的形态。\n在现代已经发展出可丽饼的自动贩卖机，让人可以随时随地品尝到美味的可丽饼。\n2月2日被法国定为传统的“可丽饼日”，是食灵——可丽饼的生日哦~"
  },
  [114] = {
    order = 114,
    id = 407,
    desc = "马卡龙",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 5,
    painter = "蘑格里",
    cv1 = "暂无",
    desc = "“马卡龙重量只有几克，但是却足以让你满足得颤抖。它们很薄，脆壳、圆圆的形状、诱人的颜色和湿软的馅料让爱好者们先饱眼福，你可以用手指感觉它们光滑的表面，它们的香气满足了鼻子，当你咬到松脆的外壳，耳朵会听到悦耳的声音，这一切之后，才是味觉的满足。”——来自法国的甜点主厨，被称为甜点界毕加索的 Pierre Herme 如此形容马卡龙。\n关于马卡龙的起源，说法各异。其中相对认可广泛的传说是，马卡龙起源于中世纪的意大利，在 16 世纪中叶，由法国商人们带回故乡。初到法国的马卡龙与现在流行的造型相去甚远，是一种单片没有夹心、由蛋白和杏仁粉制作的小圆饼。由于受到法国皇室的青睐，当地的主厨们开始竞相制作这种甜点，在口感与造型上发挥极致的想象力，用果酱、巧克力、咖啡等来创造五彩缤纷的颜色，让马卡龙逐渐演变成了如今的样式——色彩斑斓，外形圆润，层次分明，馅料分量十足，形成明显的裙边。\n马卡龙精致的外形，让几百年后的它与贵族仍保持着紧密的联系，是极尽高雅与奢侈的甜品。这一特性也是让马卡龙在时尚界备受欢迎的原因，许多知名服装、化妆品甚至是珠宝品牌都有过与马卡龙合作的记录，造成了马卡龙在世界范围内的流行。2007 年，麦当劳在法国推出马卡龙，标志着马卡龙正式冲破阶级，走向了大众化。\n尽管各个档次的马卡龙差异巨大，但如今成为潮流的马卡龙，取得人们欢心的早已不仅仅是口味。小巧缤纷的外形，浓缩了上百年的法国甜点文化，加之与时尚概念的高度重合，使马卡龙在任何地方都不会被人们拒绝。"
  },
  [115] = {
    order = 115,
    id = 408,
    desc = "提拉米苏",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 3,
    painter = "Bison仓鼠",
    cv1 = "三宅晴佳",
    desc = "提拉米苏(Tiramisu)是一种带咖啡酒味儿的意大利甜点。\n以马斯卡彭芝士作为主要材料，再以手指饼干取代传统甜点的海绵蛋糕，加入咖啡、可可粉等其他元素。吃到嘴里香、滑、甜、腻、柔和中带有质感的变化，味道并不是一味的甜。\n提拉米苏的起源可以追溯到17世纪的一种叫做Zuppa del Duca 或称作Zuppa Inglese的意大利西北方甜品，但真正的提拉米苏则是二十世纪60年代在意大利威尼斯的西北方一带开始出现。当地人采用Mascarpone cheese(马斯卡彭芝士)作为主要材料，再以手指饼干取代传统甜点的海绵蛋糕，加入咖啡、可可粉等其他元素。\n在意大利文里提拉米苏(Tiramisu)的意思是“带我走，拉我起来”意指吃了此等美味，就会幸福得飘飘然、宛如登上仙境。"
  },
  [116] = {
    order = 116,
    id = 409,
    desc = "荣耀女仆蛋挞",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "花洒",
    cv1 = "雨宫天",
    desc = "英国传统且尊贵的甜点。\n用面饼皮涂上牛油浆，包裹芝士凝乳，烘烤而成。有时也会加入肉荳蔲和扁桃。\n蛋挞是一种以蛋浆做成馅料的西式馅饼。\n它起源于欧洲，在中世纪英国人就会用奶制品、糖、蛋以及其他配料，制作类似蛋挞的食品。因为做法简单，所以在传播的过程中世界各地都有不同的品种改良和本土化，形成了多姿多彩的口感和风格。\n荣耀女仆蛋挞是英式蛋挞的一种，其诞生可以追溯到亨利8世的时代。传说国王看到皇宫里的女仆们在吃甜点，于是就要求让自己也试吃一下，结果发现极其美味于是就将这种甜点命名为“荣耀女仆蛋挞”。\n如果故事到这里就结束，那么这将是个美好的故事。但是另有传说，做出这种蛋挞的女仆，被国王囚禁，并且不得不一直为国王做甜点。\n在英国的萨里州，有一家从18世纪就开始营业的茶店，以号称“元祖荣耀女仆蛋挞”闻名，是现代，能体验到的最正宗的“荣耀女仆蛋挞”的地方。"
  },
  [117] = {
    order = 117,
    id = 417,
    desc = "龟苓膏",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 3,
    painter = "青年君",
    cv1 = "暂无",
    desc = "龟苓膏，一种外貌类似于果冻的中华养生料理。它的原型被认为是与其制作方法相类似的另一种养生料理“仙人冻”——据传，中国广东一带气候湿热多瘴气，人们常采集一种被称作是凉粉草的药材煎汁、将其与米浆混合煮制，再经过冷却处理即会成为黑色的胶状物，此时加糖搅拌食用劲道爽口，既可以解除体热，又能够祛除心热，是消夏的绝佳选择。而龟苓膏正是在此制法的基础之上加入来自宫廷的药膳配方，增加龟肉、地黄、茯苓等珍贵药材，从而使得这道“冻”的调理、解毒、养生效果更上一层楼，成为达官贵人也喜闻乐见的珍馐良品。\n值得一提的是，凉粉草又被称作是“神仙草”，而龟苓膏的另一大原材料乌龟在中国被视作是长寿的象征，这二者使得龟苓膏在追求长寿的人眼中有着别样的魅力，是一道有着美好内涵的“长寿菜”。当然了，随着中国医药科学的发展，过去配方中愚昧、无效、有害的成分被逐渐剔除，一些原始的、通过野蛮方法获取的药材也获得了替代品，现如今的龟苓膏当中已很少使用乌龟等药材了，龟苓膏的延年益寿神话也被逐渐打破。但这并不意味着这道“中药果冻”失去了它的价值，而且恰恰相反，它因为展现着人们的实践与才思，已深深扎根于人们心中，以至于在过去短暂兴起过一场短短的“龟苓膏热”。"
  },
  [118] = {
    order = 118,
    id = 425,
    desc = "苹果派",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 1,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "咩君",
    cv1 = "暂无",
    desc = "所谓苹果派就是把用砂糖煮熟的苹果塞进派皮里，然后用烤箱烤出来的点心。\n总的来说，苹果派根据国家和地区的不同，也有各种各样的做法和形状，在日本，长方形和圆形的苹果派广泛流通。\n在美国常见的是圆形的，在英国则不在底部铺面团，只在放入深盘子里的苹果上铺上面皮。\n法国的馅饼和英国的正好相反，只在底部铺上面团，奥地利则是把苹果用派皮像瑞士卷一样卷起来。\n虽然用普通的苹果也能做出苹果派，但假如是耗尽心思做出来的，还是想用为那种为制作苹果派而改良过的苹果吧。\n在日本，被称为“红玉”的品种作为用于苹果派的苹果很受欢迎。比普通苹果拥有更强烈的酸味，即使在砂糖的煮制下也能充分保留苹果的风味，让人们在甜味中享受清爽的味道吧。"
  },
  [119] = {
    order = 119,
    id = 402,
    desc = "甜甜圈",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "TID",
    cv1 = "佐仓绫音",
    desc = "甜甜圈是一种非常流行的糕点，尤其在美国非常盛行。\n甜甜圈的制作方法是将制作好的生面团油炸而成，然后可以根据个人喜欢涂上巧克力酱等。\n与新潮的外观不同，历史意外地悠久。\n在17世纪的荷兰，荷兰人发明了一种叫做“Olykoek”的甜品，虽然这种甜品并不像现代的甜甜圈一样中间开洞，但普遍认为她就是甜甜圈的原型。\n1607-1620年，在英国受到迫害的清教徒逃亡到了荷兰，学会了这种甜点的制作方法，并把这种甜点传播到了殖民地。\n虽然一般来说甜甜圈主要都作为糕点零食。但是在美国则经常被用来当作早餐。例如在咖啡馆里，咖啡+甜甜圈这样的组合就非常常见。"
  },
  [120] = {
    order = 120,
    id = 410,
    desc = "龙须糖",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 4,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "—PHI—",
    cv1 = "小仓唯",
    desc = "龙须糖原名银丝糖，是有一定历史的中国传统小吃。\n龙须糖的原料一般为麦芽糖，传统馅料包括：砂糖、花生、芝麻、椰丝等。制作时，先将麦芽糖放在容器中，隔水加热。等到麦芽糖化开变软后取出，放在案子上反复揉搓，并裹上糯米粉。之后将糖扭成 8 字型，不停重合、重复，直至呈拉丝状。最后将馅料也裹上糯米粉，包入糖丝内完成。\n相传在两千多年前，中国古代的帝皇在民间游历时，发现了这种外形如丝、味道甜美的点心，当时还叫做“银丝糖”。因为其口感十分特别，便下旨带回宫中，并改名“龙须糖”。在宫中，御厨会以其精巧手艺，于御花园表演整套造糖的过程，供皇室贵族及席享用。\n那以后再传入民间的龙须糖，一直是深受臣民们喜爱的食品。"
  },
  [121] = {
    order = 121,
    id = 415,
    desc = "香菜戚风蛋糕",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 3,
    painter = "mia",
    cv1 = "花泽香菜",
    desc = "香菜迷们不能错过的戚风蛋糕。\n将榨好的香菜泥混入面粉、蛋黄、植物油，按照制作戚风蛋糕的方法，倒膜烘烤而成。\n\n香菜的原产地是地中海东部，文字记录表示，香菜至少在公元前1500年前就已经被食用。虽然在亚洲香菜也是很普遍的食材，但是，香菜真正传播到东亚地区是在张骞出使西域之后。\n香菜除了叶子外，根部茎部果实都可以食用，其中果实是咖喱不可或缺的其中一种香料。\n除食用外香菜还有药用效果，香菜除了富含维生素B1、B2、C、E、胡萝卜素β等营养素外，还被认为有排毒效果。\n\n戚风蛋糕是一种海绵蛋糕，从发明至今，约有100年的历史，发明者是于1927年由美国加州一个兼营小型蛋糕店的保险经纪哈里·贝克。但当时戚风蛋糕的菜谱并没有被公开，直到1948年，哈里·贝克因年事已高，才将戚风蛋糕的制造法卖给了美国通用磨坊公司并公开，戚风蛋糕才爆发性的流行开来。\n戚风蛋糕的最大特点，是用植物油来代替一般蛋糕常用的牛油，使蛋糕质地变得更湿润，饱和脂肪的含量也更少。\n\n现代因为物流的发达，东西方食材和技法互相流通，从而诞生出了更多不同组合的料理，香菜戚风蛋糕就是一种另类的组合，即使不习惯吃香菜的朋友品尝到这款蛋糕，也会有意外的惊喜。香菜迷们更加是不可错过~"
  },
  [122] = {
    order = 122,
    id = 416,
    desc = "月饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "月见",
    cv1 = "朝日奈丸佳",
    desc = "月饼是中国最为知名的传统糕点之一。\n在中国古代，月饼是用以祭拜月神的供品，在宫廷内十分流行，民间则称它为“小饼”或者“月团”，寓意团圆美好。不过那时的月饼多半没有特色，人们对月饼的做法进行讲究，是从明代开始的。明代由于小说、戏曲等俗文学昌盛，各类文化传说也影响了人们的饮食。明代的饼师巧妙地将嫦娥奔月的神话故事作为艺术图案印在月饼上，使月饼更加地得到了人民青睐。到了清代，中秋吃月饼已成为一种普遍的风俗，且制作技巧越发高明。在清人袁枚的《随园食单》中有云：“酥皮月饼，以松仁、核桃仁、瓜子仁和冰糖、猪油做馅，食之不觉甜而香松柔腻，迥异寻常。”\n因为历史悠久，地域文化差异使得月饼的做法形成了多种不同流派。著名的有京式月饼、苏式月饼、广式月饼、以及潮式月饼等。不同派别的月饼，除了馅料不同，饼皮、调料等都有巨大差异。除此之外，现代人对美食与时俱进的追求，也催生出了新型、别具风格的月饼，比如冰皮月饼、海味月饼、冰淇淋月饼等。\n不过，虽然形式如此灵活，但总是在月圆之日才能够登场的月饼，身上承载的祝福早已成为了一种民族文化，是难得的、活跃在各个时代舞台上的传统点心。"
  },
  [123] = {
    order = 123,
    id = 418,
    desc = "面包诱惑",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 4,
    formation = 5,
    painter = "阿宇",
    cv1 = "暂无",
    desc = "面包诱惑，也叫“厚多士”，是将一颗冰淇淋球放在烤过的面包上完成的料理。起初发源于法国，传到香港后经过改良，如今已成为港式下午茶中的一道招牌甜点。\n具体做法是：把吐司中间掏空，并将掏出部分切成魔方一样的二十七枚方块。再在吐司壳内壁涂上蜂蜜，底部铺一层芝士。然后将之前切好的吐司方块，每一枚都蘸好蜂蜜，依次码进吐司壳中。填满后在顶部再撒上一层芝士，放入烤箱烤制三十分钟。最后在烤好的吐司上放一枚冰淇淋球就完成了。\n烤制后的面包口味醇厚，味道香浓。与冰淇淋搭配时，焦香酥脆与绵软的奶香交融在一起，能带给人十分满足的甜蜜体验。因此，面包诱惑也是无数港式茶餐厅顾客们必点的菜品之一。"
  },
  [124] = {
    order = 124,
    id = 419,
    desc = "鲷鱼烧",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "RONOPU",
    cv1 = "暂无",
    desc = "鲷鱼烧、一种著名的日本甜食，在制作方法上和所谓的“今川烧”很相似——以面粉、蛋、糖等材料为主制成外皮，再加入红豆等馅料后放入模具中进行烤制，而鲷鱼烧这边的特别之处主要在于它的模具是鱼形的，烤制完成后的鲷鱼烧色泽艳丽，就像是一条可爱的小鱼一样。\n有关于鲷鱼烧的起源、传说记载是相对较少的，甚至已经到了不可考证的地步，但是无论大人还是小孩子都非常热爱鲷鱼烧、将其视为是一种带来吉祥的食物，这可能是因为在日语当中鲷鱼烧的读音类似于可喜可贺（おめでタイおめでタイ）吧。题外话，在日本曾有一首著名的歌曲就叫做“鲷鱼烧之歌”，它的歌词讲述的是一只厌倦了被铁板炙烤而逃到水里，最后却难以生存又被钓回店里是鲷鱼烧的故事，虽然这个故事的结局并不完美，而且是作为以儿童为听众的儿歌进行推广的，但它那与命运抗争却又无可奈何的歌词却引发了无数大人的共鸣与感动，最终令这首歌的发售量达到452万枚的传奇记录，更排进了20世纪日本百大金曲的前十。"
  },
  [125] = {
    order = 125,
    id = 423,
    desc = "油蜜果",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "POPQN",
    cv1 = "暂无",
    desc = "油蜜果，在中国也被称作是高丽馒头，是一种传统的韩国点心。通常的做法是在糯米面粉里加入酒等调料，合面成团后放入蒸笼蒸制，之后加工成点心的形状，再过油、炸熟、捞出，待油全部控净浸入蜂蜜当中，最后放入芝麻蓉或其他蓉料中摇滚以裹上一层香酥的脆皮。\n如此简单的制作方法、加上清甜软糯的口感，使得油蜜果大受欢迎，它过去曾是重要的宫廷食品，现如今普及到民间当中、作为礼仪食品被互相馈赠，它于韩国的地位就如饼干于西方一样，无论是茶余饭后、祭祀宴席，还是红白喜事，人们总能寻觅到到油蜜果的身影。值得一提的是，油蜜果的独特制作方法使得它最大限度的保持了蜂蜜的营养价值，而蜂蜜，自古以来都被韩国人视作是良药佳补，因此油蜜果在过去也被称作是“药果”。"
  },
  [126] = {
    order = 126,
    id = 422,
    desc = "水信玄饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "Criin",
    cv1 = "犬塚わんこ",
    desc = "水信玄饼，别名雨滴蛋糕，是一种来自日本的传统小吃。它的原型是信玄饼。据说在日本的战国时期，著名政治家、军事家武田信玄每次出征时都会携带一些糯米粉做成的软年糕当做应急食品，久而久之人们便将这种用糯米粉做成的点心以“信玄饼”来命名，而水信玄饼则是一家名为“金精轩”的日本点心店在信玄饼的基础之上进行改良而得来的——聪明的糕点师按照信玄饼的做法，将原料的糯米粉换为琼脂、保留信玄饼的传统蘸料，于是就诞生了现如今的水信玄饼。这种“年轻”的料理既保持着信玄饼那份传统的甜美，又拥有着如同水滴一般美丽剔透的外貌以及入口即化口感，从而产生出了所向披靡的吸引力，怪不得一些店家会称呼水信玄饼是“天使的眼泪”呢。"
  },
  [127] = {
    order = 127,
    id = 424,
    desc = "白糖糕",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "Alic",
    cv1 = "七濑千代子",
    desc = "白糖糕，又称伦教糕，是一道来自中国南方的美味点心，常见于广东、香港等地，相传白糖糕是因一位小贩在制作松糕时忘记放糕种而只靠米浆自然发酵而诞生的，但实际上白糖糕的做法远比看起来要复杂。\n它的具体烹饪过程是：先将籼米粉、白砂糖和清水一起混合，搅拌均匀，然后倒入锅中，继续在小火下搅拌至奶油状。接下来将浆液盛出，加入酵母、泡打粉以及温水，搅匀后放置发酵至少两个小时。待到发酵完成，滴入少许食用油搅拌，放进事先铺好蒸布的蒸笼，大火蒸 25 分钟，最后放凉取出。但需要注意的细节是：若想要将白糖糕做到完美，在混合白砂糖时要反复过滤面浆几次、筛去结团的米粉才能让口感变得细腻。而发酵的时间也要根据气温灵活调整，时间不足、发酵不充分则口感僵硬；时间超长，发酵过度，则会让味道变得过酸……总而言之，越是制作简单质朴的事物，越考验人的耐心与细心——这一道理说的正是白糖糕这样的料理吧。\n上等的白糖糕，颜色雪白，口感软糯、味道酸甜、又弹性十足，有所谓的“猪膏面”、“鸡爪纹”和“横直眼”。发酵产生的气孔能让简单的米面变得富有嚼劲，延长了白糖糕在人口中的时间，使之能够在口腔中与唾液充分混合，生成麦芽糖，从而使它的甜味变得更加丰满。这种醇厚的口感已经刻入了这片土地上人们的味觉基因，散发着经久不衰的吸引力，以至于在东西点心琳琅满目的今日，白糖糕仍在人们心中有着无可替代的地位。"
  },
  [128] = {
    order = 128,
    id = 426,
    desc = "司康饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "+midori+",
    cv1 = "暂无",
    desc = "司康饼是英国茶文化中不可或缺的。它是一种起源于苏格兰的面包点心。\n司康饼的原料原本是燕麦，但在现代则往往选用小麦粉作为原料。\n味道朴素，嚼起来咯吱咯吱的，很多人都喜欢司康饼的这种口感。\n司康饼是英国下午茶时间必不可少的存在。\n在英国，每个家庭都有自己独特的司康饼制作手法，作为自家的味道被流传下去，司康饼的颜色、形状、味道也因家庭而异。\n关于司康饼的由来，说法很多，有一种说法是其来自于荷兰语中含意为“优质白面包”的单词，也有一种说法是，司康饼的名字来源于苏格兰首都-帕斯中的司昆城里，国王加冕仪式中作为椅子使用的名为命运之石（Stone of Destiny，也叫司昆石-Stone of Scone）的基石。\n英国以外的地方也有很多人在吃司康饼，而相较于美国的司康饼，英国的司康饼不会放糖，所以不甜。\n所谓“奶油茶”（下午茶的一种），其实便是就着红茶来吃涂抹了果酱和凝脂奶酪的司康饼，这样一种吃法。\n司康饼不是直接拿起来就吃的，正统的礼节是将其切成两半以后再吃。涂抹奶油和果酱的话，也是每次只涂一口的分量，吃一口涂一次。"
  },
  [129] = {
    order = 129,
    id = 421,
    desc = "巧克力",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 4,
    skill = 3,
    formation = 5,
    painter = "拿铁",
    cv1 = "暂无",
    desc = "巧克力，别名朱古力，是以可可豆为原材料制成的，人尽皆知的著名甜品。其原型是美洲的阿兹特人以可可豆加水及香料制成的饮料“苦水（Xocolatl）”，在西班牙探险家荷南多·科尔特斯将其引入国内后，西班牙人在此基础上加甜、加香、加温，发明了热饮“巧克力”，其后由于西班牙公主玛丽亚·萨尔莎将可可豆作为订婚礼物呈献给路易十四，这种全新的饮品开始风靡于贵族之间。\n——非常有趣的是，巧克力曾作为一个重要的秘密被西班牙人保守了长达一个世纪之久，直到一些被委托加工可可豆的西班牙僧侣泄露了相关的秘密，巧克力才在整个欧洲流传开来。而在此之后，工业化生产与商业运作为巧克力带来更多的变化与机遇：先是在1876年，瑞士人彼得试着在巧克力中加入牛奶，由此奠定了人们所熟知的巧克力的基本配方，而后到了1874年，英国的一家公司又别出心裁地将巧克力脱水浓缩，变成方便携带的固体巧克力（糖）。原本被当做药品食用的巧克力，至此才真正完成了向食品蜕变的过程。\n之所以巧克力有着如此历久弥新而又强大的吸引力力，与其甜苦适中、丝滑柔顺的口感是密不可分的，但巧克力的其他优点也不可不提：首先它有着较多的糖分、较高的脂肪，被加工成块状后更便于携带，所以能够成为一种重要的食物储备，其次，巧克力当中含有可可碱是一种反镇静成分，而巧克力中添加的糖分又能刺激大脑分泌内啡肽，因此适量摄入巧克力是有助于提升精神、缓解压力的。\n话虽如此，食用巧克力也应当适度。它所含有的过高糖分与脂肪会成为体重的大敌，而且巧克力当中的可可碱对于人类以外的许多动物而言是具有毒性的，切勿拿巧克力投喂宠物哦？"
  },
  [130] = {
    order = 130,
    id = 420,
    desc = "草莓大福",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "月见",
    cv1 = "七濑千代子",
    desc = "草莓大福是一种日式点心，由糯米皮包裹豆沙与整颗草莓做成。制作的时候，需要先将糯米粉与水拌成糊状，用大火蒸20分钟至熟。然后放入盆中，加入砂糖与黄油拌匀，直到面团表面光滑又富有弹性时即可。接着准备馅料，用豆泥包裹好新鲜草莓。最后将馅料包入糯米面团中，外层再蘸一些糯米粉以防粘手，草莓大福就完成了。制成的草莓大福，外形圆浑有致，像一只大号的团子。据说就是因为这样可爱的外形，大福起初被称为“大腹饼”，后人取吉祥的谐音，便改为了“大福”。享用时，对着草莓大福一口咬下，瞬间就能感受到外皮的清凉软糯、豆沙的细腻甜蜜，以及草莓的鲜嫩芳香。三种滋味混合在口中，妙不可言。如今草莓大福与诸多日式点心一起，作为“和果子”的代表，在全世界吸足了人气。值得一提的是大福在中国还有个好听的名字，叫做“雪媚娘”。"
  },
  [131] = {
    order = 131,
    id = 427,
    desc = "栗金团",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "wu家小子",
    cv1 = "暂无",
    desc = "栗金团，正如其名，是以栗子为原料制成的金色团块状甜品。这道料理金灿灿的外观看起来就像是大块黄金，因此被视作是一道“可以吃的招财符”。相传人们在正月吃下栗金团就可以在新的一年中财源广进、金运大开。制作栗金团自然需要用到栗子，除此之外还会使用到黄瓤的红薯来提色，在烹饪的时候，先将新鲜去壳的栗子与红薯蒸熟，去皮，一起用勺子碾成细泥，然后加入糖水置于小火上慢慢熬煮，待到栗泥和薯泥完全吸收水份变得粘稠时用勺子或布将其调成团状即可装盘盛出。新鲜出炉的栗金团口感软糯，细腻香甜，栗子香混合红薯香为品尝者带来浓厚的幸福感。不过吉兆虽好，但却不可贪心哦。栗金团是热量较高的食物，食用过多的话不但会感觉到过度甜腻，随着还会影响消化。所以最好的品尝方法还是冲一杯抹茶、找两个小勺，之后与心爱之人一起慢慢分享这一团柔软的幸运。"
  },
  [132] = {
    order = 132,
    id = 428,
    desc = "千竹",
    open = 1,
    atkSpeed = 3,
    hp = 1,
    atk = 2,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "—PHI—",
    cv1 = "日高里菜",
    desc = "隶属魂器学院的学员、能够操控魂智能武器=魂器的特异之人。出身于派森地区的她拥有着与年龄相符的天真烂漫，与此同时善良又热心，会向一切身处困境之人施以援手……嗯，如果能改掉毛手毛脚、越帮越忙的毛病，应该就是完美无缺的存在了。她在魂姬中代号是“竹间掠影”，成名技是将一切可接触物体射出、与意识中预设点进行百分百重合的能力“定点移动”，潜在实力极为强大。或许是因为千竹对汤圆的热爱超乎常人吧，在料理次元遭遇危机之时，她被神秘的声音所召唤、作为全新的主厨展开冒险。"
  },
  [133] = {
    order = 133,
    id = 429,
    desc = "海拉",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 5,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "巫贼ikataruto",
    cv1 = "門脇舞以",
    desc = "冥界的女王。虽然似乎有着闪耀的头衔，但其实是被奥丁贬降到冥界，其自由也被项圈所禁锢。她的性格一半像天使一样纯洁无暇，另一半却像恶魔一般残忍狰狞。无处可去的海拉接纳着一切来自阳间的客人，无论是杀人犯还是冤死鬼，是英勇战死还是老病而逝的灵魂，她都一视同仁地收留。“来成为我的朋友吧~”没有人知道这幅笑容到底是来自她天使的一面，还是恶魔的一面。"
  },
  [134] = {
    order = 134,
    id = 430,
    desc = "雪女",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 2,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "樾月",
    cv1 = "佐藤利奈",
    desc = "住在高天原偏远地区的妖怪，山神的女儿，掌管冬季和落雪，有时会以雪兔的姿态出现。爱把看上眼的东西冻成冰带回住处，讨厌外乡人老把她与山姥混淆，身处很热的地方会飞速落跑或干脆瘫倒在地。"
  },
  [135] = {
    order = 135,
    id = 433,
    desc = "驴打滚",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 3,
    phyDef = 2,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "　传说乾隆皇帝平息了大、小和卓叛乱后，把新疆的一个维吾尔族首领的妻子抢到宫中为妃，也就是香妃。香妃被抢到北京后，日夜思念丈夫，水米不进。乾隆急坏了，传旨御膳房：如果谁能做出香妃爱吃的东西，不但升官，还赏银千两！御厨们使出了看家本领，山珍海味，风味名吃，做了数千样，但香妃缺连看也不看。乾隆只好下旨，令白帽营的人给香妃做家乡吃食送进宫。\n　　巧合的是，香妃的丈夫自香妃被抢进宫后，也跋山涉水从新疆来到北京，藏身在白帽营里，想方设法打听香妃的下落。当他听说皇帝下旨让白帽营的人做一样好吃的东西送进宫去给香妃吃，觉得这是个联系的好机会，于是就做了一盘他家祖传的自制点心江米团子。这团子外层粘满豆面，呈金黄色，豆香馅甜，入口绵软，别具风味，豆馅入口即化，是香妃的最爱。\n　　江米团子送到宫中，宫女把驴打滚端到香妃面前，香妃一见，睛睛一亮，心中思绪万千，知道是丈夫来了，便强打精神，夹起一个，轻轻咬了一口。\n　　乾隆听说香妃吃东西了，高兴地不得了。下旨让白帽营的艾买提天天做这种点心送进宫来，香妃也因此不再闹别扭，渐渐得了皇上的宠幸。从此，这种连皇妃都能取悦的点心便慢慢有了名气，后来又流传到了民间，成为了当今风靡一方的地方小吃。因其最后制作工序中撒上的黄豆面，犹如老北京郊外野驴撒欢打滚时扬起的阵阵黄土，因此而得名“驴打滚”。"
  },
  [136] = {
    order = 136,
    id = 435,
    desc = "十八街麻花",
    open = 1,
    atkSpeed = 5,
    hp = 4,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 3,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "漫道",
    cv1 = "暂无",
    desc = "　　桂发祥十八街麻花是一道传统名点。天津市的百年老字号麻花店，与天津狗不理包子、耳朵眼炸糕并称的“天津三绝”。桂发祥十八街麻花在全国首届名小吃认定会上被认定为“中华名小吃”，1996年被中国国内贸易部命名为“中华老字号”，曾荣获国家部优金鼎奖、亚太地区博览会金奖，并被认定为中国驰名商标、天津市名牌产品及天津市著名商标。\n　　清朝末年，在天津卫海河西侧，繁华喧闹的小白楼南端，有一条名为“十八街”的巷子，有一个叫刘老八的人在这个巷子里开了一家小小的麻花铺，字号唤作“桂发祥”。这个人炸麻花有一手绝活，炸的麻花真材实料，选用精白面粉，上等清油。他的铺子总是顾客盈门。后来，他的生意越做越大，开了店面。开始还算是宾客满盈，但是随着时间的推移，大家越来越觉得麻花有点乏而生腻，渐渐的生意就不如以往了。后来店里有个少掌柜的，一次出去游玩，回到家是又累又饿，就要点心吃，可巧点心没有了，只剩下一些点心渣。又没有别的什么吃的，那少掌柜的灵机一动，让人把点心渣与麻花面和在一起做成麻花下锅炸。结果炸出的麻花和以前的大不一样，酥脆不艮，香气扑鼻，味道可口。按照这个方法，刘老八研究在麻花的白条和麻条之间夹进了什锦酥馅。桂花、闽姜、核桃仁、花生、芝麻.还有青红丝和冰糖。为了使自己的麻花与众不同，增强口感味道，把放置时间延长，取材也是愈来愈精细，如用杭州西湖桂花加工而成的精品咸桂花、岭甫种植甘蔗制成的冰糖、精制小麦粉等等。如今的“桂发祥”的招牌是由书法名家赵半知所题写。最终形成什锦夹馅大麻花，“桂发祥”麻花也随时间的酝酿慢慢成了“天津三绝”之一。"
  },
  [137] = {
    order = 137,
    id = 436,
    desc = "牡丹饼",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "朝露",
    cv1 = "hana*",
    desc = "相传牡丹饼的发明人为武则天。据《隋唐佳话录》载：有一年花朝节即谷雨牡丹盛开的季节。她率宫女游园赏花，看着争奇斗艳的花儿，突发奇想。命令宫女采下大量的各色花朵，回宫按她的设计，和米捣碎，蒸制成糕，即名“百花糕”，并用这香糯可口的点心作为礼品分别赏赐群臣。故牡丹饼又称“百花糕”、“牡丹糕”。\n牡丹饼又称“天皇饼”，原因是武则天与唐高宗并称天后、天皇。宋代词人黄庭坚《渔家傲》有“方猛省，无声三昧天皇饼”之句，说的就是牡丹饼。唐贞观二十三年（649年），武则天被发送长安感业寺削发为尼后，偶以牡丹花瓣为原料制成素饼，一食之，速觉味道非凡，恰高宗相访，武则天以饼传情。不久还宫，立为皇后，高宗称天皇，她称天后。因此饼出自皇家，时人称此饼为天皇饼。\n隋、唐两代中日交往频繁，洛阳牡丹传至日本，日本国的画师，把富丽端庄的中国牡丹彩绘在奈良“春日神社”的墙壁上，被日本人民奉若至宝。牡丹饼的制作也从中国传到日本，相延千余年，牡丹饼仍风行于日本民间。"
  },
  [138] = {
    order = 138,
    id = 437,
    desc = "奶油泡芙",
    open = 1,
    atkSpeed = 5,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 5,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "朝露",
    cv1 = "朝露",
    desc = "16世纪传入法国，泡芙的诞生，在技术上被人们认为是偶然无意中发现的，情形是从前奥地利的哈布斯堡王朝和法国的波旁王朝，长期争夺欧洲主导权已经战得精疲力竭，后来为避免邻国渔翁得利，双方达成政治联姻的协议。于是奥地利公主与法国皇太子就在凡尔赛宫内举行婚宴，泡芙就是这场两国盛宴的压轴甜点，为长期的战争画下休止符，从此泡芙在法国成为象征吉庆示好的甜点，在节庆典礼场合如婴儿诞生或新人结婚时，都习惯将泡芙沾焦糖后堆成塔状庆祝，称作泡芙塔（Croquembouche），象征喜庆与祝贺之意。"
  },
  [139] = {
    order = 139,
    id = 431,
    desc = "香草雪球",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 2,
    phyDef = 2,
    hit = 6,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "Akko",
    cv1 = "暂无",
    desc = "谈起冰淇淋，大家往往都能很容易想到香草，因为这样的搭配实在是很经典。不过，在生产香草冰淇淋时，一般的做法都是使用更廉价的香草精，如果能真的用到香草的话，那么这款冰淇淋也会连同口感和价格一起变得“高档”起来。\n会有这样的事，也是因为香草是一种较为名贵的热带天然香料。它的学名是香荚兰，能散发出梦幻般愉悦的香气，它曾经是皇室才能独享与拥有的尊荣。不仅仅是我们所熟悉的冰淇淋，包括糕点，糖果，甚至是化妆品和药物，都能见到香荚兰的身影。当然，提起香草，最经典的还是香草冰淇淋——等待着店家用球形的铁勺子，在洁白而有零星香草籽点缀的冰淇淋上娴熟的挖出一个完美的球形，再盛放在玻璃盏或蛋卷中，嗯～美好的夏天。\n不过，谈起香草冰淇淋，果然也不能忘记冰淇淋本身的历史——大约在1700年，冰淇淋传入美洲大陆，美国首任总统乔治·华盛顿对这种新工艺痴爱异常。当时，冰淇淋的制作相当不易，人们要想在夏天吃到它，不得不在冬天到河里取冰块，把它们贮放在锯末里。1846年，美国的一位名叫南希·约翰逊的女士对复杂的工艺进行了改进，制造了一种手动曲柄式冷冻机，使冰淇淋的制作工艺更加简单容易。1851年，美国人扎卡布·费斯赛尔在美国马里兰州的巴尔的摩开办了美国首家冰淇淋制作工厂。1900年，由于电力和热力学理论的广泛应用，冰淇淋的制作过程加快，降低了成本，从而使价格大大下降。从那以后，冰淇淋就开始成为一种普及的降暑食品。\n不管怎么样，冰淇淋与香草的完美结合都提现了料理无穷的魅力，还有人们对幸福的美好追求——夏天要是很热的话，就来找香草雪球玩吧！"
  },
  [140] = {
    order = 140,
    id = 432,
    desc = "糖画",
    open = 1,
    atkSpeed = 5,
    hp = 6,
    atk = 2,
    phyDef = 2,
    hit = 6,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "糖画，不仅仅是料理，更是一门传奇的手工艺术。以糖为材料来进行造型，所用的工具仅一勺一铲。糖料一般是红、白糖加上少许饴糖放在炉子上用温火熬制，熬到可以牵丝时即可以用来浇铸塑型。\n塑型时，由艺人用小汤勺舀起熔化的糖汁，在石板上飞快地来回浇铸，画出造型，民间艺人的手上功夫便是造型的关键。当造型完成后，随即用小铲刀将糖画铲起，粘上竹签，便可成型。\n据考，糖画起源于明代的“糖丞相”。清代小说家褚人获的《坚瓠补集》里载，明俗每新祀神，“熔就糖”，印铸成各种动物及人物作为祀品，所铸人物“袍笏轩昂”，俨然文臣武将，故时戏称为“糖丞相”。\n到了清代以后，糖画更加流行，制作技艺日趋精妙，题材也更加广泛，多为龙、凤、鱼、猴等普通大众喜闻乐见的吉祥图案，而后又逐渐演变发展，终于成为今日的糖画艺术。\n糖画不仅能吃能玩，一些厉害的艺人甚至可以用它做成皮影戏，在好奇的孩子们眼前演出一场栩栩如生电影来——想必这便是中华大地民间故事与料理凝结而成的最高艺术境界吧。"
  },
  [141] = {
    order = 141,
    id = 434,
    desc = "跳跳糖",
    open = 1,
    atkSpeed = 5,
    hp = 2,
    atk = 2,
    phyDef = 2,
    hit = 6,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "　比起其他料理，跳跳糖显得非常年轻。它是1974年开始出现在美国市场上的创新糖果，发明人是美国通用食品公司的研发科学家米切尔。1985年，卡夫食品买下了跳跳糖的制造权利并重新命名为Action Candy，并且通过一家叫碳酸糖果的子公司生产跳跳糖。\n　　同年，卡夫食品将跳跳糖的制造设备、技术以及亚洲区销售权卖给韩国的Jeong Woo Confectionery公司（今韩国GF株式会社）。在韩国GF株式会社开始制造跳跳糖之前，卡夫公司制作粉状跳跳糖，GF株式会社将其改良为晶体状（之后又将其与脚丫等形状的棒糖搭配），从而更方便食用。这种晶体状跳跳糖在1988年时被珍宝珠旗下的UniConfis公司重新以Crazy Dips的名字进口到美国贩卖。\n　　关于跳跳糖会“跳”的原理，它其实是在糖里边加入了压缩的二氧化碳。由于（口）水的溶解作用，外边的糖融化，二氧化碳冲出，才会有噼啪噼啪跳起来的感觉。\n　　近年来这样的小零食已经不再像以前那么风靡了，大概是更好的零食在不断的推陈出新？至少，这可是一代人的童年回忆呢。记得要永葆童心哦，可爱的主厨～"
  },
  [142] = {
    order = 142,
    id = 438,
    desc = "皮蛋慕斯",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 2,
    phyDef = 2,
    hit = 6,
    miss = 3,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "暂无",
    desc = "比起传统甜品，皮蛋慕斯堪称一场舌尖上的化学革命。最早可追溯至2010年，香港某实验餐厅主厨将松花皮蛋打碎融入法式奶油霜，用液氮急速冷冻形成霜花纹理，这项\"黑钻石甜点\"在亚洲分子料理界引发震动。2016年上海米其林二星餐厅\"琥珀\"改良配方，以竹炭粉包裹皮蛋慕斯芯，创造出\"水墨流心\"的视觉奇观。\n　　关键技术在于温度控制——慕斯体需维持在4℃保持固态，而中心皮蛋浆则通过海藻胶包裹技术，在37℃口腔温度下瞬间释放溏心质感。日本食品科学家佐藤良平曾用高速摄像机记录，当银勺破开慕斯表层时，皮蛋结晶花纹会以0.3秒/次的频率颤动，这种\"视觉鲜味\"让咸甜碰撞更具冲击力。\n　　如今全球已有23家米其林餐厅将皮蛋慕斯列为招牌，纽约现代艺术博物馆甚至为其开设\"食物解构主义\"特展。虽然仍有食客形容这是\"恶魔的甜点\"，但不可否认，当皮蛋的金属感遇上慕斯的绵密，恰似水墨在宣纸上晕染开来，这大概就是东方哲学里的阴阳相生吧？勇敢尝新的主厨大人，你的下一道传奇甜品或许就藏在这危险的美味里呢。"
  },
  [143] = {
    order = 143,
    id = 501,
    desc = "腌花瓜",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 2,
    skill = 3,
    formation = 2,
    painter = "TN千夏",
    cv1 = "岛袋美由利",
    desc = "腌花瓜是腌黄瓜的别称，昌北泡菜的一种。\n花瓜指的是非常早期未成熟的黄瓜，比较矮小短胖。\n用盐、姜、蒜、辣椒、酱油等腌制而成。\n黄瓜原产印度，由西汉时期张骞出使西域带回中原的，称为胡瓜，因隋炀帝忌讳胡人，将其改为“黄瓜”。\n因为现代主要食用的都是未成熟的黄瓜，因此很难理解“黄瓜”这个名称，但成熟的黄瓜确实是黄色的。\n黄瓜从很早就从印度传播开来，因其口感佳并富含水份在世界各地普及，但是其实营养价值十分有限，外加腌制品含有大量盐分，因此不适合被大量摄取，比较适合作为配菜食用。\n根据研制的时间长短，腌花瓜的口感也会不同，可根据自己喜好调节研制的时间。"
  },
  [144] = {
    order = 144,
    id = 502,
    desc = "薯条",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 3,
    formation = 3,
    painter = "TN千夏",
    cv1 = "结崎有理",
    desc = "快餐必备的料理。\n把马铃薯做成波纹状或细条，放到油中炸做成。\n一般会搭配西红柿酱，蛋黄酱等酱料来食用。\n薯条发祥于17世纪比利时。\n虽然常作为头盘或者配菜，在快餐中几乎是必备的料理，但在发祥地的比利时，往往被当作主食。比利时人对薯条的执念也和其他国家不同，对薯条的宽度，马铃薯的品种有严格规定，油炸也必须炸2次以上，甚至还把薯条定为国内的无形文化遗产。\n不过真正把薯条传播到全世界的，还是因为世界范围内快餐店的崛起，所以薯条的形象也和快餐密切连结了起来。\n薯条，汉堡，可乐。无敌的快餐铁三角，永远是快餐的黄金组合。也被世人所爱戴。"
  },
  [145] = {
    order = 145,
    id = 504,
    desc = "凯撒色拉",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 2,
    formation = 4,
    painter = "Asrid",
    cv1 = "金子彩花",
    desc = "禁酒令时代诞生于的位于墨西哥的意式餐厅的料理。\n凯撒色拉的主要组成材料是莴苣，大蒜，盐，胡椒，柠檬汁，橄榄油，面包粒，鸡肉等。\n凯撒色拉的名字来至于创作者凯撒·卡狄尼，和古罗马的凯撒大帝没有任何关系。\n凯撒色拉的诞生时期是在1924年，当时美国处于禁酒令时期。美墨边境的蒂华纳成为了在好莱坞工作的美国人聚集饮酒的地方。在7月4日，餐厅耗尽了厨房内所有的东西，因此厨师凯撒用他仅剩的食材，制作出了凯撒色拉。而这道菜也通过好莱坞工作的人们传回了美国，并最终传播到了全世界。"
  },
  [146] = {
    order = 146,
    id = 512,
    desc = "温泉蛋",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 2,
    skill = 3,
    formation = 4,
    painter = "ct",
    cv1 = "戸松遥",
    desc = "温泉蛋是蛋黄部分半熟、蛋白部分半凝固的水煮蛋，特征是蛋白部分已经成型，但蛋黄还处于浓滑柔软的状态。而利用温泉的恒温水和蒸汽煮出的蛋，不管蛋黄和蛋白是否半熟，也都叫做温泉蛋，也是它得名的由来。\n由于蛋黄在80℃以下不会凝固，蛋白则在超过60℃就会凝固，所以在恒温60℃至80℃之间的温泉或热水，都可做出温泉蛋。在一些露天温泉或者温泉旅馆，只要温泉温度适中，就会将鸡蛋浸入温泉制作温泉蛋，而有些温泉温度过高，也可以将鸡蛋隔着容器放在热温泉冒出的蒸汽上。\n煮好的温泉蛋只要浇上酱油便能够食用，虽然简单朴素，口感却咸鲜软糯、嫩滑可口，只要想想就能让喜爱鸡蛋的食客心动不已。"
  },
  [147] = {
    order = 147,
    id = 503,
    desc = "春卷",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 4,
    formation = 3,
    painter = "月见",
    cv1 = "岩井映美里",
    desc = "春卷是中国民间节日的一种传统食品。\n用春卷皮将馅料包成扁圆筒状，并煎炸而成。\n春卷历史悠久，由古代的春饼演化而来。非常象征春天到来的食物。\n于立春当天，人们用饼皮包裹春天采集的蔬菜，做成春饼，大家分食，祈求身体健康，称之为“咬春”，逐渐变成日常食物。\n春卷的馅料和大小各式各样，根据地区不同有很大差异，南方加蔬菜和肉较多，北方则是豆沙馅较多。\n除中国外，春卷还传播到了世界各地，尤其在东南亚有很多变种。如菲律宾，印度尼西亚的lumpia，泰国的Popiah，都是由春卷演变而来，越南的生春卷甚至成为了代表越南的料理之一。\n中国的春卷以油炸的为主，但是也有非油炸的春卷，越南生春卷就是一种非油炸的春卷。\n据说吃立春和春节期间时吃春卷，能为一年带来好兆头。"
  },
  [148] = {
    order = 148,
    id = 505,
    desc = "法式蜗牛",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 4,
    formation = 2,
    painter = "海盐冰",
    cv1 = "暂无",
    desc = "法国人食用蜗牛的历史可以追溯到几百年前，除了直接食用外，也以蜗牛为原料创作了各种菜肴。\n法式焗蜗牛就是其中最为著名的一道，具体做法是：蜗牛焯水后挑出蜗牛肉，用白酒、胡椒、百里香、柠檬片腌渍，接着与洋葱、蒜泥一起煸炒，放入蜗牛壳中，最后用蛋泡或者黄油香草末封口完成。\n由于原先生活在勃艮第地区的野生蜗牛非常多，所以原本蜗牛只是法国农民餐桌上的家常菜而已。但是随着人们食量增大、杀虫剂在农业中的广泛使用，野生蜗牛越来越稀少，即使现在法国开始人工饲养，蜗牛仍是供不应求。统计显示法国人一年要吃掉三十万吨新鲜蜗牛，其中 90% 依赖进口。\n\n也正是因为历史悠久和原料稀少，蜗牛在法国变得愈发名贵，最终成为富人们在隆重场合才能享用的佳肴，并升级成为法国的“国菜”。"
  },
  [149] = {
    order = 149,
    id = 507,
    desc = "凉粉",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 3,
    skill = 4,
    formation = 4,
    painter = "西行寺科学子",
    cv1 = "金子彩花",
    desc = "凉粉是中国夏季常见的风味料理，制作过程十分简单，将绿豆粉糊浇入烧开的水中，充分搅拌后放凉即可完成。食用时，往往将凉粉切成条状，与酱油、醋、辣椒等混合成的酱汁一同装盘。\n浸润过酱汁的凉粉，非但不会失去原有的爽滑口感，还增加了浓郁刺激的香气，让舌尖同时体会到清凉与酸辣两种感觉，不得不说是一种魔法般神奇的组合。除此之外，凉粉还有煎、炒等多种吃法，对口味不同的凉粉爱好者都能够很地满足。\n历史上最早关于凉粉的记载出现在《东京梦华录》，由孟元老著作于北宋。书中描述在汴梁地区有名为“细索凉粉”的菜品，被认为是现代凉粉的原型。\n如今，除了绿豆粉之外，也有用红薯粉、豌豆粉制成的凉粉。这道外形酷似水晶的小菜，让平凡的食材在夏天展现出了别样的风采。"
  },
  [150] = {
    order = 150,
    id = 510,
    desc = "鱼板",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 4,
    formation = 3,
    painter = "—PHI—",
    cv1 = "筱原侑",
    desc = "好玩又好吃，可以做成各种形状和图案的日本食品。\n将白身鱼的鱼肉捣成鱼浆，再加入蛋白，砂糖，盐等蒸烤而成。\n \n鱼板也称蒲鉾。被认为自古以来就在日本被制造和食用，虽然确切的诞生日期并不明确，但现存记载了鱼板这项料理的最古老的文献可以追述到到平安时代的永久3年（1115）年。\n也因此日本业界将11月15日定为“鱼板之日”。\n在日本古时，白肉的鱼非常贵重，因此鱼板常常只有在节庆时才被享用，也常被用以当作馈赠品。一般认为鱼板开始作为商品被贩卖，时要到江户时代以后。\n \n鱼板除了直接食用外，也可以再煎炸成金黄色。\n将白色鱼板和加入食用色素的鱼板叠加，卷成卷筒状，然后将横切面切成薄片，就会成为我们常见的拉面上的鱼板。这种带有漩涡状图案的鱼板，也被叫做“鸣门”。"
  },
  [151] = {
    order = 151,
    id = 513,
    desc = "肴肉",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 4,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 2,
    painter = "隼熙",
    cv1 = "暂无",
    desc = "肴肉，是中国江苏地区的传统名菜，也是淮扬菜系中的代表冷菜。成菜肉红皮白，光滑晶莹，卤冻透明，犹如水晶，因此也有“水晶肴肉”的美称。\n肴肉诞生的故事开始于明朝。传说镇江的一位厨师，腌制猪蹄时错将硝（亚硝酸钠）当做盐擦在肉上，第二天打开腌缸时发现，猪蹄肉不但没有变质，反而变得更加紧实，颜色也更显红润。而且，将这些猪蹄配以五香调料焖煮一小时后，锅内竟散发出了非比寻常的香气，邻居们纷纷被吸引而来，酒店也从此名声大噪。在当时，这道菜被命名为硝肉。后因人们觉得“硝肉”之名不雅，于是便改为肴肉，延传至今。\n肴肉的做法不算复杂。首先是加工蹄膀肉，用竹签在瘦肉上戳一些孔，均匀撒上硝水，再抹上粗盐，与八角、桂皮、花椒等香料一齐放入缸内腌制两天左右。腌制完毕，需要将猪蹄放入清水中浸泡 10 小时，捞出后刮去肉皮上的污物，用温水冲洗干净。最后，用卤水焖煮 3 小时，取出后用重物压紧，冷透后即成肴肉。口感酥嫩易化，不肥不腻，配以姜丝香醋，色雅味佳。\n经过三百多年的发展，肴肉也有了新的变化。制成的肴肉，按照部位不同，分别切开，可以分成口感相异的多种肴肉块。例如前蹄上的老爪肉，多筋、柔软，状如眼镜，叫“眼镜肴”；前蹄旁的肉弯如玉带，叫“玉带钩肴”；后蹄上连着细骨的净瘦肉，叫做“添灯棒肴”……不同的风味总能满足口味各异的食客，让肴肉一直盛名不断，是被选入中国“开国第一宴”的优秀料理。"
  },
  [152] = {
    order = 152,
    id = 508,
    desc = "韩式泡菜",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 3,
    miss = 2,
    growth = 4,
    skill = 4,
    formation = 1,
    painter = "卑しい人间",
    cv1 = "佐藤亚美菜",
    desc = "韩国泡菜是最具韩国代表性的传统料理之一，是典型的发酵食品。\n因为诸多原因，朝鲜半岛的气候要比同纬度地区寒冷的多，可供蔬菜生长的季节较短，所以每到秋季，人们必须贮存蔬菜，作为冬天的维生素来源。用盐腌制蔬菜的习俗也就应运而生。\n\n因为原料、保存方法的不同，韩式泡菜有非常多的分类。首先蔬菜就有白菜、黄瓜、大葱、卷心菜等几个种类，接着因为地区不同，还有首尔京畿道式、庆尚道式、江原道式、济州岛式等等……\n\n比较大众的做法是，将白菜码上粗盐，倒盐水在盆中放置十五个小时。第二天白菜洗净，用鱼露、糯米、辣椒和多种香料制成的高汤混合，作为腌料，让白菜蘸满后放入坛中，封口发酵两到三天，此时的白菜味道最好。\n\n严格来说，用朝鲜半岛的做法所制作的“泡菜”，并不能称为“泡菜”。它与中国西南地区使用乳酸菌发酵的泡菜有明显的区别，称为腌菜更为合适。\n\n如今，对于韩国人来讲，泡菜已经不仅仅是一道小菜，更是一种传统，从每日三餐渗透到了文化当中。"
  },
  [153] = {
    order = 153,
    id = 509,
    desc = "辣条",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 3,
    formation = 4,
    painter = "小吃",
    cv1 = "佐仓绫音",
    desc = "占领中国各地小学学校的超人气零食。\n将面粉，加入水，盐，糖，天然色素等和面成面筋，经过膨化机高温挤压膨化，再加油，辣椒，麻椒等调味料调味而成。\n根据媒体的记录，辣条是在1998年被第一次制作出来，是毫无疑问的现代小吃。\n辣条的诞生地是湖南省平江县，那里有有着悠久的做酱干豆制品的传统。辣条最初的制作目的不是零食，而是当作主食的调味品，而后被加入了甜味的辣条，迅速占领市场，成为了小学生中人气最高的食品。\n \n辣条虽然是现代小吃，但辣条的主材料面筋，在中国有悠久历史，创于中国南北朝时期。面筋虽然是素食，但是拥有高蛋白并且有接近肉食的口感，所以在许多中华料理中都有作为材料出现，是一种很万能的食物。\n \n除了中国，辣条也逐渐被外国认知，在美国网站上一包辣条的价格往往可以达到2美元以上。"
  },
  [154] = {
    order = 154,
    id = 514,
    desc = "烟熏三文鱼",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "拿铁",
    cv1 = "暂无",
    desc = "烟熏三文鱼，顾名思义即是以烟熏的方法加工过的三文鱼肉，那一片色泽诱人、口感肥美的三文鱼肉染上了烤制食物的香气，令人更加的垂涎欲滴。据说这一料理最初是由因纽特人发明的，他们发现利用这种方法处理过之后，鱼肉可以长久保鲜而不变质。当然了，这只是一种流传较广的民间说法而已，在北欧、美洲、俄罗斯等高纬度地区，类似的处理三文鱼肉的方法寻常可见，印第安人甚至把熏三文鱼的过程视作是一个神圣的仪式，因为他们相信会有一种伟大灵魂会推进这一过程。\n值得一提的是，烟熏三文鱼的熏制工艺可被分为两大种，一种是热熏，也就是如大家想象的一般用燃烧的木头将鱼肉熏到半熟，这种处理是美国人的经典手法。而市面上最为常见的、一般人们最容易接触到的烟熏三文鱼大多采用的是冷熏制法，熏制在这一过程当中只起到增加风味的作用，鱼肉本身依然是生的。尽管无论是冷熏还是热熏，烟熏三文鱼的美味都无懈可击，但是在更进一步烹饪其他菜肴的时候还是要注意到生熟区别的，因而在选购的时候一定要对此多加注意哦？"
  },
  [155] = {
    order = 155,
    id = 517,
    desc = "艾果",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 2,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "6音",
    cv1 = "暂无",
    desc = "艾果，全称是艾叶米果，又被称作是青果、青团，是一种来自中国的地方传统美食。艾果的主要原料是艾草，由于拥有着一种能够驱赶蚊虫的特殊清香，艾草又被认为有着辟邪净化的作用，它常被用作装饰门庭、入药回阳、针灸驱寒，人们也会在清明节前后草木生长最旺盛之时割下艾草，将之洗净、晾干、捣碎，后扮在糯米粉中做皮，再裹入红糖花生芝麻等甜馅或香菇鲜肉混成的咸馅，从而做成美味的艾果享用。\n艾果虽不如月饼等节日美食知名、推广度高，但在人们心中有着很重要的意义，作为一种传统美食，艾果既是清明期间祭拜先人的祭品，也取清明采青之意，因此又得到了清明果之别名。值得一提的是，除了标准的团块状艾果外，很多地方的艾果包制方法都和饺子很相似，在旅行时看到“绿色饺子”，一定要注意区分是艾果还是饺子哦？"
  },
  [156] = {
    order = 156,
    id = 520,
    desc = "竹轮",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 3,
    phyDef = 1,
    hit = 3,
    miss = 2,
    growth = 4,
    skill = 4,
    formation = 3,
    painter = "雪樱樱",
    cv1 = "暂无",
    desc = "竹轮，又被称作是鱼竹轮或烤竹轮，受到20世纪八十年代热播的影视作品的影响，在中国香港又被称作是狮子狗鱼蛋，是一种来自日本是烤制鱼肉料理。其名竹轮源自它最初的制作方法，即将鱼肉泥、面粉、蛋液、调味料等充分混合，裹在竹签上或细木枝上并以火烤或蒸食。如此烤制完成后的竹轮散发着鱼肉与烤制食物的香气，表皮金黄诱人，口感弹嫩，即可以趁热作为小吃直接食用，也可以切片后作为配菜炒制菜肴，更可以保持着串串状态，下入关东煮或火锅中进行再加热后食用。\n\n相较于其他那些简洁却精致或粗犷但丰盛的日式料理，竹轮可谓是相当的“平淡无奇”，但这并不意味着竹轮不美味。它这种默默无闻却实在而充实的存在方式反倒打动了不少的美食爱好者，有许多著名的影视、动画角色最喜爱的料理正是竹轮呢。"
  },
  [157] = {
    order = 157,
    id = 506,
    desc = "关东煮",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "NORI紫菜",
    cv1 = "雨宫夕夏",
    desc = "日本料理中，分类为“煮物料理”的一种。\n做法非常简单，把各种食材放入事先做好的“出汁”中，长时间熬煮而成。\n适合做成关东煮的食材有，魔芋，白萝卜，甜不辣，海带结，竹轮，鱼丸等多种多样，而且根据不同地域也各有差异。\n关东煮的名称虽然在14世纪已经出现，但是真正发展成广为人知的料理还在江户时代，关东煮的日文名“おでん”原来是豆腐料理“田乐”的异称。而后“田乐”不仅作为豆腐料理，而发展为一种料理分类，其分田乐又分为两种料理手法，烧和煮。煮田乐则在江户时代被称为“关东煮”，中文译名也由此而来。\n因为关东煮里放什么完全由客人自己决定，因此很少会听说有人不喜欢吃关东煮，关东煮也因为无论是作为下酒菜，还是给小朋友吃的零嘴都很合适，所以在江户时代爆发式的占据了日本全国的各大餐厅，摊贩和家庭。\n由于翻译原因，可能会被误会，也存在“关西风”的关东煮。\n即使在现代，由于关东煮的便利性，可选性和保温的特点，不仅作为家庭料理，也深受各大便利店的喜爱。最早贩卖关东煮的便利店，是在1979年的7-11。"
  },
  [158] = {
    order = 158,
    id = 511,
    desc = "鱼子酱",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 4,
    formation = 4,
    painter = "山药酱",
    cv1 = "暂无",
    desc = "在西方国家，人们通常认为世界上最贵的食物有三种，它们分别是：黑松露菌、鹅肝酱以及鱼子酱。其中的鱼子酱更是有“黑色黄金”或者“软黄金”之称，而实际上顶级的鱼子酱，价格要比黄金还贵得多。\n在 19 世纪以前，鱼子酱一直专指鲟鱼卵制品。不久后，到了 19 世纪 30 年代，俄罗斯人开始用鲑鱼卵制作鱼子酱，从那开始，市场上也开始有了用飞鱼卵、鲱鱼卵、鳟鱼卵等制成的鱼子酱。但严格来说，能冠以正统的鱼子酱（Caviar）的正统之名的，只有鲟鱼卵一种。\n野生鲟鱼子酱的传统产地是位于欧亚两洲交接的里海——世界上最大的盐水湖泊。南岸属于伊朗， 西岸属于俄罗斯，这也注定了世界上的鱼子酱主要都产自于这两个国家。在里海，分布着三种可以生产鱼子酱的鲟鱼：闪光鲟、奥西特拉鲟和白鲟。在伊朗生产的鱼子酱外包装上，会用颜色区分鱼子酱的品种和等级，红色代表闪光鲟、黄色代表奥西特拉鲟、蓝色则是白鲟。其中白鲟的成熟期在 20 年以上，每 2~3 年产卵一次，非常的稀少，价格也高到了让人惊讶的每千克 9800 欧元。\n对于如此考究的食材，加工工艺的要求往往也极为严格。在鱼子酱工厂内，工人需要对刚取出的鲟鱼卵进行过筛分离、取出卵巢膜，同时将鱼子分级。过筛后的鱼卵会立刻拌上少许盐进行腌渍，盐的比例通常不超过鱼卵重量的 5%。盐量过高会破坏口感，过少则难以保存。除此之外，加工过程中的鱼子酱不可以接触冷水，否则口感会变得坚硬粗糙；也不可以过多的接触空气，防止氧化变质……而这些看起来复杂精密的工作，必须在鱼卵取出后的 15 分钟内完成，可以说是比加工黄金要严苛得多了。\n鱼子酱通常是直接享用，用小勺将它从包装里舀出，直接送入口中。切记的是不能使用金属勺，化学反应会影响鱼子酱的风味。专业一些的办法，是用贝壳或者象牙制的勺子，将鱼子酱舀少许在手背，从手背上享用它。\n湿润香甜，一粒一粒在口中爆开的感觉，绝对会让你对它欲罢不能。"
  },
  [159] = {
    order = 159,
    id = 519,
    desc = "芥末章鱼",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "僵僵僵酱",
    cv1 = "暂无",
    desc = "芥末章鱼是一道源自日本北海道的经典凉菜，它的主料自然是芥末与章鱼，在制作的时候，厨师们会将新鲜的章鱼洗净，去除嘴部、内脏、外膜，然后用精盐进行腌制。待到20分钟后放入爽口的贡菜，再浇上由酱油、醋、白糖与芥末制成的料汁。如此做出的芥末章鱼口感饱满，鲜香劲道，章鱼的鲜味被芥末的辛辣所调和，贡菜清脆的口感更衬托出新鲜章鱼的弹牙口感，令人回味无穷。\n当然了，这种烹饪方法对原材料的新鲜度与安全性有着极高的要求，同时也很考验食客们对芥末以及生鲜食物的接受能力。如果胃肠不好的话不妨在制作时适当地加热章鱼，用熟制的章鱼来做芥末章鱼也是不错的选择哦？"
  },
  [160] = {
    order = 160,
    id = 516,
    desc = "蓝纹奶酪",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "M",
    cv1 = "暂无",
    desc = "原产于英国的奶酪之一，同时也被称为法国最古老的奶酪。\n想冠以“蓝纹奶酪（斯蒂尔顿芝士）”之名，必须满足几个条件。\n其中之一便是要由制定的三个州所制作，其他地区，其他国家所制作的都不能称之为蓝纹奶酪。\n说到蓝纹奶酪（斯蒂尔顿芝士），一般指的是用青霉菌发酵的蓝色奶酪。\n用青霉菌制作的奶酪花纹精美，仿佛大理石一般。\n有着具有强烈特征性的气味，由青霉菌所带来的刺激性和特征都很鲜明，不同人对它好恶分明，但喜欢芝士的人对它的评价很高。\n蓝纹奶酪的味道浓郁程度随着发酵的时间不断提升。\n很适合与葡萄酒一同食用，尤其适合甜味很浓的贵腐葡萄酒。\n不只是直接食用，用它制作的意大利面和色拉也是十分美味的。\n名字的由来是英国的一个村庄。而至于为什么这种奶酪是由在这个村子诞生的，大家对此众说纷纭，但似乎只要是在这个村子住宿，旅馆都会给客人提供这种奶酪。"
  },
  [161] = {
    order = 161,
    id = 526,
    desc = "春日",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "忍村的领导人，年纪轻轻就获得了“木影”之称号的天才忍者。沉默寡言，总是将所有的情绪与想法都藏于心底，与此同时，也最为擅长将自己的身影隐匿于自然之中，待猎物放松警惕的瞬间一击取其性命。虽无名刀名刃，但靠鬼神般的武艺可随时随地都可取人性命，生杀予夺，变化万千，正可谓是真正的“杀生者”。\n然而与晓一样，春日原本也只是个天真烂漫的少女，变幻莫测的“命运”夺去了她的家人，改变了她本该无忧无虑的未来，她的人生亦因为“与春日山城当代守护相遇”以及“杀死春日山城当代守护”而走上了无法预料的道路……为了“杀死”某物，春日今日也潜行于暗影之中。\n被召唤至这个世界的春日依然终日与“死”相伴，她遵循着命运的牵引，再度站到春日山城这一因缘建筑以及本该被杀死的“那个人”面前……"
  },
  [162] = {
    order = 162,
    id = 523,
    desc = "生腌膏蟹",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 4,
    phyDef = 1,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "希缇大王",
    cv1 = "暂无",
    desc = "也许有人会对“全中国最懂吃的地方是广东”有异议，但恐怕没有人会怀疑广东人在吃与烹饪上的造诣，作为中国的一大美食之乡，广东这片大地上诞生了无数山珍海味与精致小吃，然而有不少广东人却独爱一道做法粗矿的生腌膏蟹。\n想必大家已经猜到这款珍奇料理的做法了——没错，生腌膏蟹制作起来正如其名，在海蟹最肥美之季取来膏满黄足的鲜蟹数只，将其放入酒坛中浸泡，促进吐净污物，随后整只下入用酱油、粗盐、辣椒、香料、香菜头调制出的腌汁当中。经过一整个下午的腌制，蟹肉已充分入味，此时将其放入冰箱冷冻，直至彻底结冰。食用时让结冰的海鲜自然解冻到残留冰渣的程度，再以刀破成数份即可装盘上桌。\n也许有人会担心不加热处理的螃蟹食用起来是否安全，也许有人会怀疑做法如此简单的生腌膏蟹是否真的好吃。其实这两点都不必担心。生腌膏蟹虽不对螃蟹进行热处理，但腌料与腌制过程已基本除去了危险物质，肠胃健康者均可尝试。与此同时，未经过蒸煮烹制的蟹肉晶莹剔透，冰凉爽口，酱油与辣椒充分刺激味觉，使得被充分保留的海鲜鲜甜的味道被极限释放，让人吃上一口就停不下来，不愧为广东人心目中的“潮汕毒药”。"
  },
  [163] = {
    order = 163,
    id = 518,
    desc = "蚵仔煎",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "PHI",
    cv1 = "暂无",
    desc = "蚵仔煎，又称海蛎煎，是一道流行于台湾、潮汕等地经典小吃。它是用新鲜的蚵仔、虾仁、豆芽菜等食材制成的煎烙美食。制作蚵仔煎时需要先将这些主料放到热锅上煎烤，大约煎至4成熟时浇入太白粉制成的面糊，再打入生鸡蛋。继续煎烙，直至鸡蛋完全熟透后出锅，装盘时还要淋满爽口刺激的甜辣酱。如此做出的蚵仔煎外皮香脆，馅料鲜美，甜辣酱带来的味觉冲击与蚵仔肉的肥嫩口感相得益彰，让食客大呼好吃过瘾。\n有关于蚵仔煎的历史，有人认为如此美味的料理是起源于郑成功想出的绝妙烹饪方法，也有人相信它 在海上航行的渔民用随船携带的食材烹饪三餐演变的结果——无论真相到底如何，可以十分确定的一点是，蚵仔煎诞生于一个物资相当匮乏的时代，这种出身令蚵仔煎十分理解普通百姓生活中的酸甜苦辣，无外乎蚵仔煎被称作是闽南一带最为美妙的小吃呢。"
  },
  [164] = {
    order = 164,
    id = 527,
    desc = "脆炸鸡排",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "未定",
    cv1 = "暂无",
    desc = "如果有人要求你列出一张“垃圾食品”名单，炸鸡的名字绝对会名列前茅吧。尽管高热量、高油盐、高温油炸都是有据可查的对健康有害，但人类的抵抗力在油炸鸡肉带来的快乐面前实在是不值一提。这种食物就仿佛是人性弱点的大集合——大块鸡肉，刺激着人类饕餮肉食的欲望；充足调料，给人带来延绵不绝的味觉刺激；金黄外皮，直接用酥脆这一原始的嗜好击碎理性。而脆炸鸡排正是把这一切优点放大到极致的产物，它选用整块鸡胸肉做原料，在稍作腌制后包裹上蛋液与面包屑或番薯粉，下油锅快速煎炸，出锅后再用剪刀剪切成适合入口的大小，之后撒上盐、胡椒粉与辣椒面等香料混合而成的调料即可大快朵颐。相较于更为原始的炸鸡腿，鸡胸肉虽少了几分鲜嫩，但却免去了上手吐骨的辛劳，而且入味更加均匀，搭配上柠檬汁和蔬菜一起食用更具风味。还有什么料理能比脆炸鸡排更容易、更便捷、更经济地让人感受到快乐呢？如果想要犒劳一下自己，就选择脆炸鸡排吧！"
  },
  [165] = {
    order = 165,
    id = 528,
    desc = "龙井虾仁",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "电绵羊",
    cv1 = "暂无",
    desc = "细想想，龙井虾仁这道菜还真是奇妙。这世间以饮料来调味的美食并不算少，采茶入菜也并非新鲜花招，但是像龙井虾仁这样，用名贵的龙井茶去陪衬随处可见的河鲜，就着实是件稀罕事情了。据说，创造龙井虾仁的大厨受到了《望江南·超然台作》一词启发——这当然只是后人杜撰出的名堂——但若想把龙井虾仁做得有滋有味，“诗酒趁年华”的精神确实必不可少。在制作龙井虾仁之初，制作者要先取来一撮新鲜龙井茶按照饮用标准泡好，静置一段时间，然后分离出茶汤与茶叶。接下来取新鲜河虾一盘，去皮去肠，洗净，再加入淀粉、盐、鸡蛋清抓匀，腌制一段时间。待龙井和虾仁都处理好，热一锅油，油温四成热时将虾仁倒入油锅，迅速用铲子划散，等虾仁泛白后立即起锅，沥去锅中余油，再倒入剩余的茶汤、绍酒，翻炒均匀即可出锅，成盘时记得用茶叶进行点缀。如此做出的虾仁既保留着当季河鲜的鲜甜，又洋溢着龙井的香气，不仅味美，青白相间的外观也相当可人，真是将食材美好的一面都呈现到了极致。"
  },
  [166] = {
    order = 166,
    id = 529,
    desc = "亚巴顿",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "月见",
    cv1 = "加藤英美里",
    desc = "她是来自星星的旅行者。在地球上，被赋予了“毁灭者”之名。虽然有着骇人的外号，她的兴趣也只是按照个人的喜好改造周围。并且会因为自己的审美洁癖，将不符合自己品味的东西轻率地丢进无底坑之中。\n偶尔也会因为找不到东西而后悔，但是自己也并没有从无底坑里面取回东西的办法。\n对于自己对别人造成的困扰，则完全没有自觉"
  },
  [167] = {
    order = 167,
    id = 522,
    desc = "西兰花圣诞树沙拉",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "在一年一度的特别之日中，每个人都能享受到的料理，那便是西蓝花沙拉。\n人们为西蓝花的枝叶点缀上色彩缤纷的装饰物，宛如一棵小小的圣诞树一般。西蓝花沙拉虽然是外表包含了绿色、红色、白色、黄色等丰富色彩的料理，制作方法却意外的很简单。将煮好的西兰花插在以土豆沙拉做成的台座上，树的部分便完成了。以此为基础按照喜好点缀上灯笼椒、胡萝卜、小西红柿等食材，不知不觉就变得像是一棵迷你圣诞树的模型了。\n当然，西蓝花沙拉是一道料理，因此仅外表光鲜亮丽是不够的。吃到嘴里后，土豆沙拉和西兰花的搭配自不必说，用作装饰的食材也会成为沙拉的一部分。让人们大饱眼福的同时也能大饱口福，正可谓适合神圣之夜的料理。"
  },
  [168] = {
    order = 168,
    id = 530,
    desc = "艾尔希",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 2,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良",
    cv1 = "染音若蔡",
    desc = "性感又毒舌的迷人小姐姐，像是吸血鬼又无从考证的身份为她增添了诸多神秘感。\n实际上和看起来的调皮温柔这些光明的特点不同，小艾是被原本世界的人放逐到这里的。那个世界的人们无法容忍吸血鬼的存在，于是她被其他吸血鬼保护起来，流落到这个世界。在遇到双子之前，她的生活要么是在流浪，要么是在长眠。\n尊贵而美丽的女孩，拿着一杯鲜艳的红色液体俯首啜饮——这是个很吸血鬼的场景。然而那杯子里面装的却是清甜可口的西瓜汁。你如果问她本人为什么这么做，她只会说：“想要知晓答案的话，那你就永远追随妾身，也许妾身哪天兴致一来就告诉你了呢？”\n小艾有着柔软而明亮的长发，调皮又引人的性格，纤细和玲珑兼备的身体线条。所以某个生性羞涩的白毛少年被她紧紧拥抱的时候，几乎是瞬间红到爆炸。但是即便是这只白狼少年也无法问出小艾的任何过往，也有可能是他没有勇气去问下去。因为每次提到这事，这位小姐姐总会说：“你真的想知道吗？来，离我近一点......再近一点......我会告诉你的。”然后白绒绒就什么都不知道了。\n实际上，吸血鬼的力量是不变的，分享这份力量的人越多，这份力量就越弱小。随着自身能力的不断增长，即便是在这个世界，小艾也已经察觉到一个事实：或许她原本的同伴们都已经不复存在了，她可能已经是这世界上仅存的吸血鬼。好在在这个世界她并非孤身一人，她还有伙伴可以依靠。她温柔的性格还是得到了不少伙伴，即便她的真实身份仿佛一个未解之谜。\n“人类......向我宣誓，永不背叛，永远追随。什么？你不愿意？呵，那你早晚会知道的。事实会告诉你，成为吾之眷属是无上的光荣。”\n虽然是吸血鬼，但这个世界的人们还尚未发现她的危险性。这个似乎很危险的家伙，日常饮用的却是甘甜的西瓜汁，但那也有可能是某种戏法带来的迷幻效果。不过，谁又能查证到底是怎么回事呢？时间或许能证明，或许不能。闹不好最后根本没人在意这件事了。毕竟——小艾就是正义☆~"
  },
  [169] = {
    order = 169,
    id = 521,
    desc = "约克郡布丁",
    open = 1,
    atkSpeed = 4,
    hp = 3,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "约克郡布丁是英国约克郡地区的料理，作为烤牛肉的配菜而出名。\n因为约克郡布丁的名字，很多人会联想到布丁，但其实是完全不同的东西。外观和奶油泡芙声很像。里面不会加入奶油之类的。味道鲜美，松软可口。大多作为肉菜的配菜搭配，蘸着肉的酱汁吃也非常美味。很适合搭配鹰嘴豆沙酱或肉酱。\n因为在英国约克郡布丁是普通的家庭料理，所以也有着“如果能做出美味的约克郡布丁，出嫁的准备就万事大吉了!”的说法。\n在英国的家庭中，被称为“圣代烤香肠”的香肠配上约克郡布丁，是周日午餐和晚餐中必不可少的料理。\n制作方法是，将面粉、鸡蛋、盐、牛奶、水做成的面糊倒入约克郡布丁的模具中，放入烤箱烤熟。朴素的料理虽然简单但是非常的好吃。在美国有一种类似于约克郡布丁，被称为“pop - up”的料理，但那个是淋上果酱之类的作为甜点食用。"
  },
  [170] = {
    order = 170,
    id = 531,
    desc = "魔菇",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良&十七喵&酸奶",
    cv1 = "貔貅肛",
    desc = "作为菌种之王，在既有生命又有灵性的空间中，魔菇无处不在。她在每个空间留下自己的种子，脉络遍布各个次元。伴随着她的是一把绝不离手的蘑菇伞，无论是阴晴还是白夜都会带着它。\n利用次元息洞，魔菇展示了她的穿越艺术，它破坏了时空的连续性，模糊了领域现实之间的界限。蘑菇种子也会跨过时间与空间的界限互相感应。\n最开始魔菇生长于一片无人造访的森林中。她对世界的认知仅局限于下雨还是晴天。可是后来她渐渐能感受到小鸟在附近的树上振翅飞翔，听到某朵野花的绽放，甚至可以触摸路过的动物——她不再是一朵单纯的蘑菇，她能接触到的一切说明她已经已经得到了全新的生命。\n频繁往来于不同的空间，自身的存在却丝毫不受影响。魔菇的特性一直是各个科研组的研究热点，可是却没有哪个组织敢去直接把她抓来，最多趁她心情好的时候问问。除却她自身行踪飘忽不定以外，还有一个重要原因。要知道，谁也不想被她手里那把蘑菇伞爆头，这绝对会是一生一次的体验，因为体验完了，人生也就结束了。\n作为一个悠闲旅行的少女，她的时间不仅来源于漫长的生命，更来源于她处理事情时超高的效率——时间不是挤出来的，而是省下来的喔。\n虽然脾气很坏，但却极少做出伤害他人的事情。更多时候都是懒洋洋的躺在舒适的地方，或者撑起那把蘑菇伞打瞌睡，做一个安静的美少女。"
  },
  [171] = {
    order = 171,
    id = 533,
    desc = "狐弥",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良&酸奶&Boom",
    cv1 = "刘晴",
    desc = "纯粹感性的小狐狸，非常容易受到情绪感染。和狐渠本为一体同心，分开的理由目前不明。\n看起来是步入青春期，实际上脾气也吻合这个状态。有种初生牛犊专属的顽劣和固执，稍稍挑唆就会爆炸，大吵大闹或者嚎啕大哭都是常见现象。\n周围人习惯了她之前的暴躁，没想到随着成长，她的性格却又知性起来。不再像之前那样暴躁，但是仍旧很容易哭泣。只要周围人稍稍有些不幸，她就会泣不成声。\n和狐渠是由完整的个体分裂而来，为此她的两只眼睛颜色是不一样的。那么问题来了，最开始的那个人到底是什么颜色的眼睛呢？\n心跳加速的感觉是不是人人都爱！只计较利益得失岂不是很没劲吗~~来做些超爽超嗨的事情吧！\n作为纯粹的以“情绪”构成的个体，她的情绪变化速度比果冻币花掉的速度还快。稍有风吹草动，她的情绪就会完全颠倒。但是能真诚的因他人的不幸而难过，又能真诚的因为他人的幸运而快乐，并不仅仅止于表面的附和，这在任何世界都是个难得的品质。\n“我们终究会再度重逢，为了不让悲伤的现实玷污美丽的梦。”"
  },
  [172] = {
    order = 172,
    id = 534,
    desc = "舒儿",
    open = 1,
    atkSpeed = 4,
    hp = 3,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "朝露",
    cv1 = "長縄まりあ",
    desc = "出生在提斯诺姆的官僚大家庭里，是这个世界少见的富贵人家。\n作为这样家庭的孩子本应该是养尊处优，但是他和姐姐玛尼是完全相反的性格，刁蛮任性，我行我素。\n曾经非常粘着姐姐玛尼，但是在家庭变故之后，眼见着离开的玛尼变得疏远、不通人情，舒儿也决心改变了自己的性格。\n如今，她仍旧自我，还变得势利，刻薄，但是也显露出了与外表严重不符的成熟与坚强。\n在仅有自己与仆人诺特两人的情况下，建立了拾荒队，目标是用自己的方式击破玛尼那不切实际的幻想。\n\n被人们称为“洛伦兹家的红蔷薇”的拾荒者，因为荒原之上几乎没人没见识过她那与外表不符的战斗力。\n极度爱钱，不择手段，给匪徒提供武器，或者囤积饥荒地区的物资，让她在荒原上留了不少恶名。\n然而实际情况是，给匪徒的武器，是有消灭魔物的条件在先；囤积饥荒地区的物资，是为了高价卖给黑市商人，再低价为难民送出另一半。\n“当然要赚黑市商人的钱了，你不会愚蠢到认为难民的身上还有钱赚吧？而把剩下的物资送给他们，是为了让黑市商人没有钱赚，交出那里的市场啊。”\n用别扭的方式维护着自己周围的世界，这就是让成年人们都畏惧三分的红蔷薇。"
  },
  [173] = {
    order = 173,
    id = 535,
    desc = "泡椒凤爪",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "泡椒凤爪属川菜小吃类，是起源于重庆的民间独特美食。以酸辣爽口、皮韧肉香而著称。泡椒凤爪既能登大雅之堂，也为普通老百姓所喜爱。此款美食具有开胃生津、促进血液循环的功效。\n凤爪——即料理界鸡爪的美称。这个在西方大家都弃之不食的部位，却因为风味独特，且易于入味，啃食起来别具一番体验，从而被中华大陆上的有才华的主厨们发现。而泡椒凤爪则是这许多凤爪料理中颇具特色的一种……\n在四川，民间非常流行泡椒凤爪。几乎每一个风味卤菜拌菜店具有自制泡椒凤爪出售。尤其以老坛泡菜水泡出的凤爪最为鲜美入味。\n不过要小心哦，因为这道诞生在川地的料理，辣味可是相当强烈的哦……"
  },
  [174] = {
    order = 174,
    id = 538,
    desc = "Yamato",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 1,
    hit = 4,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "拿铁",
    cv1 = "暂无",
    desc = "Yamato，在料理次元中可以算是异类的存在。\n她并非是食灵，也并不诞生于料理次元。\n她来自另一个遥远时空，那儿可以称得上故乡的地方里，有着湛蓝的海，明媚的风光，而她曾经有着同伴，是她们的首领，后来……\n总而言之，那已经是过去的事了，来到了这里的她，正在努力习惯料理次元的生活。\n也许无法感受清凉的海风，但是可以尝到章鱼丸子，也许无法看到深海的大海，但是可以尝到海燕汽水……更重要的是，她感觉到了主厨纯粹的热爱、食灵们坚固的羁绊。\n是的，尽管外表让人觉得难以接近，实际上的她依旧渴望着——那些东西，被深海噩梦困扰的她不会承认的东西。\n但主厨很自信，她迟早会承认的，因为那些东西，她已经拥有了。"
  },
  [175] = {
    order = 175,
    id = 539,
    desc = "臭豆腐",
    open = 1,
    atkSpeed = 4,
    hp = 3,
    atk = 4,
    phyDef = 3,
    hit = 4,
    miss = 3,
    growth = 4,
    skill = 5,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "臭豆腐是中国传统特色小吃之一，具有“闻起来臭、吃起来香”的特点。在各地的制作方式、食用方法均有相当大的差异，有北方和南方的不同类型，臭豆腐在南方又称臭干子。其名虽俗气，却外陋内秀、平中见奇、源远流长，是一种极具特色的中华传统小吃，古老而传统，令人欲罢不能。                        制作材料有大豆、豆豉、碳酸钠等。以优质黄豆为原料。制作工艺较为复杂，黄豆经过筛选、脱壳、浸泡、磨浆、过滤、煮浆、点浆、成型、划块、发酵十道工序。呈贡臭豆腐质地软滑，散发异香。先人赞誉云：“味之有余美，玉食勿与传”。                                         臭豆腐不仅有很高的营养价值，而且有较好的药用价值。古医书记载，臭豆腐可以寒中益气，和脾胃，消胀痛，清热散血，下大肠浊气。常食者，能增强体质，健美肌肤。                                  另外臭豆腐在中国以及世界各地的制作方式和食用方式均存在地区上的差异，其味道也差异甚大。长沙和南京的臭豆腐相当闻名，台湾、浙江、上海、北京、武汉、玉林等地的臭豆腐也颇有名气~"
  },
  [176] = {
    order = 176,
    id = 532,
    desc = "黄金凤尾虾",
    open = 1,
    atkSpeed = 4,
    hp = 5,
    atk = 5,
    phyDef = 2,
    hit = 6,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "黄金凤尾虾，这个经常在西洋快餐店和家庭餐厅看到的特别小吃其实和瑞士鸡翅一样，都是看似来自国外，而事实上却是土生土长的中华料理。\n黄金凤尾虾是汉族的传统名菜,起源于江苏南京市，属金陵菜。因为装盘后每只虾都披着金色的外衣，却有鲜红的尾壳,形似凤尾,色彩艳丽,故此得名。\n这道小吃的烹饪方法也十分容易，就像做炸鸡翅一样，为处理好的虾裹上淀粉，蛋液，面包糠，接着下锅炸即可。鲜嫩的虾味配上酥脆的金色外衣，虽然简单，却别样的可口。\n现在的黄金凤尾虾经常出现在某些套餐的小食拼盘里，搭配的酱料种类也越来越丰富，无论是千岛酱，沙拉酱，番茄酱，还是韩式辣酱，这些各式各样，诞生地不同的酱料总能让这道小吃展现出不同的风味和魅力来，只是，很多人也许都不知道她也是在中华大陆诞生的吧"
  },
  [177] = {
    order = 177,
    id = 536,
    desc = "油条",
    open = 1,
    atkSpeed = 4,
    hp = 4,
    atk = 5,
    phyDef = 2,
    hit = 4,
    miss = 4,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "油条，有的地方也叫馃子，是一种古老的汉族面食，长条形中空的油炸食品，口感松脆有韧劲，中国传统的早点之一。\n早在南北朝时期，北魏农学家贾思勰在其所著的《齐民要术》中，就记录了油炸食品的制作方法。“细环饼，一名寒具，翠美”。唐朝时期，诗人刘禹锡在《佳话》中也提及寒具。《苕溪渔隐丛话》中提到：东坡于饮食，作诗赋以写之，往往皆臻其妙，如《老饕赋》、《豆粥诗》是也。又《寒具诗》云：‘纤手搓来玉数寻，碧油煎出嫩黄深，夜来春睡无轻重，压褊佳人缠臂金。’寒具乃捻头也，出刘禹锡《佳话》。”然而这种叫“寒具”的食物应该形似女子佩戴的缠臂金，类似撒子，并非油条。油条应是南宋以后对油炸面食的又一创新。\n关于油条，还有一个最脍炙人口的故事：据说油条本名叫“油炸桧”，这还要追溯到南宋时期那段令人叹息的历史：当年抗金名将岳飞由于宰相秦桧及其妻子的迫害，于风波亭被捕，最终惨死。一代英雄就这样陨落在小人手中。百姓们对这对奸臣夫妇恨之入骨，便把秦桧夫妇的面人扭在一起，下入油锅烹炸，以解心头之恨。本来老百姓当初吃“油炸桧”就是为了解恨，可一吃又觉得酥脆可口，价钱也便宜，所以吃的人就越来越多，一时间临安城里城外所有和烧饼摊，都学着做起来。慢慢的，这道美食就传遍了全国各地。尽管如此，那股承载着英雄精神与民族气节的执念却早已在这道料理中悄悄的凝聚……\n直到现在，那昏君佞臣依旧阴魂不散。它们化成两条凶狠的蟒蛇，盘旋在油条的食灵身后，好像还在酝酿着什么不为人知的隐谋呢。"
  },
  [178] = {
    order = 178,
    id = 537,
    desc = "黄桃罐头",
    open = 1,
    atkSpeed = 4,
    hp = 4,
    atk = 6,
    phyDef = 2,
    hit = 5,
    miss = 4,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "　“黄桃呀小黄桃，圆小小，真可爱，皮儿薄，果又甜，轻轻咬，水噗噗~”作为家喻户晓的水果罐头之一，这一首首童谣足以证实黄桃罐头在人们心中的地位之高了，而在其中的学问可不见少，就黄桃而言，黄桃又称黄肉桃，属于蔷薇科桃属，因肉为黄色而得名。黄桃的营养十分丰富，含有丰富的维生素C和大量的人体所需要的纤维素、胡萝卜素、番茄黄素、红素及多种微量元素。黄桃食时软中带硬，甜多酸少，有香气、水分中等，成熟糖度14~15度。而对其的选择上，则需果块大小、色泽一致，糖水透明，或有少量果肉碎屑，富含补充维生素C，人体所需纤维素、胡萝卜素等。黄桃罐头一般可以开盖即食，也可以高温加热食用。炎热的夏天，将黄桃罐头放入冰箱内冷藏后，口味更佳哦~"
  },
  [179] = {
    order = 179,
    id = 540,
    desc = "纳豆白子",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "朝露",
    cv1 = "暂无",
    desc = "纳豆，起源于中国古代，自秦汉（公元前221年-公元220年）以来开始制作，由黄豆通过纳豆菌（枯草杆菌）发酵制成豆制品，具有黏性，气味较臭，味道微甜，不仅保有黄豆的营养价值、富含维生素K2、提高蛋白质的消化吸收率，更重要的是发酵过程产生了多种生理活性物质，具有溶解体内纤维蛋白及其他调节生理机能的保健作用。白子也就是鱼类的精巢，日本人视之为美味。较常见的有河豚、鳕鱼的等，烹调方法多为刺身、火锅、烧烤。 因含有丰富的蛋白质所以被奉为补身极品。而纳豆白子则是由这两者结合制成的黑暗料理。"
  },
  [180] = {
    order = 180,
    id = 541,
    desc = "鲱鱼沙拉",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "朝露",
    cv1 = "暂无",
    desc = "鲱鱼沙拉，之所以冠以黑暗料理称号，因为有黑暗三重冲击，视觉冲击：层层堆叠的食材如「人体解剖标本」，鲱鱼丁与甜菜丝的紫红色泽在烛光下宛如凝固的血迹。嗅觉陷阱??：未发酵鲱鱼仍带海腥，混合洋葱醋汁的酸腐味，形成「穷酸味觉矩阵。味觉凌迟?：第一口是蛋黄酱的甜腻，第二口鲱鱼的咸腥反扑，第三口甜菜的土涩将味蕾拖入深渊\n传说沙皇亚历山大三世加冕宴上，御厨为讽刺贵族奢靡，用鲱鱼象征底层劳工，红菜头代表革命者，土豆象征农民，以「食物阶级化」的黑色幽默化解宫廷矛盾。该事件被记载于《厨师的修为》，成为俄罗斯新年宴的雏形。\n莫斯科酒馆老板Anastas Bogomilov为平息醉汉斗殴，将鲱鱼、土豆、红菜头分层填入模具，意外创造出兼具饱腹感与娱乐性的「和平料理」。士兵们戏称其为「联合小菜」，后演变为跨年必吃。\n\"这道菜最可怕之处，在于它用美食的外衣包裹着文明冲突。当你用银叉切开红菜头时，刀锋划过的不仅是食材，更是两个世纪以来的阶级伤痕。\" —— 俄罗斯美食史学家柳德米拉·伊万诺娃"
  },
  [181] = {
    order = 181,
    id = 542,
    desc = "西湖醋鱼",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 1,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "朝露",
    cv1 = "暂无",
    desc = "西湖醋鱼，又名\"叔嫂传珍\"，是源自浙江杭州的千年传统名菜，为浙菜系最具代表性的经典之作。这道菜以西湖特产的草鱼为主料，经精准的刀工处理与火候掌控，呈现出色泽红亮、肉质鲜嫩的独特风味。其精髓在于恰到好处的糖醋配比——入口时醋香扑鼻，细品时酸甜交融，回味时鲜嫩如蟹肉，形成层次丰富的味觉体验。\n\n传说此菜源于南宋时期，与\"叔嫂传珍\"的民间故事密切相关：一位宋嫂为小叔烹鱼治病，独创醋溜之法，后传入宫廷成为御膳。历经八百余年的传承与改良，西湖醋鱼既保留了古法烹制的精髓，又融合了现代健康理念，将油炸改为清蒸，更凸显鱼肉的鲜嫩本味。\n\n西湖醋鱼不仅是舌尖上的美味，更是一张飘香千年的杭州文化名片。这道菜见证了南宋以来江南饮食文化的演变历程，其独特的\"醋香调味法\"开创了中国烹鱼技法的先河，影响了整个江南地区的烹饪体系。在当代，西湖醋鱼作为杭帮菜的标志性作品，既是寻常百姓家宴客的诚意之选，也是高端宴席中的压轴大菜。其制作技艺已被列入非物质文化遗产保护名录，代表着杭帮菜烹饪技艺的最高境界。如今，这道承载着历史与创新的经典名菜，正以其\"酸中带甜、甜中藏鲜\"的独特哲学，向世人讲述着杭州这座千年古城的饮食智慧和生活美学。"
  },
  [182] = {
    order = 182,
    id = 601,
    desc = "奶油蘑菇汤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 2,
    skill = 2,
    formation = 1,
    painter = "谷梁顿Grain",
    cv1 = "雨宫夕夏",
    desc = "欧美非常常见的一种奶油汤。\n以奶油为底料，加入蘑菇，牛油，牛奶等煮成。\n在上古时期的意大利和法国，以有以奶油为基础的酱汁，而以其为基底的奶油蘑菇汤，也已诞生数百年之久。\n奶油汤因为其历史悠久，欧洲有各种材料的奶油汤，如花菜奶油汤，西红柿奶油汤等。奶油蘑菇汤只是其中一种。\n之所以奶油蘑菇汤的认知度要高于其他奶油汤，除了因为本身就是非常常见的组合外，主要是因为美国开发出的罐头奶油蘑菇汤，以及快餐店的大量采用。"
  },
  [183] = {
    order = 183,
    id = 605,
    desc = "珍珠奶茶",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 2,
    skill = 3,
    formation = 1,
    painter = "teeth",
    cv1 = "暂无",
    desc = "珍珠奶茶，是在奶茶中加入木薯粉圆的甜味饮品，台湾最具代表性的小吃之一。\n对粉圆的处理方法会直接影响珍珠奶茶的口感，因此需要十分慎重。煮粉圆时，必须等待热水滚开后下锅，否则木薯粉会融化。接着中火烹煮十五至二十分钟，期间持续用滤勺搅动。时间到后盖上锅盖，熄火，再焖十五分钟左右。焖后捞出，过凉水，最后再加入糖浆浸泡，这样才算完成。\n做好的粉圆既软又富有弹性，还带着一股甜味，为浓郁的奶茶增添了爽滑口感，在青少年人群中非常受欢迎。"
  },
  [184] = {
    order = 184,
    id = 607,
    desc = "酸梅汤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 3,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 2,
    skill = 4,
    formation = 2,
    painter = "浊凉",
    cv1 = "金子彩花",
    desc = "酸梅汤是老北京传统的消暑饮料，口感清凉甜美，还具有一定调养、保健作用，是夏季不可多得的解渴沁饮。\n酸梅汤的历史十分悠久，初唐医典著作《千金翼方》就有了“乌梅汤”的记载；南宋时期，还出现了用焙干的乌梅肉、生姜、甘草、砂糖捣成细粉，拌匀储存的酸梅粉。而酸梅汤真正流行起来，是在清朝的时候。满族入关后，达官贵族忍受不了北京夏季的酷暑，宫廷的御厨便用乌梅煮汤，解暑开胃，深得皇亲贵族喜爱。后来，酸梅汤的制作流向民间，成为百姓们的解暑饮料。\n常见的做法是，将乌梅、山楂、甘草放入锅中煮开，再转小火熬制四十分钟左右，最后加入冰糖调整味道。\n酸爽解腻、降脂降压、清热去火、益气润肺，因为技术的进步，如今酸梅汤已经是一年四季都很常见的饮品，沉郁典雅的色泽成为了中国人心中亘古不变的符号。"
  },
  [185] = {
    order = 185,
    id = 602,
    desc = "蓝色玛格丽特",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 4,
    painter = "Asrid",
    cv1 = "三宅晴佳",
    desc = "或叫蓝色玛格丽塔，优雅的蓝色鸡尾酒。\n玛格丽特是一种鸡尾酒，除了蓝色之外根据配方的微调，有各种各样的颜色。\n玛格丽特以龙舌兰酒、柠檬汁和君度橙皮酒等成分兑成的，其杯口上通常粘有一层细盐。\n蓝色玛格丽特在1949年入选全美鸡尾酒大赛，创造者是简·杜雷萨。\n1926年，杜雷萨去墨西哥，与玛格丽特相恋，墨西哥成了他们的浪漫之地。然而，有一次当两人去野外打猎时，玛格丽特中了流弹，最后倒在恋人杜雷萨的怀中，永远离开了。\n简·杜雷萨为了纪念过世的恋人，而把这种鸡尾酒冠上逝去恋人的名字。"
  },
  [186] = {
    order = 186,
    id = 603,
    desc = "罗宋汤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 3,
    painter = "sola",
    cv1 = "井上麻里奈",
    desc = "罗宋汤是发源于乌克兰的一种浓菜汤。\n原本叫做红菜汤，以甜菜作为主料，所以颜色呈紫红色，辣中带酸，配以大列巴佐食，在俄罗斯、波兰等东欧国家广为流传，在过去是东欧和中欧人的主要食物之一。\n在十月革命时期，红菜汤传入中国，旧上海的文人便给它起名为“罗宋”，意思是罗宋人（俄罗斯人）喝的汤。但这种酸辣味的汤，口味偏甜的上海人并不习惯，后来受地域材料限制和本地口味的影响，在中国本土化后形成了主料为西红柿酱的酸甜罗宋汤，颜色也由紫红变成了橙色，甚至还出现了卷心菜做的绿色罗宋汤。\n自此，国内罗宋汤的口味由俄式红菜汤的酸辣，变化为上海式的酸甜，成为了独具海派特色的料理。"
  },
  [187] = {
    order = 187,
    id = 606,
    desc = "紫菜蛋花汤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 1,
    painter = "哈路卡",
    cv1 = "岭内ともみ",
    desc = "中国各地都非常常见的餐后汤。\n将紫菜，打好的鸡蛋，盐，味精等加入热水中煮成。\n \n紫菜蛋花汤是中国非常常见的汤饮，任何地区都可以见到。\n紫菜和鸡蛋，都是营养价值都很高的食材，且中国都使用至少千年以上。中国又是鸡蛋和紫菜的最大生产国，因此这些食材也非常廉价。\n因为其廉价而又有高营养价值，所以成为了各种大众食堂，院校等地的常驻菜式。\n但如此常见且有名的汤品，菜谱以外的信息却非常之少，关于紫菜蛋花汤的历史和起源的记载并不多。\n \n紫菜蛋花汤不但在中国很普及，在国外也具有代表性，在外国的中餐馆中，紫菜蛋花汤也是被提供的主要汤品之一。是极其便利又百搭的汤品。"
  },
  [188] = {
    order = 188,
    id = 609,
    desc = "摩卡咖啡",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 5,
    painter = "—PHI—",
    cv1 = "岩山ちひろ",
    desc = "加入巧克力的咖啡饮品。\n将浓缩咖啡，巧克力浆，牛奶混合而成。\n摩卡咖啡有时会用白巧克力或混合巧克力加入咖啡中，使摩卡咖啡产生出很多新的变种，例如“白摩卡咖啡”、“燕尾服摩卡”、“斑马摩卡咖啡等”。\n摩卡咖啡的原意指的是红海海边的也门小镇摩卡产的咖啡。那里产的咖啡豆有像可可豆一样的风味。现代泛指的“摩卡咖啡”就是通过在咖啡中加入巧克力的方式，来还原摩卡小镇产的咖啡的味道。\n虽然现代摩卡咖啡已经不仅仅指也门摩卡产的咖啡，作为调和基底的咖啡也是意式特浓咖啡，但是在咖啡中加入巧克力而酝酿出的风味，还是能让人联想到红海的风情。"
  },
  [189] = {
    order = 189,
    id = 610,
    desc = "拿铁咖啡",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 5,
    painter = "拿铁",
    cv1 = "佳村遥",
    desc = "拿铁，是意大利语“Latte”的译音，原意指牛奶。顾名思义，拿铁咖啡是牛奶与咖啡混合的花式咖啡。\n虽然是咖啡的一种，但是在一杯拿铁咖啡中，占多数的却是牛奶。拿铁咖啡中的咖啡指的是意式浓缩咖啡 espresso，与牛奶的比例一般控制在 1:1.5 。\n制作方法并不复杂，在刚做好的意式浓缩咖啡中加入接近沸腾的牛奶即可。有心的话，可以在咖啡的顶端加上一些奶泡，那是咖啡师展现拉花手艺的地方。\n\n值得一提的是，在一些地区，会用拿铁作为拿铁咖啡的简称，很容易造成概念的混淆。严格上讲，拿铁只指代牛奶，同样，抹茶拿铁也指的是抹茶牛奶。所以，如果遇见在咖啡店点了一杯拿铁，却送上来牛奶的情况，请不要惊讶~"
  },
  [190] = {
    order = 190,
    id = 622,
    desc = "五味子花茶",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 3,
    skill = 3,
    formation = 3,
    painter = "EB十",
    cv1 = "暂无",
    desc = "五味子花茶，又被称作是五味子花菜，它是一种来自韩国的消夏饮品。其主料自然是五味子，这种红润而娇小的果实具有强烈而独特的酸味，但与此同时又具有甜、苦、辣、咸四味，故得名五味子，将其制成饮品饮用的话五味子强烈而丰富的味道会充分刺激味蕾，从而起到解渴、解乏、唤起身心的功效，它能够有效地缓解暑天高热给人们带来的身体压力。\n五味子花茶的做法非常简单，人们在家中就可以轻易制作，需要准备到的食材仅仅有五味子、蜂蜜、梨、松子，也可以根据个人喜好适当替换或加入其他辅料。具体的制作方法可分成三步：第一步，将五味子洗净、筛干，放入凉白开中浸泡半天左右，其后用棉布筛去五味子残渣制成五味子水；第二步，将松子去壳，清洗干净，再将梨等水果洗净、切开，利用水果刀或模具将其加工成花型或者者星型等美观的形状；第三步，在五味子水中加入三大勺白塘和两大勺蜂蜜、搅拌均匀，其后再撒上处理好的梨片与松子——于是，有着鲜艳色彩和奇特香味的五味子花茶便大功告成了。传统的五味子花茶是保持着常温直接饮用的，不过若是追求新鲜与口感的话不妨先冰镇一下五味子水，冰冰的茶水与刺激的酸味想必会带来更棒的味觉体验哦？"
  },
  [191] = {
    order = 191,
    id = 604,
    desc = "海洋之星酒冻",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 5,
    formation = 3,
    painter = "仙女vv",
    cv1 = "武田罗梨沙多胡",
    desc = "海洋之星酒冻是一种以朗姆酒为基调的鸡尾酒酒冻。\n以蓝玫瑰味朗姆预调酒、琼脂、柠檬为原料调制而成。\n因为是以朗姆酒（酒精浓度38%-50%）为基调，所以是即使是类似果冻的东西，但是酒精浓度还是相当之高。\n根据加入的水的量，海洋之星酒冻可以做成很稀的液体或者很有弹性的固体状，因此也有类似甜品的一面。\n酒冻的制造法出现最早可以追溯到1868年Jerry Thomas出版的书\"How to Mix Drinks, or The Bon Vivant's Companion\"\n而后在北美地区出现的商品“Jell-O”则让酒冻的制作变得非常简单，任何有兴趣的人都可以轻易地制作出自己喜欢的酒冻。"
  },
  [192] = {
    order = 192,
    id = 611,
    desc = "香槟",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 2,
    painter = "时辰",
    cv1 = "种田梨沙",
    desc = "“当我快乐时我喝香槟，悲伤时也喝它，有时独处时也喝它，当我有朋友时当然要喝香槟，不饿的时候我会小口喝，饿了就好好来一杯。除此之外，我不碰香槟——除非我渴了。”——首席法兰西香槟创始人莉莉·伯那吉。\n只有在法国香槟区，选用指定的葡萄品种，根据指定的生产方法流程所酿造的起泡酒，才可标注为香槟（Champagne）。创造出它的人是谁不得而知，但有记载在1668年，传说中的“香槟之父”唐·佩里侬修士始终为酿出的酒中含有气泡而烦恼，认为这种带气泡的酒是瑕疵。他用了十五年时间研究如何阻止气泡产生，最终虽然失败，但他在研究过程中对不同品种的葡萄根据品质择优混酿，却意外对香槟的出生做出了巨大贡献。\n直到十七世纪末至十八世纪初，有位修道院的酒窖管理员第一个使用了“再发酵液”，主动利用了再发酵液引起葡萄酒在瓶中的二次发酵，酿造出了香槟的原型。1729年，法国香槟省出现了第一家登记在案的香槟生产商“Ruinart”，自此香槟开始征服欧洲各大贵族。\n自此之后，不管是国王加冕还是新船下水，就连生日、婚礼、庆典，都少不了香槟的存在。泡沫丰富、色泽金黄的香槟，已经成为了人们心中胜利和期望成功的象征。"
  },
  [193] = {
    order = 193,
    id = 614,
    desc = "马赛鱼汤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 1,
    formation = 1,
    painter = "ジャック",
    cv1 = "暂无",
    desc = "马赛鱼汤是来自法国的著名料理，顾名思义，最初是在马赛诞生。马赛是人口仅次于巴黎的法国第二大城市，也是法国最大的海港。那里的渔民们在出海归来后，会对收获的海产进行筛选。除去卖相较好的品种后，留下鱼骨较多、口感一般的小鱼，还有各种无名的虾与蟹，将它们放在锅中一起炖烂，加上蒜味面包和辣味蛋黄酱后，就成了最初的马赛鱼汤。后来，马赛在 19 世纪成为重要的商业港口，当地的许多料理开始进入上流社会，马赛鱼汤这道实惠简单的平民料理也摇身一变，成为了如今奢华复杂、闻名世界的海鲜炖菜。\n关于马赛鱼汤中的食材，一直是众说纷纭。正统主义者认为，马赛鱼汤中至少要有四种从地中海出产的鱼类，比如岩鱼、海鳗、红体绿鳍鱼、鲭鱼，并且这些鱼类必须和新鲜西红柿、土豆、茴香一起炖煮，才能算是真正的马赛鱼汤。而在 1980 年，马赛的厨师们又制定了含有少许不同的标准，并将这份标准称为《马赛鱼汤宪章》。在这份“宪章”中规定，马赛鱼汤的食材必须是马赛近海捕捉的鱼，且最少四种以上入菜，比如刺丝鳍鱼、安康鱼、海鲂、石头鱼等。“宪章”还规定，鲷鱼、比目鱼、龙虾、章鱼、乌贼一律不能入菜。从食材上就可以想象得到，作为一款海鲜杂烩料理，马赛鱼汤除了有酸辣与香料味，还有极其浓烈的海鲜香气。对全世界热爱海鲜的人来说，马赛鱼汤中浓缩了足够的地中海精华，是一辈子必须去吃一次的顶级美食之一。"
  },
  [194] = {
    order = 194,
    id = 615,
    desc = "金酒",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 4,
    skill = 5,
    formation = 3,
    painter = "红茶菌",
    cv1 = "暂无",
    desc = "金酒，也被称为杜松子酒，是在荷兰发明出来，在英国发扬光大的一种著名烈酒。\n起初，金酒被制造出来是为了帮助在东印度地区活动的荷兰商人、海员和移民预防热带疟疾病，作为清热的药剂使用。这是因为金酒的主要材料——杜松子是一种古老的解毒剂。在埃及和欧洲的早期文献中，都有焚烧杜松子来抗菌、预防流行病传染的记录。除去药用价值，杜松子特有的松脂香味也让它作为常用的调味品在西方流行。用杜松子制作的金酒，香气浓郁、酒体洁净，发明不久后就被人们作为正式的酒精饮料饮用。\n金酒的酒精浓度在 45% 左右，无色透明，近百年来都是调制鸡尾酒时最常使用的基酒，其配方多达千种以上，因而被赐予了“鸡尾酒心脏”的美称。“修道院”、“百慕大”、“红粉佳人”，原本颇为小众的金酒，随着鸡尾酒的蓬勃发展，慢慢蜚声国际。\n在金酒的故乡荷兰，人们叫它 Jenever，意思是让人有活力、恢复元气，现在的它已然成为国家的象征之一，有专门的博物馆“波士鸡尾酒之家”来展示其多彩的历史。"
  },
  [195] = {
    order = 195,
    id = 618,
    desc = "水正果",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "inxst",
    cv1 = "暂无",
    desc = "水正果，又名柿饼茶，是一种发源于韩国的茶类饮品。\n正如其别名，水正果的主料便是柿子。从养生保健的角度来讲，新鲜的柿子是偏向于湿寒性质的食物，可以化解秋风带来的燥热，不过它却并不适合湿气较大、脾胃虚寒的的人直接食用——为此、为了让更多人能享受柿子的美味，人们发明出了将柿子置于阳光下晒干，挥发掉多余的寒性制成“柿饼”的料理方法，由此将其转化为一种健脾补胃的健康食品。而为了更进一步地发挥柿子的神奇功效、去除过度食用柿饼所带来的消化不良等不适症状，在加入暖性的肉桂、生姜等辅料一起煮制之后，所谓的“水正果”便诞生了。\n这款饮品最大魅力就在于“和谐”二字，柿子的甜蜜与桂皮微苦混合，带来了富有回味的口感，而温性的桂皮生姜与寒性的柿子达成统一，即可以清热解毒，也可以缓解寒症状，它被认为能够祛痰止咳、提高免疫力，适于容易咳嗽、口舌生疮的人饮用，而一般人饮用水正果也可以达到滋阴润肺，补水养颜，活化血管的效果。总而言之，这是一种适合人们多多品尝的美味养生饮品。"
  },
  [196] = {
    order = 196,
    id = 619,
    desc = "铁观音",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 4,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 4,
    skill = 4,
    formation = 4,
    painter = "—PHI—",
    cv1 = "暂无",
    desc = "铁观音，中国“十大名茶”之一的传统名茶，是一种介于绿茶与红茶之间的半发酵茶。人类饮茶历史悠久，中华的饮茶文化更是博大精深，而铁观音凭借其独特的“观音韵”傲立于众多的珍茗之间。\n所谓的观音韵是指铁观音所散发出的独一无二的香气，相传铁观音的香味时而强、时而弱、时而酸、时而甜、时而霸气夺人、时而温文尔雅，恰似人生百态，其妙处只能意会，不能言传，正可谓“品茶如品人。品观音韵，同品其他名茶一样，通常讲究审茶、观茶、品茶三道程序——首先是审，即去看干茶的色泽，内行人从干茶茶色中便可看出茶叶的种类与质量；其后是观，待茶叶入水，干茶吸足水分慢慢伸展，几乎会回复到自然的状态，而此时汤水沾染上茶叶的眼色，由浅入深，令人赏心悦目；最后的一步便是最为直接的品，品汤味、闻茶香，好茶叶不仅仅闻着香、入口香，它的气味又会给茶杯、茶杯盖、茶渣染上截然不同的香味，犹如乐师轻轻拨动琴弦后产生出高低不同的音色，最终汇聚为一曲仙乐。"
  },
  [197] = {
    order = 197,
    id = 608,
    desc = "冰糖燕窝",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "MOB",
    cv1 = "岭内ともみ",
    desc = "驰名海外的中国的知名补品。\n将冰糖和燕窝一起炖制而成，之后可以选择冰镇或者直接食用。\n在炖燕窝时，不能够使用太高的温度，因为那样会使燕子的唾液液化，从而丧失独特的口感。\n最高级的燕窝产地在印度尼西亚，马来西亚，泰国等东南亚地区，但食用燕窝这种文化却是发源自中国。\n燕窝在元末明初时被认知到可以食用，而到了清朝，更是被当作和鱼翅、鲍鱼并列的高级食材。\n燕窝在古代往往不仅仅作为料理，而是一种“药膳”被搬上餐桌，燕窝在中医中是一种具有滋阴润邦、美容、增强抵抗力的食材。虽然近年的研究对燕窝的营养价值进行不少反思，但是作为传统的补品，燕窝在亚洲还是有着极高的人气。\n在现代，广州地区仍然非常流行食用燕窝，虽然高价，但其独特美味的口感，仍然俘虏了众多食客的心。"
  },
  [198] = {
    order = 198,
    id = 612,
    desc = "大吟酿",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 4,
    painter = "Mkiiiiii",
    cv1 = "上坂すみれ",
    desc = "日本清酒，根据精米步合程度可分为三个等级，即：本酿造，吟酿和大吟酿。其中被称作大吟酿的，是最高等级的清酒。所以，说到大吟酿，不得不从清酒开始讲起。\n酿制清酒，对纯净、自然的水质要求极高。矿物质较少的软水，酿出的酒口感较为甘甜、柔和、清淡。反之则辛辣、浓郁、醇厚。\n用米方面，酿造清酒的大米品种也与日常食用的大米不同。常见的有山田锦、熊町、五百万石等等，这些米被称为“酒造好适米”。和普通的大米相比，这些大米除了穗粒饱满硕大之外，淀粉的分布也有很大不同。普通大米的淀粉基本均匀分布在米粒中，而酒造好适米的淀粉则是聚集于米心中间部分，在米粒表层的则是油脂与蛋白质，这些成分会极大地影响酒的口感。因此，在加水蒸熟之前，酿酒用的大米会经过研磨，只留下淀粉为主的中心。\n大米研磨后剩下的比例就称为精米步合。比例越高，米香越浓郁；比例越低，则越能够酿出精细、清香、带有花果香气的酒。\n其中，大吟酿的精米步合都低于50%，意味着米的杂质已磨掉五成以上，再用特殊酵母低温发酵，口感会非常细腻，有“清酒之王”的美誉。"
  },
  [199] = {
    order = 199,
    id = 613,
    desc = "冬荫功",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "6音",
    cv1 = "佳村遥",
    desc = "冬荫功，由发音为“Tom Yum Goong”的泰语翻译而来。其中，Tom Yum 是酸辣的意思，Goong 是虾的意思，所以直译的话就是“酸辣虾汤”。\n如直译所述，作为一款开胃菜，冬荫功在酸、辣方面毫不含糊。材料中，负责酸味的是东南亚皱皮柠檬，除了比普通柠檬的味道更加浓郁，还能够有效地去除海鲜的腥气。而负责辣味的泰国朝天椒更是被誉为世界上最辣的辣椒。其他，冬荫功中还会加入鱼露、咖喱、柠檬草、虾酱等多种东南亚风味的调味料，致使最后出锅的味道极尽鲜美浓郁。\n关于冬荫功的起源，传说是在 18 世纪吞武里王朝的泰国，淼运公主受重病影响，食欲不振。郑信王便要求御厨为公主做一道开胃汤。结果公主喝了汤后，通体舒畅，病情减轻——这道神奇的开胃汤就是冬荫功的原型，并被郑信王定为“国汤”。\n作为最传统的泰国料理之一，如今冬荫功已被视作判断一家泰国餐厅是否“好吃”的标志，是货真价实的泰国菜代表。"
  },
  [200] = {
    order = 200,
    id = 616,
    desc = "冬瓜盅",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "咩煲",
    cv1 = "暂无",
    desc = "冬瓜盅是中国广东的十大名菜之一，据传原型是来自于清朝宫廷的菜肴“西瓜盅”。当时的清宫御厨将西瓜一切两半，挖去瓜瓤后倒入鸡汤与食材，连同西瓜皮一起蒸煮，创造出了独特的美味。这一颇具新意的料理方法在之后的官员出访中被传至中国各地，到了盛产冬瓜的广东，就被当地厨师采用，创制出了“冬瓜盅”。\n制作冬瓜盅，需要挑选老而肉厚的冬瓜，先取出瓜内白瓤，再放入开水中煮 10 分钟，目的是为了去除青味。接着在冬瓜内注入高汤，放进焯过水的食材，连同冬瓜一起炖上 1 小时就完成了。\n传统冬瓜盅内的食材，一般会选用：猪肉丁、烧鸭肉丁、田鸡肉、鲜鸭肉丁、蟹肉丁、腌虾仁、鸭肾丁、火腿丁，这八种食材被称为“八宝”，制作而成的冬瓜盅也叫做“八宝冬瓜盅”，是历史最悠久的一种。\n现在，根据人们的不同喜好，冬瓜盅也发展出了新的配方。例如有加鲍鱼、肥蚝、干贝肉、海参等食材的海鲜冬瓜盅、完全由禽肉构成的“百鸟归巢”冬瓜盅、以及纯素菜制作的素食冬瓜盅……虽然做法各不相同，但每一种冬瓜盅都汁多肉嫩、清甜四溢，加上其独特的外形，往往能给人色香味俱全的圆满享受，所以冬瓜盅也被誉为“中国烹饪史上的奇葩，中华民族独步世界食坛的美馔”。"
  },
  [201] = {
    order = 201,
    id = 623,
    desc = "嫩豆腐锅",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "RONOPU",
    cv1 = "暂无",
    desc = "嫩豆腐锅是一道来自韩国的、以豆腐为主料的炖菜。这道菜是用嫩豆腐——这里指未经过过滤、压制的新鲜豆腐，而非是中国的“南豆腐”——与蘑菇、洋葱、蛤蜊或扇贝、虾、牛肉或猪肉以及韩式辣酱制成的。在正式制作嫩豆腐锅的时候我们首先要将豆腐切开、加工成一指厚的豆腐块，然后要将贝肉、虾肉等肉类原材料清洗干净，将肉、洋葱等食材加工成匀称的片状，再取韩式辣酱、盐、糖、鸡精、 酱油等调味料调制酱料。至此，基本的准备工作便完成了，接下来的工作很简单，便是烧热锅子并加水，用大火煮制豆腐2分钟左右，再转中火继续煮5分钟，等到豆腐初步成熟后立即下入酱料与肉类，蔬菜以及青椒，继续焖煮直至食材全部成熟，美味诱人的嫩豆腐锅便大功告成了。"
  },
  [202] = {
    order = 202,
    id = 617,
    desc = "血腥玛丽",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "科学",
    cv1 = "暂无",
    desc = "血腥玛丽是来自于英国的一款经典鸡尾酒，采用伏特加作为基酒，混合以西红柿汁，再添加海盐、辣椒酱、胡椒、辣根等佐料制成。\n关于血腥玛丽这个稍显特别的名字，其实是借鉴于 16 世纪的英格兰女王玛丽一世。这位女王因她强硬的政治、宗教手段而闻名天下。在她带领的英格兰宗教改革期间，有超过三百名新教徒被施以火刑，流亡至国外者更不计其数。后来，不堪其高压统治的人们就以“血腥玛丽”这个称号来称呼女王，流传下来的恐怖传说也五花八门——不过这一切都与鸡尾酒无关，名字只是因它颜色鲜红而产生的联想。\n阅读血腥玛丽的配料就可以想象得到，它是一款酸甜苦辣咸、五味陈杂的鸡尾酒，因为与主流口味大相径庭，所以被很多人评为最难喝的鸡尾酒之一。而对喜欢的人来说，血腥玛丽中有浓厚的西红柿味，辣、甜、苦、咸在入口后层层叠加，最后还能感受到伏特加带来的一股暖流缓缓融进身体，有一杯酒尝尽人生百态之感，让人欲罢不能。\n偏嗜这种体验的人们，一般称血腥玛丽为“喝不醉的西红柿汁”，因为其中西红柿汁的味道能有效地缓解酒精带来的醉感，让人保持清醒。但其实西红柿与酒精二者并不会发生任何化学作用，所以“喝不醉”只是一种说辞而已，对酒精敏感的人还是要量力而行。"
  },
  [203] = {
    order = 203,
    id = 621,
    desc = "冻柠茶",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "catxuan",
    cv1 = "暂无",
    desc = "冻柠茶，源自中国香港茶餐厅的著名茶饮料，它更为人们所熟知的名字是柠檬茶（港式柠檬茶），但与广义上的柠檬+红茶不同，冻柠茶要加入大量糖浆来调味，口感侧重于酸与甜，而且一般都以冷饮为主。在制作过程上冻柠茶也远比“柠檬+红茶”要复杂许多：首先制作者必须精选“茶胆”，即不同种类的茶叶混合、调制、加热处理后得出来用于冲泡的混合茶叶粉末，专业的冻柠茶制作者都拥有只属于自己的茶胆配方，密不外传，这便构成了冻柠茶美味的根本“防线”；在“泡茶”的问题上冻柠茶也有相当的讲究，因为准确地讲冻柠茶并不是被冲泡出来的，而是被煮制出来的。且若要想让茶水清澈不苦涩，在煮制过后制作者还需要用茶兜过滤茶水——用专业的术语来讲，要反复地“拉茶”，这一过程并非是为了滤除杂质，而是为了让混合的茶粉均匀融入水中，从而提升茶水的香气与口感。一般在经过5-8次拉茶后，茶水已变得清透浓香，这时候再将茶水再度蒸煮5分钟，将茶水精制为可用于制作冻柠茶或港式奶茶的茶基后兑入柠檬水、糖浆，充分混合后放置冰箱冷藏。待到壶壁完全冰透，一壶令人爱不释手的冻柠茶便大功告成了。"
  },
  [204] = {
    order = 204,
    id = 624,
    desc = "生啤",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "啤酒有各种各样的做法，但一般指的是将麦芽用啤酒酵母发酵制成的酒精饮料。起源要追溯到公元前美索不达米亚文明时期，将大麦和水混在一起，将其放置后产生的液体便是啤酒的雏形。也就是说啤酒是人们在偶然之下发现的产物。\n被归类为世界闻名的酒类中，其中也有被认为发源地是欧洲圈的。虽说是啤酒，但是根据制作方法的不同，也有淡啤酒（Lager)、爱尔啤酒（Ale）等，它们品种不同，味道也各有差异。生啤酒和啤酒的区别在于是否在制造过程中进行加热和杀菌处理。生啤酒的特征是独特的苦味和浓郁感，同时也带有碳酸滑过喉咙的爽快感。有这么一句话：“完事后来一杯”，作为很多大人在休息时间都很喜欢饮用的饮品，人们对生啤酒的爱已经超越了国界限制。"
  },
  [205] = {
    order = 205,
    id = 627,
    desc = "可乐",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Dimmi",
    cv1 = "暂无",
    desc = "也许是人类历史上最为知名的饮品——可乐。这种传奇的饮料最初是由可乐果与古柯草提取物混合而成的提神药剂，在经历了某个广为人知的意外事件后追加了苏打水这一原料，从而转变成了碳酸饮品。其后它的配方又经历了数代的微小调整，例如去掉了古柯这一易成瘾成份、降低咖啡因、用焦糖色调色……等等，最终转变成了我们现在所熟悉的样子。可以说可乐的核心配方并不是什么秘密，只要拥有材料，谁都可以尝试着做，但若想调和出心仪的味道就只能求助于各家配方了——而这些配方恐怕是现今世界上价值最高的商业机密之一。所以还是赶紧走上街去花三五元钱买上一瓶可乐要更加实际一些。不过在享受它所带来的畅快感之余也请不要忘记，这种导致圣诞老人经典形象诞生的饮品无疑是将工业、商业、文化结合的最为成功的范例，它也一定会在今后极长的一段时光里继续支配年轻人的口味吧。"
  },
  [206] = {
    order = 206,
    id = 620,
    desc = "红茶",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "红茶是将采摘的茶叶发酵、干燥后倒入热水，从而提取出的饮料。红茶的种类有很多，大致可分为三种。\n单一型。只使用了生产地名的茶叶。 \n混合型。由多个产地的茶叶混合而成，红茶制造厂进行混合，可以享受到各种各样的口味。\n调味型。单一型和混合型添加了调味剂后的茶叶的总称。\n红茶在欧洲被广泛饮用。据说世界上喝红茶最多的国家是英国。\n作为英国国民饮料的红茶，一般是做成奶茶来喝。不仅仅是早中晚等吃饭的时候，早上起床后喝，上午或者下午休息时也喝，英国人具有频繁地喝红茶的习惯。\n在英国有建议来客喝茶，客人不能拒绝的规矩。英国有名的所谓午后红茶，是和红茶一起享用点心和小吃的一种习惯。红茶的地位在英国人的日常生活中已经根深蒂固了。"
  },
  [207] = {
    order = 207,
    id = 629,
    desc = "棺材板",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 1,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "电绵羊",
    cv1 = "暂无",
    desc = "棺材板，又称鸡肝版，是一道源自台湾的经典料理。在制作的时候，烹饪者先取鸡肝、鸡肉、豌豆、胡萝卜、土豆与虾仁等食材用高汤进行熬制，待到成熟时加入牛奶、芝士或芡粉等令汤汁变得浓稠，此时再将面包块放入油锅内烹炸制金黄、取出、用小刀挖空内瓤，最后倒入烹饪好的浓汤，盖回上侧面包即大功告成。由此做出的棺材板，被热油焦炸过的面包外表色泽焦亮，颇有松木家具的感觉，而长方形的盖子令人联想到棺材的形状，故使其得名棺材板。也有店家为讨彩头改称其为官财板，不过食客们完全没必要被名字吓到，棺材板这道菜不但好吃还有趣，它最大的特点在于创造了鸡肝的新吃法，既融合了中式与西式两种风格，酥脆与浓稠两种口感，与此同时又相容了甜与咸两种味道，也不失鸡与虾两种食材的鲜味，在品尝时既可以一勺浓汤、一勺面包的品尝，也可以一勺下去，连带面包与浓汤一起食用，味道独具一格，吃法其乐无穷，令人流连忘返。"
  },
  [208] = {
    order = 208,
    id = 628,
    desc = "柠檬爱玉",
    open = 1,
    atkSpeed = 4,
    hp = 2,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "未定",
    cv1 = "暂无",
    desc = "随着珍珠奶茶等手摇饮料兴起，五花八门的饮品配料开始走入人们的视野，大家一定都很熟悉由木薯粉制成的珍珠、芋圆，但会对爱玉这个名字感到陌生吧？所谓的爱玉冻是一种由桑科榕属植物爱玉子提炼出的果胶制成的果冻状食品，它的口感类似于仙草，但要更加Q弹且略带果味，因此爱玉冻非常适合与果汁一起做成冰饮。\n柠檬爱玉便是新鲜的爱玉冻配以柠檬水、蜂蜜或糖浆制成的果味饮品，它那澄澈的柠檬色汁水中漂浮着透亮的爱玉果冻，酸甜的味道配上充实的口感，绝对是夏日解暑降温的最佳选择之一。如果你想要在家试作它的话需要先准备约1500克的爱玉子，下锅后按一比六十的比例加水捣碎搅拌，析出爱玉果肉内的果胶物质，再在筛去残渣后置入冰箱低温层结冻处理。此时架锅熬制果汁，加入蜂蜜、糖浆及香料调味，待果胶完全凝结后将其放入其中便大功告成，可以与朋友一起畅快享用了。"
  },
  [209] = {
    order = 209,
    id = 630,
    desc = "芒果沙冰",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "Ahchii",
    cv1 = "暂无",
    desc = "芒果沙冰作为夏日中冰品店的常见冰品为人熟知。通常的做法为：将芒果去皮去核后，将果肉放入冰箱中冷冻一段时间后取出，于搅拌机中打成沙状，便可直接食用了。视个人情况，也可以添加些牛奶或者砂糖来调节味道。由于原材料就是整颗芒果，所以芒果沙冰在冰品当中算是营养价值较为丰富的，同时做法又相当简单，这也让芒果沙冰成为了既健康又便捷的夏日解暑佳品。"
  },
  [210] = {
    order = 210,
    id = 631,
    desc = "赫斯提亚",
