    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "贺崽Load",
    cv1 = "加隈亚衣",
    desc = "身为奥林匹斯山上最神圣、最古老的神明，有着显赫地位的赫斯提亚反而对力量毫无兴趣。\n疲于应付诸神追求的她向宙斯要了主掌人家所有家灶的权力，于是她的日常便是坐在木制的宝座上，沏上一杯红茶，观察人类的生活。\n最喜欢的问题是“今天吃什么？”最讨厌的问题是……有关于年龄的一切哦！"
  },
  [211] = {
