    painter = "cyyyyy",
    cv1 = "暂无",
    desc = "将生姜和砂糖、柠檬汁等一起混合，发酵产生的饮料是姜汁苏打饮……并不是。姜汁苏打饮是以姜汁为原料制作的含有生姜成分的碳酸饮料。发酵生姜的饮料被称为姜汁饮料。从发酵生姜的工序来看，起源的姜汁多多少少含有酒精。另外，生姜是浓缩了甜辣味的饮料，有时还会加入辣椒，因此作为饮料来说，生姜具有很强的刺激性。与此相反，姜汁苏打饮不含酒精，味道也更温和，保留了生姜风味的特点，成为更容易被大众接受的饮料。虽然英国人发明了“姜汁啤酒”，但“姜汁苏打饮”是加拿大人发明的，并迅速扩散到世界各地。在现代的日本也广受欢迎，很多人即使不喜欢生姜的味道和香味，也喜欢姜汁苏打饮的甜辣味道。"
  },
  [212] = {
    order = 212,
    id = 626,
    desc = "甜酒",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 3,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "XC",
    cv1 = "暂无",
    desc = "作为日本传统甜味饮料的甜酒，根据制作方法大体上分为两大类。一类是在水和米中加入米曲进行发酵后而成的甜酒，一类是将酒糟溶于水中，而后在其中加入砂糖而制成的甜酒。其中，前者的原型可以追溯到一千多年前的古坟时代，在当时被称为「一夜酒」而为人所知。现在的甜酒一般是在正月时才喝的，然而江户时代的甜酒则被称为夏日的风景诗。用来指代甜酒的「一夜酒」一词则成为了夏日俳句的季语。即便是在现代，甜酒也因为其营养丰富而被称为「可以喝的点滴」，尤其是在人们营养状态普遍不如现代的过去，在身体容易感到疲劳的夏天喝甜酒可谓是相当普遍的一种做法。虽然被称为「酒」，但甜酒中的酒精成分其实相当少，连小孩子喝都不会有什么问题。即便不是正月，也可以一边补充营养，一边感受这传承自古代的甘甜。"
  },
  [213] = {
    order = 213,
    id = 632,
    desc = "月汐",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 1,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "千良&十七喵",
    cv1 = "张惠霖",
    desc = "冰冻星古老家族伊洛斯皇女，小月汐出生就已经注定她不凡的能力，果冻冰剑是她的绝对实力。父母寄希望于她，期望她能带领伊洛斯走向顶端，登上王位。小月汐从小就接受精英式培育，在这种环境下，小月汐早早就懂得了利益权谋。\n随着R实验的爆发，冰雪星王位的空缺，越发动荡的局势使得其他家族蠢蠢欲动，各家族间陷入自相斗争，暴徒乘虚而入，整个冰雪星一片混乱；身为伊洛斯皇女，父母将她送往皇家学院学习。\n月汐清楚自己需要面对的是什么，稍有不慎就是万劫不复，她越发努力学习，训练。在学院的她虽然外表冰冷，实际也有温柔的一面，因为只专心于学习，对流行的东西总是毫不在意，和妖炽聊天中没少被调笑。\n在学院的生活似乎没有想象中的平静，月汐被其他家族排挤孤立，但是月汐觉得无所谓，一直本着低调的她通常会选择无视或者暗地里回击回去；她清楚守护组在星系的重要地位，加入守护组势在必行。\n净化星球是月汐成为守护组组长的重要转折，靠着强硬的手段净化一波波的病毒污染。出色的能力让她成功上任守护组组长。月汐很清楚，一旦用出守护组这张王牌，她将肩负起守护冰雪星的职责，成为冰雪星第一位女王。\n在混乱的局势里，拥有强大实力的月汐成为唯一符合王位的人。月汐成功继任冰雪王位，受冰雪之礼；在月汐的领导下，击溃暴徒，重整秩序，使原本混乱不堪的星球得到洗礼。\n月汐接受着子民的瞩目和崇拜，同时在这片不知何时才能休止的绝望中成为守护他们的剑和盾。是什么？是一个星球的主宰？一个星球的意志？一个星球的象征？这些答案或许都对，但也有可能全是错误的。——只有身为王的人，才有资格回答这个问题。也只有真正的王，她的所做作为才是那个“正确答案”。"
  },
  [214] = {
    order = 214,
    id = 633,
    desc = "霁华",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 2,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "酸奶",
    cv1 = "云鹤追",
    desc = "霁华是在冰雪星一个叫云村的地方出生的，她的母亲对她极其喜爱，将刻着云纹的戒指送给了她。霁华在云村无忧无虑的生活——如果非要说烦恼的话，大概就读书不注意姿势而戴上的眼镜了吧。\n霁华特别喜欢读书，她知道云村原来是云之国的遗民所建，而她和母亲都是纯正的云国皇室血脉。时光流逝，村子里的书已经无法满足霁华的求知欲，她开始去镇子上的书馆，在那里，她遇到了一个神秘的知音，她与其畅所欲言……\n平淡的生活结束于一个冬夜，霁华从镇上的书馆回来，云村的人却已被尽数屠杀！原来是伊洛斯偏执的王后，认为蔓延冰雪星的海胆病毒是来自云国遗民的诅咒，将云之村的村民屠尽。于是霁华与神秘人交易，隐姓埋名，怀着满心恨意，进入皇宫，成为了长公主的贴身侍女。\n在霁华的刻意为之下，她与长公主建立了深厚的情谊，温柔沉默的长公主珍惜和她的友谊，为她在王宫栽满了她喜欢的霜花。在王后去世后，长公主登基为王，亲自提拔她作为冰雪星首席执政官。\n霁华永远也忘不了，她从镇上书馆回来，看到冰冷的霜花绽放于村民的血泊之中的愤怒与无助……她发过誓，要伊洛斯王族及其拥护者血债血偿！可是……为什么那位年轻的女王，有着那样温柔的眼睛……\n——“陛下，我见不得谁哄我，谁哄我，我就会忍不住觉得自己受了天大的委屈，反而更难过。”\n——“那我偷偷哄你。”\n——“不让你看见。”\n一切尘埃落定，霁华隐匿归乡，却在故乡看到了挂起的云灯，繁灯照亮村后墓碑上刻着的每一个死者的真名，黎明渐至，流浪于外的孤魂，至此安息。那位温柔的女王，终是给了满村冤魂，一个沉默而情深的交代。"
  },
  [215] = {
    order = 215,
    id = 637,
    desc = "留姬",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 1,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "血族",
    cv1 = "暂无",
    desc = "留姬，来自远方的神秘少女，安静，沉稳。\n她是那么讨厌聒噪，喜欢寂静，住在偏远又不方便的角落。\n她的笑容就像她用错符咒的次数那样稀少。\n留姬和所有人都相处很好，这意味着没有人能轻易接近她的心。\n每次主厨穿过一小段林子，才能走近留姬的住所。\n这时候，吵闹一点也是可以的。\n因为留姬望着主厨笑了，她的符咒用错了。\n众鸟啾啾，飞越过丛林，前往还染着灿烂云霞的远方。\n不知道为什么，留姬会想起她从未到过的避世之地。\n……也许，次元小屋，也可以算是她的避世之地吧。"
  },
  [216] = {
    order = 216,
    id = 635,
    desc = "薇尔丹蒂",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 3,
    miss = 1,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "朝露",
    cv1 = "花守ゆみり",
    desc = "提雅芬妮亚教会魔导炉工程的两个产物之一，世界上所有魔导器的源头——魔导人偶，体内藏着无数强大的魔导机关，本质来说就是人形的魔导器。\n在另一名人太人偶发动叛乱，教会认定计划失败后，被软禁在地下庭院数百年，最后被好友法拉救出。然而就在救出的当日，薇尔丹蒂与法拉遭遇了星灾，法拉下落不明，薇尔丹蒂将自己装在时钟箱内，辗转五百年后，被薇琪发现。\n\n来自五百年前魔工时代的神秘少女，不仅懂得术士，还能为魔导器充能，实力让人惊叹。\n重度甜食控，最爱的是巧克力。只要能得到巧克力就能轻易改变心意。\n有时很难察觉她的心意，经常对薇琪和安西娅的愚蠢行为放任不顾，声称要观察人类行为，让伙伴们十分头痛。\n十分擅长处理古代机关，体内所藏的秘密似乎比所有人想象中还要多。"
  },
  [217] = {
    order = 217,
    id = 634,
    desc = "干红",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 6,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "漫道",
    cv1 = "暂无",
    desc = "　　干红葡萄酒，自然是葡萄酒的其中一类。它在大约公元前1000年到前500年之间在法国南部出现，而后它开始在地中海盆地的大部分地区进行繁衍传播。早期，这种饮料一直被视认是一种只有贵族才能享用的高尚饮品，也是一种用来敬拜酒神巴克斯（Bacchus）的祭神用品。同时，它在基督教徒心目中，也是耶稣基督的血液。\n　　葡萄酒的成分很简单，它是经由自然发酵酿造出来的果酒，含有最多的当然是葡萄汁，至少占80%的比例以上，其次就是经葡萄里面的糖份自然发酵而成的酒精，一般在10%至30%，剩余的营养物质超过1000种，比较重要的有300多种，有酒石酸，果胶，矿物质和单宁酸等。虽然这些物质所占的比例不高，却能决定一整瓶红酒的优劣——就像魔法一样，只有各个元素的比例均衡，才能做出最完美的效果。\n　　红酒在无论是在餐桌上，还是在酒吧里，都是颇受青睐的明星饮品，这离不开红酒本身甘醇的味道，自然也离不开它本身神秘而优雅的气质。所以，来端上一杯红酒，享受这片刻的奢华吧。"
  },
  [218] = {
    order = 218,
    id = 636,
    desc = "开水白菜",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 6,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "赤赤水",
    cv1 = "暂无",
    desc = "　　开水白菜，这可是一道有名的国宴精品了，尽管它有一个十分简单的名字，却有非常不得了的内涵。\n　　开水白菜的极致秘密，就在那一碗汤里。\n　　开水，其实是至清的鸡汤。此汤要用老母鸡、老母鸭、火腿蹄肉、排骨、干贝等食材分别去杂入沸锅，加入料酒、葱蒜等调味品调制至少4小时，再将鸡胸脯肉剁烂至茸，灌以鲜汤搅成浆状，倒入锅中吸附杂质。反复吸附两三次之后，锅中原本略浊的鸡汤此刻呈开水般透彻清冽之状，香味浓醇敦厚，不油不腻，沁人心脾。\n　　而白菜则要选取将熟未透的大白菜做原材，只选用当中发黄的嫩心，微焯之后用清水漂冷，去尽菜腥后再用“开水”状鸡汤淋浇至烫熟。烫过白菜的清汤当然要弃置不用，烫好的菜心垫入钵底，轻轻倒进新鲜的鸡汤，此菜才算成。成菜乍看清汤寡水，油星全无，但闻起来却香味扑鼻，吃在口中清鲜柔美，自然胜过那万般佳肴。\n　　所以，或许下次，你可以试试，在朋友家做客之前对他点出这道菜哦？要是这位朋友满口答应，可就不知道他到底是身怀绝技，还是麻烦临头了呢～"
  },
  [219] = {
    order = 219,
    id = 638,
    desc = "仰望星空派",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 5,
    phyDef = 2,
    hit = 1,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "朝露",
    cv1 = "朝露",
    desc = "仰望星空派，这道起源于英国康沃尔地区的传统料理，以其独特的造型著称——它不以美味见长，但造型极具辨识度。制作时，厨师会将整条鱼竖插在馅饼中，让鱼头和鱼尾露出馅饼表层，仿佛鱼正仰望星空，因此得名“仰望星空派”（Stargazy Pie）。派馅通常由沙丁鱼、洋葱、鸡蛋、奶油等食材制成，结合了海鲜的咸鲜与奶油的润滑，口感偏腥重，不易被普罗大众接受。\n尽管视觉上过于“独特”，仰望星空派的营养成分可谓相当丰富。派的主料鱼类富含优质蛋白、Omega-3脂肪酸以及维生素D等。此外，土豆的淀粉与纤维，洋葱的抗氧化物质相互配合，使得这一道传统英式料理适合长期食用，有助于人体健康。\n仰望星空派的诞生有其背景传说，相传在一场暴风雨之后，康沃尔小镇濒临粮食短缺，一位勇敢的渔夫冒险出海，成功捕获大批沙丁鱼，拯救了小镇饥荒。为了纪念这位渔夫，居民们制作了仰望星空派，象征渔夫凝望远方的大海。如今，这道菜在康沃尔的节日中会被端上餐桌，更多作为一种文化象征，而非美食享受。"
  },
  [220] = {
    order = 220,
    id = 639,
    desc = "青龙过江",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 6,
    phyDef = 2,
    hit = 1,
    miss = 2,
    growth = 5,
    skill = 5,
    formation = 5,
    painter = "朝露",
    cv1 = "朝露",
    desc = "青龙过江，这道菜乍听名字颇具气势，然而实际却是一道让人啼笑皆非的“黑暗料理”。它的做法简单到近乎随意：整根黄瓜未经任何处理直接入锅，与酱油和肉一同翻炒。待到黄瓜煮得软烂、颜色变得暗沉，便算大功告成。\n成品端上桌，黄瓜早已失去清脆，口感绵软甚至带些油腻，酱油的咸味盖过一切，肉片也沦为陪衬。整体风味不伦不类，既不像家常菜的质朴，也缺乏精致菜肴的层次感，可谓既毁食材，又毁胃口。\n尽管如此，这道菜因其独特的做法和戏剧性的呈现，偶尔也能成为饭桌上的笑点。“青龙过江”的名字虽堂皇，却与实际的落差形成了某种反差萌，令人哭笑不得。正是这种奇特的存在，让它在“黑暗料理”界中占据了一席之地——你可能不愿尝试第二次，但却永远忘不了它的名字。"
  },
  [221] = {
    order = 221,
    id = 640,
    desc = "凤鸣·冰糖燕窝",
    open = 1,
    atkSpeed = 4,
    hp = 1,
    atk = 6,
    phyDef = 2,
    hit = 3,
    miss = 2,
    growth = 5,
    skill = 6,
    formation = 5,
    painter = "朝露",
    cv1 = "朝露",
    desc = "?冰糖燕窝，中华滋补名品。?\n驰名中外的传统药膳食疗珍品，以东南亚金丝燕唾液筑巢形成的天然燕窝为主料，搭配冰糖文火慢炖而成。冰镇后口感清凉滑润如凝脂，温热享用则绵密柔润似绸缎。\n制作时需要精选干燕窝用纯净水浸泡4-8小时，期间多次换水并镊除细小燕毛，撕成丝状后以80℃以下水温隔水炖煮1小时，避免高温破坏唾液酸活性。可搭配枸杞、红枣等辅料增强滋补功效，冰糖需在炖煮后期加入以防甜味掩盖燕窝本味。\n虽顶级燕窝产自印尼、马来等南洋之地，但「食燕文化」根植华夏——元末明初通过海上丝绸之路传入，清朝时与鲍参翅肚并称「参翅八珍」，成为宫廷御膳与贵族宴席的身份象征。\n中医理论中，燕窝性平味甘，具滋阴润肺、养颜美容之效，《本草逢原》记载其与冰糖配伍可调理虚劳咳喘。\n广州及东南亚华人社群中，冰糖燕窝仍是婚宴寿席的压轴甜点，顶级官燕盏炖制的琥珀色汤汁，凭借丝滑胶质与清甜回甘的独特口感，成就「一口千金」的饮食美学。"
  }
}
